import React, { useState, useMemo, useEffect, useRef } from 'react';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
import { useData } from '../context/DataContext';
import { 
    Play, Pause, RotateCcw, PartyPopper, ArrowLeft, 
    Check, X, BookOpen, Utensils, CheckSquare, Clock, ChevronRight,
    Users, Plus, Minus, Timer, CircleDot, ChevronDown, ListChecks,
    Lock, AlertCircle
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '../lib/utils';

const CompactTimer: React.FC<{ timeLeft: number; totalTime: number; isRunning: boolean; onToggle: () => void; onReset: () => void; }> = ({ timeLeft, totalTime, isRunning, onToggle, onReset }) => {
    const progress = totalTime > 0 ? timeLeft / totalTime : 0;
    const formatTime = (s: number) => `${Math.floor(s / 60)}:${(s % 60).toString().padStart(2, '0')}`;

    return (
        <div className="flex flex-col items-center bg-card border border-border/50 p-4 md:p-6 rounded-2xl shadow-sm w-full">
             <div className="relative h-28 w-28 md:h-36 md:w-36 flex items-center justify-center mb-4">
                 <svg className="absolute inset-0 transform -rotate-90 w-full h-full">
                    <circle cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="3" className="text-muted/5" />
                    <motion.circle
                        cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="4" strokeLinecap="round"
                        initial={{ strokeDashoffset: 400 }}
                        animate={{ strokeDashoffset: 400 - (400 * progress) }}
                        transition={{ duration: 0.5, ease: "linear" }}
                        style={{ strokeDasharray: 400 }}
                        className="text-primary"
                    />
                </svg>
                <div className="flex flex-col items-center">
                    <span className="text-2xl md:text-3xl font-black tabular-nums tracking-tighter text-foreground">{formatTime(timeLeft)}</span>
                    <span className="text-[8px] font-black uppercase text-muted-foreground tracking-widest">Running</span>
                </div>
             </div>
             <div className="flex gap-2 w-full max-w-[280px]">
                <button 
                    onClick={onReset} 
                    className="w-10 h-10 rounded-lg bg-muted/50 hover:bg-muted text-muted-foreground flex items-center justify-center transition-all active:scale-90 border border-border/40"
                    title="Reset Timer"
                >
                    <RotateCcw className="h-4 w-4"/>
                </button>
                <button 
                    onClick={onToggle} 
                    className={cn(
                        "flex-1 h-10 rounded-lg font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all shadow-sm", 
                        isRunning 
                            ? "bg-red-50 text-red-600 border border-red-100" 
                            : "bg-primary text-white shadow-primary/20 hover:brightness-105"
                    )}
                >
                    {isRunning ? <Pause className="h-4 w-4"/> : <Play className="h-4 w-4 fill-current"/>}
                    <span>{isRunning ? 'Stop' : 'Start'}</span>
                </button>
             </div>
        </div>
    );
};

export default function CookingModePage() {
    const { recipeId } = useParams<{ recipeId: string }>();
    const [searchParams] = useSearchParams();
    const initialServings = searchParams.get('servings') ? parseInt(searchParams.get('servings')!) : 1;
    const { getRecipeById } = useData();
    const navigate = useNavigate();
    const recipe = getRecipeById(recipeId || '');

    const activeStepRef = useRef<HTMLDivElement>(null);

    const [currentStepIndex, setCurrentStepIndex] = useState(0);
    const [localServings, setLocalServings] = useState(initialServings);
    const [isFinished, setIsFinished] = useState(false);
    const [timeLeft, setTimeLeft] = useState(0);
    const [isTimerRunning, setIsTimerRunning] = useState(false);
    const [completedIngs, setCompletedIngs] = useState<Set<string>>(new Set());

    const steps = recipe?.steps || [];
    const scaleFactor = recipe ? localServings / recipe.servings : 1;

    const currentStepIngredients = useMemo(() => {
        if (!recipe) return [];
        const currentStepData = steps[currentStepIndex];

        if (currentStepData?.linkedIngredientIds && currentStepData.linkedIngredientIds.length > 0) {
            const allIngredients = recipe.ingredientSections.flatMap(s => s.ingredients);
            return allIngredients.filter(ing => currentStepData.linkedIngredientIds!.includes(ing.id));
        }

        const stepNum = currentStepData?.stepNumber || (currentStepIndex + 1);
        return recipe.ingredientSections[stepNum - 1]?.ingredients || [];
    }, [recipe, currentStepIndex, steps]);

    const isCurrentStepTasksCompleted = useMemo(() => {
        if (currentStepIngredients.length === 0) return true;
        return currentStepIngredients.every(ing => completedIngs.has(ing.id));
    }, [currentStepIngredients, completedIngs]);

    useEffect(() => {
        if (steps[currentStepIndex]?.duration) {
            setTimeLeft(steps[currentStepIndex].duration! * 60);
        } else {
            setTimeLeft(0);
        }
        setIsTimerRunning(false);

        activeStepRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, [currentStepIndex, steps]);

    useEffect(() => {
        let interval: any;
        if (isTimerRunning && timeLeft > 0) {
            interval = setInterval(() => setTimeLeft(p => p - 1), 1000);
        } else if (timeLeft === 0) {
            setIsTimerRunning(false);
        }
        return () => clearInterval(interval);
    }, [isTimerRunning, timeLeft]);

    const toggleIngredient = (id: string) => {
        setCompletedIngs(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    if (!recipe) return null;

    if (isFinished) {
        return (
            <div className="fixed inset-0 bg-background z-[200] flex items-center justify-center p-4 font-sans">
                <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="max-w-md w-full bg-card p-8 rounded-2xl border border-border shadow-2xl text-center">
                    <div className="h-16 w-16 bg-primary/10 text-primary rounded-full flex items-center justify-center mx-auto mb-6">
                        <PartyPopper className="h-8 w-8" />
                    </div>
                    <h1 className="text-2xl font-black text-foreground mb-2 tracking-tight">SERVICE COMPLETE</h1>
                    <p className="text-sm text-muted-foreground mb-8 font-medium leading-relaxed uppercase tracking-tight">{recipe.name} IS READY FOR PLATING.</p>
                    <button onClick={() => navigate(`/recipes/${recipeId}`)} className="w-full py-4 bg-primary text-white rounded-xl font-black text-[10px] uppercase tracking-[0.2em] shadow-lg hover:brightness-105 active:scale-[0.99] transition-all">Back to Recipe</button>
                </motion.div>
            </div>
        );
    }

    return (
        <div className="fixed inset-0 bg-background z-[150] flex flex-col font-sans overflow-hidden">
            {/* Header */}
            <div className="bg-card/95 border-b border-border/40 h-14 md:h-16 flex items-stretch sticky top-0 z-30 shadow-sm">
                <div className="w-1/2 flex items-center px-2 md:px-6 border-r border-border/40">
                    <button onClick={() => navigate(-1)} className="p-1.5 hover:bg-muted rounded-lg transition-all active:scale-90 mr-1 md:mr-3">
                        <ArrowLeft className="h-4 w-4 text-muted-foreground"/>
                    </button>
                    <div className="min-w-0">
                        <h2 className="text-[10px] md:text-xs font-black text-foreground tracking-tight truncate uppercase leading-tight">{recipe.name}</h2>
                        <div className="flex items-center gap-1 mt-0.5">
                            <span className="text-[7px] md:text-[8px] font-black uppercase text-primary tracking-widest bg-primary/10 px-1 py-0.5 rounded leading-none">Step {currentStepIndex + 1}</span>
                            <span className="text-[7px] text-muted-foreground font-bold uppercase tracking-widest hidden xs:inline">({currentStepIndex + 1}/{steps.length})</span>
                        </div>
                    </div>
                </div>

                <div className="w-1/2 flex items-center justify-center px-2 md:px-8">
                    <div className="flex items-center justify-between w-full max-w-[160px] bg-muted/20 p-0.5 rounded-xl border border-border/40">
                        <button 
                            onClick={() => setLocalServings(Math.max(1, localServings - 1))}
                            className="h-8 w-8 md:h-9 md:w-9 rounded-lg bg-white dark:bg-zinc-800 shadow-sm border border-border/50 flex items-center justify-center text-muted-foreground hover:text-primary transition-all active:scale-90"
                        >
                            <Minus className="h-3 w-3" strokeWidth={3} />
                        </button>

                        <div className="flex flex-col items-center">
                            <div className="flex items-baseline gap-0.5">
                                <span className="text-sm md:text-base font-black tabular-nums text-foreground">{localServings}</span>
                                <Users className="h-2 w-2 text-muted-foreground/40" />
                            </div>
                            <span className="text-[6px] md:text-[7px] font-black uppercase text-muted-foreground tracking-widest leading-none">Servings</span>
                        </div>

                        <button 
                            onClick={() => setLocalServings(localServings + 1)}
                            className="h-8 w-8 md:h-9 md:w-9 rounded-lg bg-primary shadow-md shadow-primary/10 flex items-center justify-center text-white transition-all active:scale-90"
                        >
                            <Plus className="h-3 w-3" strokeWidth={3} />
                        </button>
                    </div>
                </div>
            </div>

            <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
                {/* Method Sequence Timeline - Focus on Active Step */}
                <div className="w-full md:w-3/5 overflow-y-auto p-4 md:p-6 md:border-r border-border/40 scrollbar-hide">
                    <div className="max-w-2xl mx-auto space-y-6 pb-20">
                        <div className="flex items-center gap-2 mb-4 px-1">
                            <ListChecks className="h-4 w-4 text-primary" />
                            <h3 className="text-[10px] md:text-[11px] font-black uppercase tracking-[0.25em] text-muted-foreground">Active Instruction</h3>
                            <div className="h-px flex-1 bg-border/30"></div>
                        </div>

                        <div className="space-y-4">
                            <AnimatePresence mode="wait">
                                {steps.map((step, idx) => {
                                    const isActive = currentStepIndex === idx;
                                    const isDone = currentStepIndex > idx;
                                    const isFuture = currentStepIndex < idx;

                                    if (!isActive && !isDone) return null; // Show current and past steps only

                                    return (
                                        <motion.div 
                                            key={step.id}
                                            ref={isActive ? activeStepRef : null}
                                            initial={isActive ? { scale: 0.98, opacity: 0 } : false}
                                            animate={{ scale: 1, opacity: 1 }}
                                            className={cn(
                                                "relative group p-4 md:p-6 rounded-2xl border transition-all select-none",
                                                isActive 
                                                    ? "bg-card border-primary shadow-xl ring-4 ring-primary/5 z-10" 
                                                    : "bg-muted/10 border-border opacity-50 grayscale"
                                            )}
                                        >
                                            <div className="flex gap-4">
                                                <div className="flex flex-col items-center shrink-0">
                                                    <div className={cn(
                                                        "h-8 w-8 rounded-full border-2 flex items-center justify-center transition-all",
                                                        isActive ? "bg-primary border-primary text-white scale-110" : "bg-background border-border text-muted-foreground"
                                                    )}>
                                                        {isDone ? <Check className="h-4 w-4" strokeWidth={3} /> : <span className="text-[10px] font-black">{idx + 1}</span>}
                                                    </div>
                                                </div>

                                                <div className="flex-1 min-w-0">
                                                    {isActive && (
                                                        <div className="flex items-center gap-2 mb-2">
                                                            <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse"></span>
                                                            <span className="text-[8px] font-black text-primary uppercase tracking-[0.2em]">Current Mission</span>
                                                        </div>
                                                    )}
                                                    <p className={cn(
                                                        "font-bold leading-relaxed transition-all uppercase tracking-tight",
                                                        isActive ? "text-base md:text-xl text-foreground" : "text-sm text-muted-foreground",
                                                        isDone && "line-through"
                                                    )}>
                                                        {step.instruction}
                                                    </p>
                                                    {step.duration && (
                                                        <div className={cn(
                                                            "mt-2 inline-flex items-center gap-1 px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest",
                                                            isActive ? "bg-primary/10 text-primary" : "bg-muted text-muted-foreground"
                                                        )}>
                                                            <Clock className="h-2.5 w-2.5" /> {step.duration} Min
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </motion.div>
                                    );
                                })}
                            </AnimatePresence>

                            {/* Future steps placeholder */}
                            {currentStepIndex < steps.length - 1 && (
                                <div className="p-6 rounded-2xl border border-dashed border-border/40 bg-muted/5 flex flex-col items-center justify-center gap-2 opacity-40">
                                    <Lock className="h-5 w-5 text-muted-foreground" />
                                    <span className="text-[9px] font-black uppercase tracking-widest">Next Step Locked</span>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Sidebar Controls */}
                <div className="w-full md:w-2/5 overflow-y-auto p-4 md:p-6 bg-muted/5 scrollbar-hide">
                    <div className="max-w-md mx-auto space-y-6">
                        {/* Timer Section */}
                        <div className="animate-in fade-in slide-in-from-right duration-300">
                            <div className="flex items-center gap-2 mb-3 px-1">
                                <Timer className="h-3 w-3 text-muted-foreground" />
                                <h3 className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.25em] text-muted-foreground">Process Timer</h3>
                                <div className="h-px flex-1 bg-border/30"></div>
                            </div>
                            {steps[currentStepIndex]?.duration ? (
                                <CompactTimer 
                                    timeLeft={timeLeft} 
                                    totalTime={steps[currentStepIndex].duration! * 60} 
                                    isRunning={isTimerRunning} 
                                    onToggle={() => setIsTimerRunning(!isTimerRunning)} 
                                    onReset={() => setTimeLeft(steps[currentStepIndex].duration! * 60)} 
                                />
                            ) : (
                                <div className="bg-card border border-dashed border-border p-8 rounded-2xl w-full flex flex-col items-center text-muted-foreground/30">
                                    <Clock className="h-8 w-8 mb-2" />
                                    <span className="text-[8px] font-black uppercase tracking-widest">Manual Control</span>
                                </div>
                            )}
                        </div>

                        {/* Step Ingredients Section */}
                        <div className="animate-in fade-in slide-in-from-right duration-500">
                            <div className="flex items-center justify-between mb-3 px-1">
                                <div className="flex items-center gap-2">
                                    <Utensils className="h-3 w-3 text-muted-foreground" />
                                    <h3 className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.25em] text-muted-foreground">Required Assets</h3>
                                </div>
                                <span className={cn(
                                    "text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded border transition-colors",
                                    isCurrentStepTasksCompleted ? "bg-emerald-50 text-emerald-600 border-emerald-200" : "bg-primary/5 text-primary border-primary/10"
                                )}>
                                    {completedIngs.size} / {currentStepIngredients.length} Verified
                                </span>
                            </div>

                            <div className="bg-card rounded-2xl border border-border shadow-sm overflow-hidden divide-y divide-border/40">
                                {currentStepIngredients.length > 0 ? (
                                    currentStepIngredients.map((ing, idx) => {
                                        const isDone = completedIngs.has(ing.id);
                                        return (
                                            <div 
                                                key={ing.id} 
                                                onClick={() => toggleIngredient(ing.id)}
                                                className={cn(
                                                    "group flex items-center gap-3 p-3 md:p-4 transition-all cursor-pointer select-none",
                                                    isDone ? "bg-emerald-50/20" : "hover:bg-muted/30"
                                                )}
                                            >
                                                <div className={cn(
                                                    "w-8 h-8 rounded-lg border flex items-center justify-center transition-all shrink-0",
                                                    isDone 
                                                        ? "bg-emerald-500 border-emerald-500 text-white" 
                                                        : "border-border bg-muted/5 text-muted-foreground"
                                                )}>
                                                    {isDone ? <Check className="h-4 w-4 stroke-[4]" /> : <span className="text-[10px] font-black">{idx + 1}</span>}
                                                </div>

                                                <div className="flex-1 min-w-0">
                                                    <p className={cn("text-xs md:text-sm font-bold truncate leading-none transition-all uppercase tracking-tight", isDone && "line-through text-muted-foreground/60")}>{ing.name}</p>
                                                    <div className="flex items-center gap-1.5 mt-1">
                                                        <span className="text-[9px] md:text-[10px] font-black text-primary uppercase tracking-wider">
                                                            {(ing.quantity * scaleFactor).toFixed(1)} {ing.unit}
                                                        </span>
                                                        {ing.type && <span className="text-[8px] text-muted-foreground font-black uppercase tracking-widest opacity-40">&bull; {ing.type}</span>}
                                                    </div>
                                                </div>

                                                <div className={cn("h-5 w-5 rounded-md flex items-center justify-center transition-all", isDone ? "bg-emerald-100 text-emerald-600" : "bg-muted text-muted-foreground/20")}>
                                                    <CheckSquare className="h-3.5 w-3.5" />
                                                </div>
                                            </div>
                                        );
                                    })
                                ) : (
                                    <div className="p-8 text-center text-muted-foreground/40 flex flex-col items-center gap-2">
                                        <BookOpen className="h-8 w-8 opacity-20" />
                                        <p className="text-[8px] font-black uppercase tracking-[0.3em]">Manual Execution Only</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Sticky Navigation Footer */}
            <div className="bg-card border-t border-border h-16 md:h-20 flex items-center px-4 md:px-8 shadow-2xl z-40">
                <div className="max-w-4xl mx-auto w-full flex items-center justify-between gap-3">
                    <button 
                        disabled={currentStepIndex === 0}
                        onClick={() => setCurrentStepIndex(c => c - 1)}
                        className="h-10 md:h-12 px-4 rounded-xl border border-border flex items-center gap-2 hover:bg-muted disabled:opacity-10 transition-all active:scale-90 shadow-sm"
                    >
                        <ArrowLeft className="h-4 w-4 text-foreground" />
                        <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">Back</span>
                    </button>

                    <div className="flex-1 flex flex-col items-center gap-2 max-w-xs">
                        <div className="flex items-center gap-1 h-1.5 w-full bg-muted/40 rounded-full overflow-hidden">
                            {steps.map((_, i) => (
                                <div 
                                    key={i} 
                                    className={cn(
                                        "h-full transition-all duration-500",
                                        i === currentStepIndex ? "flex-[4] bg-primary" : i < currentStepIndex ? "flex-1 bg-primary/40" : "flex-1 bg-muted"
                                    )}
                                />
                            ))}
                        </div>
                        <div className="flex items-center gap-2">
                             {!isCurrentStepTasksCompleted && (
                                <span className="flex items-center gap-1 text-[7px] font-black uppercase text-amber-600 tracking-widest animate-pulse">
                                    <AlertCircle className="h-2.5 w-2.5" /> Verify Assets
                                </span>
                             )}
                             <span className="text-[8px] font-black uppercase text-foreground tracking-[0.2em]">Flow: {Math.round(((currentStepIndex + 1)/steps.length) * 100)}%</span>
                        </div>
                    </div>

                    <button 
                        disabled={!isCurrentStepTasksCompleted}
                        onClick={() => currentStepIndex === steps.length - 1 ? setIsFinished(true) : setCurrentStepIndex(c => c + 1)}
                        className={cn(
                            "h-10 md:h-12 px-6 md:px-10 rounded-xl font-black text-[10px] md:text-xs uppercase tracking-[0.2em] flex items-center gap-2 transition-all active:scale-[0.98] shadow-lg disabled:opacity-50 disabled:grayscale disabled:cursor-not-allowed", 
                            currentStepIndex === steps.length - 1 
                                ? "bg-emerald-600 text-white shadow-emerald-500/20" 
                                : "bg-primary text-white shadow-primary/20 hover:brightness-110"
                        )}
                    >
                        <span>{currentStepIndex === steps.length - 1 ? "Complete" : "Continue"}</span>
                        {isCurrentStepTasksCompleted ? <ChevronRight className="h-4 w-4" /> : <Lock className="h-3.5 w-3.5" />}
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
import { useData } from '../context/DataContext';
import { 
    Play, Pause, RotateCcw, PartyPopper, ArrowLeft, 
    Check, X, BookOpen, Utensils, CheckSquare, Clock, ChevronRight,
    Users, Plus, Minus, Timer, CircleDot, ChevronDown, ListChecks,
    Lock, AlertCircle, Box
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '../lib/utils';

const CompactTimer: React.FC<{ timeLeft: number; totalTime: number; isRunning: boolean; onToggle: () => void; onReset: () => void; }> = ({ timeLeft, totalTime, isRunning, onToggle, onReset }) => {
    const progress = totalTime > 0 ? timeLeft / totalTime : 0;
    const formatTime = (s: number) => `${Math.floor(s / 60)}:${(s % 60).toString().padStart(2, '0')}`;

    return (
        <div className="flex flex-col items-center bg-card border border-border/50 p-4 md:p-6 rounded-2xl shadow-sm w-full">
             <div className="relative h-28 w-28 md:h-36 md:w-36 flex items-center justify-center mb-4">
                 <svg className="absolute inset-0 transform -rotate-90 w-full h-full">
                    <circle cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="3" className="text-muted/5" />
                    <motion.circle
                        cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="4" strokeLinecap="round"
                        initial={{ strokeDashoffset: 400 }}
                        animate={{ strokeDashoffset: 400 - (400 * progress) }}
                        transition={{ duration: 0.5, ease: "linear" }}
                        style={{ strokeDasharray: 400 }}
                        className="text-primary"
                    />
                </svg>
                <div className="flex flex-col items-center">
                    <span className="text-2xl md:text-3xl font-black tabular-nums tracking-tighter text-foreground">{formatTime(timeLeft)}</span>
                    <span className="text-[8px] font-black uppercase text-muted-foreground tracking-widest">Running</span>
                </div>
             </div>
             <div className="flex gap-2 w-full max-w-[280px]">
                <button 
                    onClick={onReset} 
                    className="w-10 h-10 rounded-lg bg-muted/50 hover:bg-muted text-muted-foreground flex items-center justify-center transition-all active:scale-90 border border-border/40"
                    title="Reset Timer"
                >
                    <RotateCcw className="h-4 w-4"/>
                </button>
                <button 
                    onClick={onToggle} 
                    className={cn(
                        "flex-1 h-10 rounded-lg font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all shadow-sm", 
                        isRunning 
                            ? "bg-red-50 text-red-600 border border-red-100" 
                            : "bg-primary text-white shadow-primary/20 hover:brightness-105"
                    )}
                >
                    {isRunning ? <Pause className="h-4 w-4"/> : <Play className="h-4 w-4 fill-current"/>}
                    <span>{isRunning ? 'Stop' : 'Start'}</span>
                </button>
             </div>
        </div>
    );
};

export default function CookingModePage() {
    const { recipeId } = useParams<{ recipeId: string }>();
    const [searchParams] = useSearchParams();
    const initialServings = searchParams.get('servings') ? parseInt(searchParams.get('servings')!) : 1;
    const { getRecipeById } = useData();
    const navigate = useNavigate();
    const recipe = getRecipeById(recipeId || '');

    const activeStepRef = useRef<HTMLDivElement>(null);

    const [currentStepIndex, setCurrentStepIndex] = useState(0);
    const [localServings, setLocalServings] = useState(initialServings);
    const [isFinished, setIsFinished] = useState(false);
    const [timeLeft, setTimeLeft] = useState(0);
    const [isTimerRunning, setIsTimerRunning] = useState(false);
    const [completedIngs, setCompletedIngs] = useState<Set<string>>(new Set());

    const steps = recipe?.steps || [];
    const scaleFactor = recipe ? localServings / recipe.servings : 1;

    const currentStepIngredients = useMemo(() => {
        if (!recipe) return [];
        const currentStepData = steps[currentStepIndex];

        if (currentStepData?.linkedIngredientIds && currentStepData.linkedIngredientIds.length > 0) {
            const allIngredients = recipe.ingredientSections.flatMap(s => s.ingredients);
            return allIngredients.filter(ing => currentStepData.linkedIngredientIds!.includes(ing.id));
        }

        const stepNum = currentStepData?.stepNumber || (currentStepIndex + 1);
        return recipe.ingredientSections[stepNum - 1]?.ingredients || [];
    }, [recipe, currentStepIndex, steps]);

    const isCurrentStepTasksCompleted = useMemo(() => {
        if (currentStepIngredients.length === 0) return true;
        return currentStepIngredients.every(ing => completedIngs.has(ing.id));
    }, [currentStepIngredients, completedIngs]);

    useEffect(() => {
        if (steps[currentStepIndex]?.duration) {
            setTimeLeft(steps[currentStepIndex].duration! * 60);
        } else {
            setTimeLeft(0);
        }
        setIsTimerRunning(false);

        activeStepRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, [currentStepIndex, steps]);

    useEffect(() => {
        let interval: any;
        if (isTimerRunning && timeLeft > 0) {
            interval = setInterval(() => setTimeLeft(p => p - 1), 1000);
        } else if (timeLeft === 0) {
            setIsTimerRunning(false);
        }
        return () => clearInterval(interval);
    }, [isTimerRunning, timeLeft]);

    const toggleIngredient = (id: string) => {
        setCompletedIngs(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    if (!recipe) return null;

    if (isFinished) {
        return (
            <div className="fixed inset-0 bg-background z-[200] flex items-center justify-center p-4 font-sans">
                <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="max-w-md w-full bg-card p-8 rounded-2xl border border-border shadow-2xl text-center">
                    <div className="h-16 w-16 bg-primary/10 text-primary rounded-full flex items-center justify-center mx-auto mb-6">
                        <PartyPopper className="h-8 w-8" />
                    </div>
                    <h1 className="text-2xl font-black text-foreground mb-2 tracking-tight">SERVICE COMPLETE</h1>
                    <p className="text-sm text-muted-foreground mb-8 font-medium leading-relaxed uppercase tracking-tight">{recipe.name} IS READY FOR PLATING.</p>
                    <button onClick={() => navigate(`/recipes/${recipeId}`)} className="w-full py-4 bg-primary text-white rounded-xl font-black text-[10px] uppercase tracking-[0.2em] shadow-lg hover:brightness-105 active:scale-[0.99] transition-all">Back to Recipe</button>
                </motion.div>
            </div>
        );
    }

    return (
        <div className="fixed inset-0 bg-background z-[150] flex flex-col font-sans overflow-hidden">
            {/* Header */}
            <div className="bg-card/95 border-b border-border/40 h-14 md:h-16 flex items-stretch sticky top-0 z-30 shadow-sm">
                <div className="w-1/2 flex items-center px-2 md:px-6 border-r border-border/40">
                    <button onClick={() => navigate(-1)} className="p-1.5 hover:bg-muted rounded-lg transition-all active:scale-90 mr-1 md:mr-3">
                        <ArrowLeft className="h-4 w-4 text-muted-foreground"/>
                    </button>
                    <div className="min-w-0">
                        <h2 className="text-[10px] md:text-xs font-black text-foreground tracking-tight truncate uppercase leading-tight">{recipe.name}</h2>
                        <div className="flex items-center gap-1 mt-0.5">
                            <span className="text-[7px] md:text-[8px] font-black uppercase text-primary tracking-widest bg-primary/10 px-1 py-0.5 rounded leading-none">Step {currentStepIndex + 1}</span>
                            <span className="text-[7px] text-muted-foreground font-bold uppercase tracking-widest hidden xs:inline">({currentStepIndex + 1}/{steps.length})</span>
                        </div>
                    </div>
                </div>

                <div className="w-1/2 flex items-center justify-center px-2 md:px-8">
                    <div className="flex items-center justify-between w-full max-w-[160px] bg-muted/20 p-0.5 rounded-xl border border-border/40">
                        <button 
                            onClick={() => setLocalServings(Math.max(1, localServings - 1))}
                            className="h-8 w-8 md:h-9 md:w-9 rounded-lg bg-white dark:bg-zinc-800 shadow-sm border border-border/50 flex items-center justify-center text-muted-foreground hover:text-primary transition-all active:scale-90"
                        >
                            <Minus className="h-3 w-3" strokeWidth={3} />
                        </button>

                        <div className="flex flex-col items-center">
                            <div className="flex items-baseline gap-0.5">
                                <span className="text-sm md:text-base font-black tabular-nums text-foreground">{localServings}</span>
                                <Users className="h-2 w-2 text-muted-foreground/40" />
                            </div>
                            <span className="text-[6px] md:text-[7px] font-black uppercase text-muted-foreground tracking-widest leading-none">Servings</span>
                        </div>

                        <button 
                            onClick={() => setLocalServings(localServings + 1)}
                            className="h-8 w-8 md:h-9 md:w-9 rounded-lg bg-primary shadow-md shadow-primary/10 flex items-center justify-center text-white transition-all active:scale-90"
                        >
                            <Plus className="h-3 w-3" strokeWidth={3} />
                        </button>
                    </div>
                </div>
            </div>

            <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
                {/* Method Sequence Timeline - Focus on Active Step */}
                <div className="w-full md:w-1/2 lg:w-3/5 overflow-y-auto p-4 md:p-6 md:border-r border-border/40 scrollbar-hide">
                    <div className="max-w-2xl mx-auto space-y-6 pb-20">
                        <div className="flex items-center gap-2 mb-4 px-1">
                            <ListChecks className="h-4 w-4 text-primary" />
                            <h3 className="text-[10px] md:text-[11px] font-black uppercase tracking-[0.25em] text-muted-foreground">Active Instruction</h3>
                            <div className="h-px flex-1 bg-border/30"></div>
                        </div>

                        <div className="space-y-4">
                            <AnimatePresence mode="wait">
                                {steps.map((step, idx) => {
                                    const isActive = currentStepIndex === idx;
                                    const isDone = currentStepIndex > idx;
                                    const isFuture = currentStepIndex < idx;

                                    if (!isActive && !isDone) return null; // Show current and past steps only

                                    return (
                                        <motion.div 
                                            key={step.id}
                                            ref={isActive ? activeStepRef : null}
                                            initial={isActive ? { scale: 0.98, opacity: 0 } : false}
                                            animate={{ scale: 1, opacity: 1 }}
                                            className={cn(
                                                "relative group p-4 md:p-6 rounded-2xl border transition-all select-none",
                                                isActive 
                                                    ? "bg-card border-primary shadow-xl ring-4 ring-primary/5 z-10" 
                                                    : "bg-muted/10 border-border opacity-50 grayscale"
                                            )}
                                        >
                                            <div className="flex gap-4">
                                                <div className="flex flex-col items-center shrink-0">
                                                    <div className={cn(
                                                        "h-8 w-8 rounded-full border-2 flex items-center justify-center transition-all",
                                                        isActive ? "bg-primary border-primary text-white scale-110" : "bg-background border-border text-muted-foreground"
                                                    )}>
                                                        {isDone ? <Check className="h-4 w-4" strokeWidth={3} /> : <span className="text-[10px] font-black">{idx + 1}</span>}
                                                    </div>
                                                </div>

                                                <div className="flex-1 min-w-0">
                                                    {isActive && (
                                                        <div className="flex items-center gap-2 mb-2">
                                                            <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse"></span>
                                                            <span className="text-[8px] font-black text-primary uppercase tracking-[0.2em]">Current Mission</span>
                                                        </div>
                                                    )}
                                                    <p className={cn(
                                                        "font-bold leading-relaxed transition-all uppercase tracking-tight",
                                                        isActive ? "text-base md:text-xl text-foreground" : "text-sm text-muted-foreground",
                                                        isDone && "line-through"
                                                    )}>
                                                        {step.instruction}
                                                    </p>
                                                    {step.duration && (
                                                        <div className={cn(
                                                            "mt-2 inline-flex items-center gap-1 px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest",
                                                            isActive ? "bg-primary/10 text-primary" : "bg-muted text-muted-foreground"
                                                        )}>
                                                            <Clock className="h-2.5 w-2.5" /> {step.duration} Min
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </motion.div>
                                    );
                                })}
                            </AnimatePresence>

                            {/* Future steps placeholder */}
                            {currentStepIndex < steps.length - 1 && (
                                <div className="p-6 rounded-2xl border border-dashed border-border/40 bg-muted/5 flex flex-col items-center justify-center gap-2 opacity-40">
                                    <Lock className="h-5 w-5 text-muted-foreground" />
                                    <span className="text-[9px] font-black uppercase tracking-widest">Next Step Locked</span>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                {/* Sidebar Controls */}
                <div className="w-full md:w-1/2 lg:w-2/5 overflow-y-auto p-4 md:p-6 bg-muted/5 scrollbar-hide">
                    <div className="max-w-4xl mx-auto space-y-8">
                        {/* Timer Section */}
                        <div className="animate-in fade-in slide-in-from-right duration-300">
                            <div className="flex items-center gap-2 mb-3 px-1">
                                <Timer className="h-3 w-3 text-muted-foreground" />
                                <h3 className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.25em] text-muted-foreground">Process Timer</h3>
                                <div className="h-px flex-1 bg-border/30"></div>
                            </div>
                            {steps[currentStepIndex]?.duration ? (
                                <CompactTimer 
                                    timeLeft={timeLeft} 
                                    totalTime={steps[currentStepIndex].duration! * 60} 
                                    isRunning={isTimerRunning} 
                                    onToggle={() => setIsTimerRunning(!isTimerRunning)} 
                                    onReset={() => setTimeLeft(steps[currentStepIndex].duration! * 60)} 
                                />
                            ) : (
                                <div className="bg-card border border-dashed border-border p-8 rounded-2xl w-full flex flex-col items-center text-muted-foreground/30">
                                    <Clock className="h-8 w-8 mb-2" />
                                    <span className="text-[8px] font-black uppercase tracking-widest">Manual Control</span>
                                </div>
                            )}
                        </div>

                        {/* Step Ingredients Section - Responsive Grid Layout */}
                        <div className="animate-in fade-in slide-in-from-right duration-500">
                            <div className="flex items-center justify-between mb-4 px-1">
                                <div className="flex items-center gap-2">
                                    <Utensils className="h-3 w-3 text-muted-foreground" />
                                    <h3 className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.25em] text-muted-foreground">Required Assets</h3>
                                </div>
                                <div className="flex items-center gap-2">
                                    <span className={cn(
                                        "text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded border transition-colors",
                                        isCurrentStepTasksCompleted ? "bg-emerald-50 text-emerald-600 border-emerald-200" : "bg-primary/5 text-primary border-primary/10"
                                    )}>
                                        {completedIngs.size} / {currentStepIngredients.length} Verified
                                    </span>
                                </div>
                            </div>

                            <div className={cn(
                                "grid gap-3 transition-all",
                                currentStepIngredients.length > 2 
                                    ? "grid-cols-1 sm:grid-cols-2 md:grid-cols-1 lg:grid-cols-2 xl:grid-cols-2" 
                                    : "grid-cols-1 sm:grid-cols-2 md:grid-cols-1 lg:grid-cols-2"
                            )}>
                                {currentStepIngredients.length > 0 ? (
                                    currentStepIngredients.map((ing, idx) => {
                                        const isDone = completedIngs.has(ing.id);
                                        return (
                                            <motion.div 
                                                key={ing.id} 
                                                layout
                                                onClick={() => toggleIngredient(ing.id)}
                                                className={cn(
                                                    "group relative flex items-start gap-3 p-3 md:p-4 rounded-xl border transition-all cursor-pointer select-none shadow-sm",
                                                    isDone 
                                                        ? "bg-emerald-50/40 border-emerald-200/60 dark:bg-emerald-900/10 dark:border-emerald-800/40" 
                                                        : "bg-card border-border/60 hover:border-primary/30 hover:bg-muted/10"
                                                )}
                                            >
                                                <div className={cn(
                                                    "w-8 h-8 rounded-lg border flex items-center justify-center transition-all shrink-0 mt-0.5",
                                                    isDone 
                                                        ? "bg-emerald-500 border-emerald-500 text-white shadow-lg shadow-emerald-500/20" 
                                                        : "border-border bg-muted/5 text-muted-foreground group-hover:bg-primary/5 group-hover:border-primary/20"
                                                )}>
                                                    {isDone ? <Check className="h-4 w-4 stroke-[4]" /> : <span className="text-[10px] font-black">{idx + 1}</span>}
                                                </div>

                                                <div className="flex-1 min-w-0">
                                                    <p className={cn(
                                                        "text-[11px] md:text-xs font-black truncate leading-tight transition-all uppercase tracking-tight", 
                                                        isDone ? "line-through text-muted-foreground/50" : "text-foreground"
                                                    )}>
                                                        {ing.name}
                                                    </p>
                                                    <div className="flex items-center gap-1.5 mt-1">
                                                        <span className={cn(
                                                            "text-[9px] md:text-[10px] font-black uppercase tracking-wider",
                                                            isDone ? "text-muted-foreground/60" : "text-primary"
                                                        )}>
                                                            {(ing.quantity * scaleFactor).toFixed(1)} {ing.unit}
                                                        </span>
                                                        {ing.type && (
                                                            <span className="text-[8px] text-muted-foreground/40 font-black uppercase tracking-widest">
                                                                &bull; {ing.type}
                                                            </span>
                                                        )}
                                                    </div>
                                                </div>

                                                <div className={cn(
                                                    "absolute top-3 right-3 h-5 w-5 rounded-md flex items-center justify-center transition-all opacity-0 group-hover:opacity-100", 
                                                    isDone ? "text-emerald-600 opacity-100" : "text-muted-foreground/20"
                                                )}>
                                                    <CheckSquare className="h-3.5 w-3.5" />
                                                </div>
                                            </motion.div>
                                        );
                                    })
                                ) : (
                                    <div className="col-span-full p-12 text-center text-muted-foreground/30 flex flex-col items-center gap-3 border border-dashed border-border/40 rounded-3xl bg-muted/5">
                                        <div className="h-12 w-12 rounded-full bg-muted/20 flex items-center justify-center">
                                            <BookOpen className="h-6 w-6 opacity-30" />
                                        </div>
                                        <div>
                                            <p className="text-[9px] font-black uppercase tracking-[0.3em]">Manual Execution</p>
                                            <p className="text-[8px] uppercase tracking-widest mt-1">No tracked assets for this phase</p>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Sticky Navigation Footer */}
            <div className="bg-card border-t border-border h-16 md:h-20 flex items-center px-4 md:px-8 shadow-2xl z-40">
                <div className="max-w-5xl mx-auto w-full flex items-center justify-between gap-3">
                    <button 
                        disabled={currentStepIndex === 0}
                        onClick={() => setCurrentStepIndex(c => c - 1)}
                        className="h-10 md:h-12 px-4 rounded-xl border border-border flex items-center gap-2 hover:bg-muted disabled:opacity-10 transition-all active:scale-90 shadow-sm"
                    >
                        <ArrowLeft className="h-4 w-4 text-foreground" />
                        <span className="text-[10px] font-black uppercase tracking-widest hidden sm:inline">Back</span>
                    </button>

                    <div className="flex-1 flex flex-col items-center gap-2 max-w-sm">
                        <div className="flex items-center gap-1 h-1.5 w-full bg-muted/40 rounded-full overflow-hidden">
                            {steps.map((_, i) => (
                                <div 
                                    key={i} 
                                    className={cn(
                                        "h-full transition-all duration-500",
                                        i === currentStepIndex ? "flex-[4] bg-primary" : i < currentStepIndex ? "flex-1 bg-primary/40" : "flex-1 bg-muted"
                                    )}
                                />
                            ))}
                        </div>
                        <div className="flex items-center gap-4">
                             {!isCurrentStepTasksCompleted && (
                                <span className="flex items-center gap-1 text-[7px] font-black uppercase text-amber-600 tracking-widest animate-pulse">
                                    <AlertCircle className="h-2.5 w-2.5" /> Verify Assets
                                </span>
                             )}
                             <span className="text-[8px] font-black uppercase text-foreground tracking-[0.2em]">Flow: {Math.round(((currentStepIndex + 1)/steps.length) * 100)}%</span>
                        </div>
                    </div>

                    <button 
                        disabled={!isCurrentStepTasksCompleted}
                        onClick={() => currentStepIndex === steps.length - 1 ? setIsFinished(true) : setCurrentStepIndex(c => c + 1)}
                        className={cn(
                            "h-10 md:h-12 px-6 md:px-10 rounded-xl font-black text-[10px] md:text-xs uppercase tracking-[0.2em] flex items-center gap-2 transition-all active:scale-[0.98] shadow-lg disabled:opacity-50 disabled:grayscale disabled:cursor-not-allowed", 
                            currentStepIndex === steps.length - 1 
                                ? "bg-emerald-600 text-white shadow-emerald-500/20" 
                                : "bg-primary text-white shadow-primary/20 hover:brightness-110"
                        )}
                    >
                        <span>{currentStepIndex === steps.length - 1 ? "Complete" : "Continue"}</span>
                        {isCurrentStepTasksCompleted ? <ChevronRight className="h-4 w-4" /> : <Lock className="h-3.5 w-3.5" />}
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
import { useData } from '../context/DataContext';
import { 
    Play, Pause, RotateCcw, PartyPopper, ArrowLeft, 
    Check, X, BookOpen, Utensils, CheckSquare, Clock, ChevronRight,
    Users, Plus, Minus, Timer, ListChecks,
    Lock, AlertCircle, Volume2, VolumeX, FastForward, Activity
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '../lib/utils';

const CompactTimer: React.FC<{ timeLeft: number; totalTime: number; isRunning: boolean; onToggle: () => void; onReset: () => void; }> = ({ timeLeft, totalTime, isRunning, onToggle, onReset }) => {
    const progress = totalTime > 0 ? timeLeft / totalTime : 0;
    const formatTime = (s: number) => `${Math.floor(s / 60)}:${((s % 60) || 0).toString().padStart(2, '0')}`;

    return (
        <div className="flex flex-col items-center bg-card border border-border/50 p-6 rounded-3xl shadow-sm w-full">
             <div className="relative h-32 w-32 md:h-40 md:w-40 flex items-center justify-center mb-6">
                 <svg className="absolute inset-0 transform -rotate-90 w-full h-full">
                    <circle cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="2" className="text-muted/10" />
                    <motion.circle
                        cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="4" strokeLinecap="round"
                        initial={{ strokeDashoffset: 400 }}
                        animate={{ strokeDashoffset: 400 - (400 * progress) }}
                        transition={{ duration: 0.5, ease: "linear" }}
                        style={{ strokeDasharray: 400 }}
                        className="text-primary"
                    />
                </svg>
                <div className="flex flex-col items-center">
                    <span className="text-3xl md:text-4xl font-black tabular-nums tracking-tighter text-foreground">{formatTime(timeLeft)}</span>
                    <span className="text-[7px] font-black uppercase text-muted-foreground tracking-[0.3em] mt-1">Countdown</span>
                </div>
             </div>
             <div className="flex gap-2 w-full max-w-[280px]">
                <button 
                    onClick={onReset} 
                    className="w-12 h-12 rounded-xl bg-muted/50 hover:bg-muted text-muted-foreground flex items-center justify-center transition-all active:scale-90 border border-border/40"
                    title="Reset Timer"
                >
                    <RotateCcw className="h-4 w-4"/>
                </button>
                <button 
                    onClick={onToggle} 
                    className={cn(
                        "flex-1 h-12 rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all shadow-sm", 
                        isRunning 
                            ? "bg-red-50 text-red-600 border border-red-100" 
                            : "bg-primary text-white shadow-primary/20 hover:brightness-105"
                    )}
                >
                    {isRunning ? <Pause className="h-4 w-4"/> : <Play className="h-4 w-4 fill-current"/>}
                    <span>{isRunning ? 'Halt' : 'Initiate'}</span>
                </button>
             </div>
        </div>
    );
};

export default function CookingModePage() {
    const { recipeId } = useParams<{ recipeId: string }>();
    const [searchParams] = useSearchParams();
    const initialServings = searchParams.get('servings') ? parseInt(searchParams.get('servings')!) : 1;
    const { getRecipeById } = useData();
    const navigate = useNavigate();
    const recipe = getRecipeById(recipeId || '');

    const activeStepRef = useRef<HTMLDivElement>(null);

    const [currentStepIndex, setCurrentStepIndex] = useState(0);
    const [localServings, setLocalServings] = useState(initialServings);
    const [isFinished, setIsFinished] = useState(false);
    const [timeLeft, setTimeLeft] = useState(0);
    const [isTimerRunning, setIsTimerRunning] = useState(false);
    const [completedIngs, setCompletedIngs] = useState<Set<string>>(new Set());
    const [isSpeaking, setIsSpeaking] = useState(false);

    const steps = recipe?.steps || [];
    const scaleFactor = recipe ? localServings / recipe.servings : 1;

    const currentStepIngredients = useMemo(() => {
        if (!recipe) return [];
        const currentStepData = steps[currentStepIndex];

        if (currentStepData?.linkedIngredientIds && currentStepData.linkedIngredientIds.length > 0) {
            const allIngredients = recipe.ingredientSections.flatMap(s => s.ingredients);
            return allIngredients.filter(ing => currentStepData.linkedIngredientIds!.includes(ing.id));
        }

        const stepNum = currentStepData?.stepNumber || (currentStepIndex + 1);
        return recipe.ingredientSections[stepNum - 1]?.ingredients || [];
    }, [recipe, currentStepIndex, steps]);

    const isCurrentStepTasksCompleted = useMemo(() => {
        if (currentStepIngredients.length === 0) return true;
        return currentStepIngredients.every(ing => completedIngs.has(ing.id));
    }, [currentStepIngredients, completedIngs]);

    const speakInstruction = () => {
        if ('speechSynthesis' in window) {
            window.speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(steps[currentStepIndex].instruction);
            utterance.onstart = () => setIsSpeaking(true);
            utterance.onend = () => setIsSpeaking(false);
            window.speechSynthesis.speak(utterance);
        }
    };

    useEffect(() => {
        if (steps[currentStepIndex]?.duration) {
            setTimeLeft(steps[currentStepIndex].duration! * 60);
        } else {
            setTimeLeft(0);
        }
        setIsTimerRunning(false);
        activeStepRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, [currentStepIndex, steps]);

    useEffect(() => {
        let interval: any;
        if (isTimerRunning && timeLeft > 0) {
            interval = setInterval(() => setTimeLeft(p => p - 1), 1000);
        } else if (timeLeft === 0) {
            setIsTimerRunning(false);
        }
        return () => clearInterval(interval);
    }, [isTimerRunning, timeLeft]);

    const toggleIngredient = (id: string) => {
        setCompletedIngs(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    if (!recipe) return null;

    if (isFinished) {
        return (
            <div className="fixed inset-0 bg-background z-[200] flex items-center justify-center p-4 font-sans">
                <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="max-w-md w-full bg-card p-10 rounded-[2rem] border border-border shadow-2xl text-center">
