                                                            ? "bg-emerald-500 border-emerald-500 text-white shadow-lg shadow-emerald-500/20" 
                                                            : "border-border bg-muted/5 text-muted-foreground group-hover:border-primary/30"
                                                    )}>
                                                        {isDone ? <Check className="h-5 w-5 stroke-[4]" /> : <span className="text-xs font-black">{idx + 1}</span>}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <p className={cn(
                                                            "text-[10px] md:text-xs font-black truncate leading-tight uppercase tracking-tight", 
                                                            isDone ? "line-through text-muted-foreground/50" : "text-foreground"
                                                        )}>
                                                            {ing.name}
                                                        </p>
                                                        <p className={cn(
                                                            "text-[9px] font-black uppercase tracking-widest mt-1",
                                                            isDone ? "text-emerald-500/50" : "text-primary"
                                                        )}>
                                                            {(ing.quantity * scaleFactor).toFixed(1)} {ing.unit}
                                                        </p>
                                                    </div>
                                                </div>
                                                <div className="flex items-center justify-between pt-2 border-t border-border/40 mt-auto">
                                                    <span className="text-[8px] font-black uppercase text-muted-foreground/40 tracking-[0.2em]">Asset {idx + 1}</span>
                                                    <span className={cn("text-[7px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded", isDone ? "bg-emerald-100 text-emerald-600" : "bg-muted text-muted-foreground/60")}>
                                                        {isDone ? 'STAGED' : 'PENDING'}
                                                    </span>
                                                </div>
                                            </motion.div>
                                        );
                                    })
                                ) : (
                                    <div className="col-span-full py-16 text-center text-muted-foreground/20 flex flex-col items-center gap-4 border-2 border-dashed border-border/20 rounded-[2.5rem] bg-muted/5">
                                        <BookOpen className="h-10 w-10 opacity-30" />
                                        <p className="text-[10px] font-black uppercase tracking-[0.4em]">Autonomous Mode Only</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Sticky Navigation Footer */}
            <div className="bg-white border-t border-border/40 h-20 md:h-24 flex items-center px-6 md:px-12 shadow-2xl z-40">
                <div className="max-w-6xl mx-auto w-full flex items-center justify-between gap-6">
                    <button 
                        disabled={currentStepIndex === 0}
                        onClick={() => setCurrentStepIndex(c => c - 1)}
                        className="h-12 md:h-14 px-6 rounded-2xl border border-border flex items-center gap-3 hover:bg-muted disabled:opacity-5 transition-all active:scale-90"
                    >
                        <ArrowLeft className="h-5 w-5 text-foreground" />
                        <span className="text-xs font-black uppercase tracking-widest hidden sm:inline">Prior</span>
                    </button>

                    <div className="flex-1 flex flex-col items-center gap-3 max-w-md">
                        <div className="flex items-center gap-2 h-2 w-full bg-muted/20 rounded-full overflow-hidden">
                            {steps.map((_, i) => (
                                <div 
                                    key={i} 
                                    className={cn(
                                        "h-full transition-all duration-700",
                                        i === currentStepIndex ? "flex-[6] bg-primary" : i < currentStepIndex ? "flex-1 bg-primary/40" : "flex-1 bg-muted/50"
                                    )}
                                />
                            ))}
                        </div>
                        <div className="flex items-center gap-6">
                             {!isCurrentStepTasksCompleted && (
                                <span className="flex items-center gap-1.5 text-[8px] font-black uppercase text-amber-600 tracking-widest animate-pulse">
                                    <AlertCircle className="h-3 w-3" /> Audit Assets
                                </span>
                             )}
                             <span className="text-[9px] font-black uppercase text-foreground tracking-[0.3em] font-mono">Process: {progressPercent}%</span>
                        </div>
                    </div>

                    <button 
                        disabled={!isCurrentStepTasksCompleted}
                        onClick={() => currentStepIndex === steps.length - 1 ? setIsFinished(true) : setCurrentStepIndex(c => c + 1)}
                        className={cn(
                            "h-12 md:h-14 px-8 md:px-12 rounded-2xl font-black text-xs uppercase tracking-[0.3em] flex items-center gap-3 transition-all active:scale-[0.98] shadow-xl disabled:opacity-20 disabled:grayscale disabled:cursor-not-allowed", 
                            currentStepIndex === steps.length - 1 
                                ? "bg-emerald-600 text-white shadow-emerald-500/30" 
                                : "bg-primary text-white shadow-primary/30 hover:brightness-110"
                        )}
                    >
                        <span>{currentStepIndex === steps.length - 1 ? "Terminate" : "Advance"}</span>
                        {isCurrentStepTasksCompleted ? <ChevronRight className="h-5 w-5" /> : <Lock className="h-4 w-4" />}
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
import { useData } from '../context/DataContext';
import { 
    Play, Pause, RotateCcw, PartyPopper, ArrowLeft, 
    Check, BookOpen, Utensils, CheckSquare, Clock, ChevronRight,
    Users, Plus, Minus, Timer, ListChecks,
    Lock, AlertCircle, Volume2, VolumeX, FastForward, Activity
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '../lib/utils';

// Helper for professional synthesized UI sound
const playTimerStartSound = () => {
    try {
        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const oscillator = audioCtx.createOscillator();
        const gainNode = audioCtx.createGain();

        oscillator.connect(gainNode);
        gainNode.connect(audioCtx.destination);

        oscillator.type = 'sine';
        oscillator.frequency.setValueAtTime(880, audioCtx.currentTime); // A5 note
        oscillator.frequency.exponentialRampToValueAtTime(440, audioCtx.currentTime + 0.1); // Slide to A4

        gainNode.gain.setValueAtTime(0.1, audioCtx.currentTime);
        gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.1);

        oscillator.start();
        oscillator.stop(audioCtx.currentTime + 0.1);
    } catch (e) {
        console.warn("Audio Context blocked or not supported", e);
    }
};

const CompactTimer: React.FC<{ timeLeft: number; totalTime: number; isRunning: boolean; onToggle: () => void; onReset: () => void; }> = ({ timeLeft, totalTime, isRunning, onToggle, onReset }) => {
    const progress = totalTime > 0 ? timeLeft / totalTime : 0;
    const formatTime = (s: number) => `${Math.floor(s / 60)}:${((s % 60) || 0).toString().padStart(2, '0')}`;

    return (
        <div className="flex flex-col items-center bg-card border border-border/50 p-4 rounded-2xl shadow-sm w-full">
             <div className="relative h-24 w-24 md:h-32 md:w-32 flex items-center justify-center mb-4">
                 <svg className="absolute inset-0 transform -rotate-90 w-full h-full">
                    <circle cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="2" className="text-muted/10" />
                    <motion.circle
                        cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="4" strokeLinecap="round"
                        initial={{ strokeDashoffset: 400 }}
                        animate={{ strokeDashoffset: 400 - (400 * progress) }}
                        transition={{ duration: 0.5, ease: "linear" }}
                        style={{ strokeDasharray: 400 }}
                        className="text-primary"
                    />
                </svg>
                <div className="flex flex-col items-center">
                    <span className="text-2xl md:text-3xl font-black tabular-nums tracking-tighter text-foreground">{formatTime(timeLeft)}</span>
                    <span className="text-[6px] font-black uppercase text-muted-foreground tracking-[0.3em] mt-0.5">Time</span>
                </div>
             </div>
             <div className="flex gap-2 w-full max-w-[240px]">
                <button 
                    onClick={onReset} 
                    className="w-10 h-10 rounded-lg bg-muted/50 hover:bg-muted text-muted-foreground flex items-center justify-center transition-all active:scale-90 border border-border/40"
                    title="Reset Timer"
                >
                    <RotateCcw className="h-4 w-4"/>
                </button>
                <button 
                    onClick={() => {
                        if (!isRunning) playTimerStartSound();
                        onToggle();
                    }} 
                    className={cn(
                        "flex-1 h-10 rounded-lg font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all shadow-sm", 
                        isRunning 
                            ? "bg-red-50 text-red-600 border border-red-100" 
                            : "bg-primary text-white shadow-primary/20 hover:brightness-105"
                    )}
                >
                    {isRunning ? <Pause className="h-4 w-4"/> : <Play className="h-4 w-4 fill-current"/>}
                    <span>{isRunning ? 'Halt' : 'Start'}</span>
                </button>
             </div>
        </div>
    );
};

export default function CookingModePage() {
    const { recipeId } = useParams<{ recipeId: string }>();
    const [searchParams] = useSearchParams();
    const initialServings = searchParams.get('servings') ? parseInt(searchParams.get('servings')!) : 1;
    const { getRecipeById } = useData();
    const navigate = useNavigate();
    const recipe = getRecipeById(recipeId || '');

    const activeStepRef = useRef<HTMLDivElement>(null);

    const [currentStepIndex, setCurrentStepIndex] = useState(0);
    const [localServings, setLocalServings] = useState(initialServings);
    const [isFinished, setIsFinished] = useState(false);
    const [timeLeft, setTimeLeft] = useState(0);
    const [isTimerRunning, setIsTimerRunning] = useState(false);
    const [completedIngs, setCompletedIngs] = useState<Set<string>>(new Set());
    const [isSpeaking, setIsSpeaking] = useState(false);

    const steps = recipe?.steps || [];
    const scaleFactor = recipe ? localServings / recipe.servings : 1;

    const currentStepIngredients = useMemo(() => {
        if (!recipe) return [];
        const currentStepData = steps[currentStepIndex];

        if (currentStepData?.linkedIngredientIds && currentStepData.linkedIngredientIds.length > 0) {
            const allIngredients = recipe.ingredientSections.flatMap(s => s.ingredients);
            return allIngredients.filter(ing => currentStepData.linkedIngredientIds!.includes(ing.id));
        }

        const stepNum = currentStepData?.stepNumber || (currentStepIndex + 1);
        return recipe.ingredientSections[stepNum - 1]?.ingredients || [];
    }, [recipe, currentStepIndex, steps]);

    const isCurrentStepTasksCompleted = useMemo(() => {
        if (currentStepIngredients.length === 0) return true;
        return currentStepIngredients.every(ing => completedIngs.has(ing.id));
    }, [currentStepIngredients, completedIngs]);

    const speakInstruction = () => {
        if ('speechSynthesis' in window) {
            window.speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(steps[currentStepIndex].instruction);
            utterance.onstart = () => setIsSpeaking(true);
            utterance.onend = () => setIsSpeaking(false);
            window.speechSynthesis.speak(utterance);
        }
    };

    useEffect(() => {
        if (steps[currentStepIndex]?.duration) {
            setTimeLeft(steps[currentStepIndex].duration! * 60);
        } else {
            setTimeLeft(0);
        }
        setIsTimerRunning(false);
        activeStepRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, [currentStepIndex, steps]);

    useEffect(() => {
        let interval: any;
        if (isTimerRunning && timeLeft > 0) {
            interval = setInterval(() => setTimeLeft(p => p - 1), 1000);
        } else if (timeLeft === 0) {
            setIsTimerRunning(false);
        }
        return () => clearInterval(interval);
    }, [isTimerRunning, timeLeft]);

    const toggleIngredient = (id: string) => {
        setCompletedIngs(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    if (!recipe) return null;

    if (isFinished) {
        return (
            <div className="fixed inset-0 bg-background z-[200] flex items-center justify-center p-4 font-sans">
                <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="max-w-md w-full bg-card p-8 rounded-[2rem] border border-border shadow-2xl text-center">
                    <div className="h-16 w-16 bg-primary/10 text-primary rounded-full flex items-center justify-center mx-auto mb-6">
                        <PartyPopper className="h-8 w-8" />
                    </div>
                    <h1 className="text-2xl font-black text-foreground mb-2 tracking-tighter uppercase">Service Completed</h1>
                    <p className="text-[10px] text-muted-foreground mb-8 font-bold leading-relaxed uppercase tracking-widest">{recipe.name} IS READY FOR PLATING.</p>
                    <button onClick={() => navigate(`/recipes/${recipeId}`)} className="w-full py-4 bg-primary text-white rounded-xl font-black text-[10px] uppercase tracking-[0.3em] shadow-xl hover:brightness-105 active:scale-[0.99] transition-all">Exit Console</button>
                </motion.div>
            </div>
        );
    }

    const progressPercent = Math.round(((currentStepIndex + 1) / steps.length) * 100);

    return (
        <div className="fixed inset-0 bg-[#fdfcfb] dark:bg-zinc-950 z-[150] flex flex-col font-sans overflow-hidden">
            {/* Header - Height Reduced */}
            <div className="bg-card border-b border-border/40 h-12 md:h-14 flex items-stretch sticky top-0 z-30 shadow-sm px-4 md:px-6">
                <div className="flex items-center flex-1 min-w-0">
                    <button onClick={() => navigate(-1)} className="p-1.5 hover:bg-muted rounded-lg transition-all active:scale-90 mr-3">
                        <ArrowLeft className="h-4 w-4 text-muted-foreground"/>
                    </button>
                    <div className="min-w-0">
                        <h2 className="text-[10px] md:text-xs font-black text-foreground tracking-tight truncate uppercase leading-tight">{recipe.name}</h2>
                        <div className="flex items-center gap-2 mt-0.5">
                            <Activity className="h-2.5 w-2.5 text-primary animate-pulse" />
                            <span className="text-[7px] md:text-[8px] font-black uppercase text-primary tracking-widest leading-none">Live Console {currentStepIndex + 1}/{steps.length}</span>
                        </div>
                    </div>
                </div>

                <div className="flex items-center justify-end gap-3 md:gap-6">
                    <div className="flex items-center gap-1 bg-muted/20 p-0.5 rounded-lg border border-border/40">
                        <button 
                            onClick={() => setLocalServings(Math.max(1, localServings - 1))}
                            className="h-7 w-7 md:h-9 md:w-9 rounded-md bg-white dark:bg-zinc-800 shadow-sm border border-border/50 flex items-center justify-center text-muted-foreground hover:text-primary transition-all active:scale-90"
                        >
                            <Minus className="h-3 w-3" strokeWidth={3} />
                        </button>

                        <div className="flex flex-col items-center px-2">
                            <input 
                                type="number"
                                min="1"
                                value={localServings}
                                onChange={(e) => setLocalServings(Math.max(1, parseInt(e.target.value) || 1))}
                                className="w-10 md:w-12 bg-transparent text-center text-xs md:text-sm font-black tabular-nums text-foreground outline-none border-none focus:ring-0"
                            />
                            <span className="text-[6px] font-black uppercase text-muted-foreground tracking-widest leading-none">Servings</span>
                        </div>

                        <button 
                            onClick={() => setLocalServings(localServings + 1)}
                            className="h-7 w-7 md:h-9 md:w-9 rounded-md bg-primary shadow-md shadow-primary/10 flex items-center justify-center text-white transition-all active:scale-90"
                        >
                            <Plus className="h-3 w-3" strokeWidth={3} />
                        </button>
                    </div>
                </div>
            </div>

            <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
                {/* Method Sequence Timeline - Padding Reduced */}
                <div className="w-full md:w-1/2 lg:w-3/5 overflow-y-auto p-3 md:p-6 md:border-r border-border/20 scrollbar-hide bg-white dark:bg-zinc-950">
                    <div className="max-w-2xl mx-auto space-y-6 pb-24">
                        <div className="flex items-center gap-2 px-1">
                            <ListChecks className="h-4 w-4 text-primary" />
                            <h3 className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground">Instructional Feed</h3>
                            <div className="h-px flex-1 bg-border/20"></div>
                        </div>

                        <div className="space-y-4">
                            <AnimatePresence mode="wait">
                                {steps.map((step, idx) => {
                                    const isActive = currentStepIndex === idx;
                                    const isDone = currentStepIndex > idx;

                                    if (!isActive && !isDone) return null;

                                    return (
                                        <motion.div 
                                            key={step.id}
                                            ref={isActive ? activeStepRef : null}
                                            initial={isActive ? { scale: 0.98, opacity: 0 } : false}
                                            animate={{ scale: 1, opacity: 1 }}
                                            className={cn(
                                                "relative p-4 md:p-6 rounded-2xl border transition-all select-none",
                                                isActive 
                                                    ? "bg-white dark:bg-zinc-900 border-primary shadow-lg ring-4 ring-primary/5 z-10" 
                                                    : "bg-muted/5 border-border/20 opacity-30 grayscale blur-[0.5px]"
                                            )}
                                        >
                                            <div className="flex gap-4 items-start">
                                                <div className="flex flex-col items-center shrink-0">
                                                    <div className={cn(
                                                        "h-8 w-8 rounded-lg border-2 flex items-center justify-center transition-all",
                                                        isActive ? "bg-primary border-primary text-white scale-110 shadow-sm" : "bg-background border-border text-muted-foreground"
                                                    )}>
                                                        {isDone ? <Check className="h-4 w-4" strokeWidth={3} /> : <span className="text-[10px] font-black">{idx + 1}</span>}
                                                    </div>
                                                </div>

                                                <div className="flex-1 min-w-0">
                                                    {isActive && (
                                                        <div className="flex items-center justify-between mb-3">
                                                            <div className="flex items-center gap-2">
                                                                <span className="flex h-1.5 w-1.5 rounded-full bg-primary animate-pulse"></span>
                                                                <span className="text-[8px] font-black text-primary uppercase tracking-[0.2em]">Current Mission</span>
                                                            </div>
                                                            <button 
                                                                onClick={speakInstruction}
                                                                className={cn(
                                                                    "h-7 w-7 rounded-full flex items-center justify-center transition-all",
                                                                    isSpeaking ? "bg-primary text-white scale-110" : "bg-muted text-muted-foreground hover:bg-primary/10"
                                                                )}
                                                            >
                                                                {isSpeaking ? <VolumeX className="h-3.5 w-3.5" /> : <Volume2 className="h-3.5 w-3.5" />}
                                                            </button>
                                                        </div>
                                                    )}
                                                    <p className={cn(
                                                        "font-black leading-snug transition-all uppercase tracking-tight",
                                                        isActive ? "text-base md:text-xl text-foreground" : "text-sm text-muted-foreground",
                                                        isDone && "line-through opacity-50"
                                                    )}>
                                                        {step.instruction}
                                                    </p>

                                                    {isActive && currentStepIndex < steps.length - 1 && (
                                                        <div className="mt-4 p-2 rounded-xl bg-muted/10 border border-border/10">
                                                            <div className="flex items-center gap-1.5 mb-1">
                                                                <FastForward className="h-2.5 w-2.5 text-muted-foreground" />
                                                                <span className="text-[7px] font-black uppercase text-muted-foreground tracking-widest">Next Up</span>
                                                            </div>
                                                            <p className="text-[8px] font-bold text-muted-foreground/60 uppercase line-clamp-1">{steps[currentStepIndex + 1].instruction}</p>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </motion.div>
                                    );
                                })}
                            </AnimatePresence>
                        </div>
                    </div>
                </div>

                {/* Sidebar Controls - Padding Reduced */}
                <div className="w-full md:w-1/2 lg:w-2/5 overflow-y-auto p-4 md:p-6 bg-muted/5 scrollbar-hide">
                    <div className="max-w-xl mx-auto space-y-6">
                        {/* Timer Section */}
                        <div className="animate-in fade-in slide-in-from-right duration-300">
                            <div className="flex items-center gap-2 mb-3 px-1">
                                <Timer className="h-3.5 w-3.5 text-muted-foreground" />
                                <h3 className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground">Flow Control</h3>
                                <div className="h-px flex-1 bg-border/20"></div>
                            </div>
                            {steps[currentStepIndex]?.duration ? (
                                <CompactTimer 
                                    timeLeft={timeLeft} 
                                    totalTime={steps[currentStepIndex].duration! * 60} 
                                    isRunning={isTimerRunning} 
                                    onToggle={() => setIsTimerRunning(!isTimerRunning)} 
                                    onReset={() => setTimeLeft(steps[currentStepIndex].duration! * 60)} 
                                />
                            ) : (
                                <div className="bg-card border border-dashed border-border/60 p-8 rounded-2xl w-full flex flex-col items-center text-muted-foreground/20">
                                    <Clock className="h-8 w-8 mb-2" />
                                    <span className="text-[8px] font-black uppercase tracking-[0.4em]">Pace Enforced</span>
                                </div>
                            )}
                        </div>

                        {/* Step Ingredients Section - Grid Density Increased */}
                        <div className="animate-in fade-in slide-in-from-right duration-500">
                            <div className="flex items-center justify-between mb-3 px-1">
                                <div className="flex items-center gap-2">
                                    <Utensils className="h-3.5 w-3.5 text-muted-foreground" />
                                    <h3 className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground">Required Assets</h3>
                                </div>
                                <span className={cn(
                                    "text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full border transition-all",
                                    isCurrentStepTasksCompleted ? "bg-emerald-50 text-emerald-600 border-emerald-200" : "bg-primary/5 text-primary border-primary/10"
                                )}>
                                    {completedIngs.size} / {currentStepIngredients.length} Audit
                                </span>
                            </div>

                            <div className={cn(
                                "grid gap-2 transition-all",
                                currentStepIngredients.length > 2 ? "grid-cols-1 sm:grid-cols-2 lg:grid-cols-2" : "grid-cols-1"
                            )}>
                                {currentStepIngredients.length > 0 ? (
                                    currentStepIngredients.map((ing, idx) => {
                                        const isDone = completedIngs.has(ing.id);
                                        return (
                                            <motion.div 
                                                key={ing.id} 
                                                layout
                                                onClick={() => toggleIngredient(ing.id)}
                                                className={cn(
                                                    "group relative flex flex-col gap-2 p-3 rounded-xl border transition-all cursor-pointer select-none shadow-sm",
                                                    isDone 
                                                        ? "bg-emerald-50/40 border-emerald-200/60 dark:bg-emerald-900/10" 
                                                        : "bg-card border-border/40 hover:bg-muted/5"
                                                )}
                                            >
                                                <div className="flex items-center gap-2.5">
                                                    <div className={cn(
                                                        "w-8 h-8 rounded-lg border flex items-center justify-center transition-all shrink-0",
                                                        isDone 
                                                            ? "bg-emerald-500 border-emerald-500 text-white" 
                                                            : "border-border bg-muted/5 text-muted-foreground group-hover:bg-primary/5"
                                                    )}>
                                                        {isDone ? <Check className="h-4 w-4 stroke-[4]" /> : <span className="text-[9px] font-black">{idx + 1}</span>}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <p className={cn(
                                                            "text-[9px] md:text-[10px] font-black truncate leading-tight uppercase tracking-tight", 
                                                            isDone ? "line-through text-muted-foreground/50" : "text-foreground"
                                                        )}>
                                                            {ing.name}
                                                        </p>
                                                        <p className={cn(
                                                            "text-[8px] font-black uppercase tracking-widest mt-0.5",
                                                            isDone ? "text-emerald-500/50" : "text-primary"
                                                        )}>
                                                            {(ing.quantity * scaleFactor).toFixed(1)} {ing.unit}
                                                        </p>
                                                    </div>
                                                </div>
                                            </motion.div>
                                        );
                                    })
                                ) : (
                                    <div className="col-span-full py-12 text-center text-muted-foreground/20 flex flex-col items-center gap-3 border border-dashed border-border/20 rounded-2xl bg-muted/5">
                                        <BookOpen className="h-8 w-8 opacity-30" />
                                        <p className="text-[9px] font-black uppercase tracking-[0.3em]">Autonomous Phase</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Sticky Navigation Footer - Height Reduced */}
            <div className="bg-white border-t border-border/40 h-14 md:h-16 flex items-center px-4 md:px-8 shadow-2xl z-40">
                <div className="max-w-6xl mx-auto w-full flex items-center justify-between gap-4">
                    <button 
                        disabled={currentStepIndex === 0}
                        onClick={() => setCurrentStepIndex(c => c - 1)}
                        className="h-9 md:h-10 px-4 rounded-lg border border-border flex items-center gap-2 hover:bg-muted disabled:opacity-10 transition-all active:scale-90"
                    >
                        <ArrowLeft className="h-4 w-4 text-foreground" />
                        <span className="text-[9px] font-black uppercase tracking-widest hidden sm:inline">Prior</span>
                    </button>

                    <div className="flex-1 flex flex-col items-center gap-1.5 max-w-md">
                        <div className="flex items-center gap-1.5 h-1 w-full bg-muted/20 rounded-full overflow-hidden">
                            {steps.map((_, i) => (
                                <div 
                                    key={i} 
                                    className={cn(
                                        "h-full transition-all duration-700",
                                        i === currentStepIndex ? "flex-[6] bg-primary" : i < currentStepIndex ? "flex-1 bg-primary/40" : "flex-1 bg-muted/50"
                                    )}
                                />
                            ))}
                        </div>
                        <div className="flex items-center gap-4">
                             {!isCurrentStepTasksCompleted && (
                                <span className="flex items-center gap-1 text-[7px] font-black uppercase text-amber-600 tracking-widest animate-pulse">
                                    <AlertCircle className="h-2 w-2" /> Verify Assets
                                </span>
                             )}
                             <span className="text-[8px] font-black uppercase text-foreground tracking-[0.2em] font-mono">FLOW: {progressPercent}%</span>
                        </div>
                    </div>

                    <button 
                        disabled={!isCurrentStepTasksCompleted}
                        onClick={() => currentStepIndex === steps.length - 1 ? setIsFinished(true) : setCurrentStepIndex(c => c + 1)}
                        className={cn(
                            "h-9 md:h-10 px-6 md:px-10 rounded-lg font-black text-[9px] uppercase tracking-[0.2em] flex items-center gap-2 transition-all active:scale-[0.98] shadow-lg disabled:opacity-20 disabled:grayscale disabled:cursor-not-allowed", 
                            currentStepIndex === steps.length - 1 
                                ? "bg-emerald-600 text-white shadow-emerald-500/20" 
                                : "bg-primary text-white shadow-primary/20 hover:brightness-110"
                        )}
                    >
                        <span>{currentStepIndex === steps.length - 1 ? "End" : "Next"}</span>
                        {isCurrentStepTasksCompleted ? <ChevronRight className="h-4 w-4" /> : <Lock className="h-3 w-3" />}
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useData } from '../context/DataContext';
import { Recipe } from '../types';
import { 
    Clock, Flame, Utensils, ArrowLeft, Star, 
    Edit, Printer, ChefHat, Package, Calculator, HeartPulse, ListOrdered, 
    Minus, Plus, Play
} from 'lucide-react';
import { cn } from '../lib/utils';
import { motion, AnimatePresence } from 'framer-motion';
import { NutritionTab } from '../components/recipes/NutritionTab';
import { PrintRecipeModal } from '../components/recipes/PrintRecipeModal';
import { IngredientsTab } from '../components/recipes/IngredientsTab';
import { StepsTab } from '../components/recipes/StepsTab';
import { CostTab } from '../components/recipes/CostTab';

export default function RecipeDetailPage() {
    const { recipeId } = useParams<{ recipeId: string }>();
    const navigate = useNavigate();
    const { getRecipeById, updateRecipe, ingredients: pantryIngredients, updateIngredient } = useData();

    const [activeTab, setActiveTab] = useState<'ingredients' | 'steps' | 'cost' | 'nutrition'>('ingredients');
    const [showPrintModal, setShowPrintModal] = useState(false);
    const [localServings, setLocalServings] = useState<number | null>(null);

    const recipe = useMemo(() => getRecipeById(recipeId || ''), [recipeId, getRecipeById]);

    useEffect(() => {
        setLocalServings(null);
    }, [recipeId]);

    if (!recipe) return null;

    const currentServings = localServings ?? recipe.servings ?? 1;
    const scaleFactor = currentServings / (recipe.servings || 1);

    return (
        <div className="min-h-screen pb-20 -mt-2 -mx-2 md:-mx-6 lg:-mx-8 font-sans bg-[#fdfcfb] relative">
            {showPrintModal && <PrintRecipeModal recipe={recipe} onClose={() => setShowPrintModal(false)} />}

            <div className="relative h-[22vh] md:h-[30vh] w-full overflow-hidden bg-slate-900 border-b border-border/40 shadow-inner">
                <img src={recipe.imageUrl} className="w-full h-full object-cover opacity-75 grayscale-[10%] group-hover:grayscale-0 transition-all duration-700" alt={recipe.name} />
                <div className="absolute inset-0 bg-gradient-to-t from-[#fdfcfb] via-transparent to-black/10" />

                <div className="absolute top-3 left-4 right-4 flex justify-between items-start z-20">
                    <button onClick={() => navigate('/recipes')} className="p-2 bg-white/20 hover:bg-white/40 backdrop-blur-xl rounded-xl text-white border border-white/30 transition-all active:scale-90 shadow-lg">
                        <ArrowLeft className="h-5 w-5" />
                    </button>

                    <div className="flex items-center gap-1 p-1 bg-black/30 backdrop-blur-2xl rounded-xl border border-white/20 shadow-2xl">
                        <div className="flex items-center bg-white/10 rounded-lg px-0.5">
                             <button onClick={() => setLocalServings(Math.max(1, currentServings - 1))} className="w-7 h-7 flex items-center justify-center text-white hover:bg-white/20 rounded-md font-black transition-all active:scale-90 text-xs">-</button>
                             <div className="px-2 text-center min-w-[32px]">
                                <input 
                                    type="number" 
                                    value={currentServings} 
                                    onChange={(e) => setLocalServings(Math.max(1, parseInt(e.target.value) || 1))}
                                    className="block w-full bg-transparent text-center font-black text-[11px] text-white tabular-nums outline-none"
                                />
                             </div>
                             <button onClick={() => setLocalServings(currentServings + 1)} className="w-7 h-7 flex items-center justify-center text-white hover:bg-white/20 rounded-md font-black transition-all active:scale-90 text-xs">+</button>
                        </div>

                        <button onClick={() => setShowPrintModal(true)} className="h-8 w-8 flex items-center justify-center text-white/80 hover:text-white hover:bg-white/10 rounded-lg transition-all" title="Print Recipe">
                            <Printer className="h-4 w-4" />
                        </button>

                        <button 
                            onClick={() => navigate(`/recipes/${recipeId}/cook?servings=${currentServings}`)}
                            className="h-8 px-3 bg-primary text-white rounded-lg font-black text-[10px] uppercase tracking-wider shadow-lg shadow-primary/30 hover:brightness-110 active:scale-95 transition-all flex items-center gap-1.5"
                        >
                            <ChefHat className="h-3.5 w-3.5" />
                            <span className="hidden xs:inline">Service</span>
                        </button>

                        <button 
                            onClick={() => navigate(`/recipes/${recipe.id}/edit`)} 
                            className="h-8 w-8 flex items-center justify-center text-white/80 hover:text-white hover:bg-white/10 rounded-lg transition-all border-l border-white/10 ml-0.5"
                            title="Edit Recipe"
                        >
                            <Edit className="h-4 w-4" />
                        </button>
                    </div>
                </div>

                <div className="absolute bottom-4 left-6 right-6 max-w-7xl mx-auto">
                    <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }}>
                        <div className="flex flex-wrap gap-2 mb-1.5">
                            <span className="px-2 py-0.5 rounded-md bg-primary text-white text-[8px] font-black uppercase tracking-widest shadow-lg shadow-primary/20">{recipe.category}</span>
                            <span className="px-2 py-0.5 rounded-md bg-white/10 text-white backdrop-blur-md border border-white/20 text-[8px] font-black uppercase tracking-widest">{recipe.cuisine}</span>
                        </div>
                        <h1 className="text-2xl md:text-4xl font-black text-foreground leading-tight tracking-tighter uppercase">{recipe.name}</h1>
                    </motion.div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-4 md:px-8 mt-4">
                <div className="grid grid-cols-4 gap-2 mb-6">
                    {[
                        { label: 'KCAL', val: Math.round((recipe.nutrition?.calories || 0) * scaleFactor), color: 'text-orange-600 bg-orange-50/50 border-orange-100' },
                        { label: 'PRO', val: Math.round((recipe.nutrition?.protein || 0) * scaleFactor) + 'g', color: 'text-blue-600 bg-blue-50/50 border-blue-100' },
                        { label: 'CARB', val: Math.round((recipe.nutrition?.carbs || 0) * scaleFactor) + 'g', color: 'text-emerald-600 bg-emerald-50/50 border-emerald-100' },
                        { label: 'FAT', val: Math.round((recipe.nutrition?.fat || 0) * scaleFactor) + 'g', color: 'text-pink-600 bg-pink-50/50 border-pink-100' }
                    ].map(stat => (
                        <div key={stat.label} className={cn("border py-2 px-1 rounded-lg flex flex-col items-center justify-center transition-all", stat.color)}>
                            <p className="text-[7px] font-black uppercase tracking-[0.1em] opacity-60 mb-0.5">{stat.label}</p>
                            <p className="text-[11px] md:text-sm font-black tabular-nums">{stat.val}</p>
                        </div>
                    ))}
                </div>

                <div className="flex gap-1 p-1 bg-muted/30 border border-border/40 rounded-xl mb-6 sticky top-14 md:top-16 z-30 backdrop-blur-2xl shadow-sm overflow-x-auto scrollbar-hide">
                    {[
                        { id: 'ingredients', label: 'Prep', icon: ListOrdered },
                        { id: 'steps', label: 'Method', icon: Utensils },
                        { id: 'cost', label: 'Finance', icon: Calculator },
                        { id: 'nutrition', label: 'Vitality', icon: HeartPulse }
                    ].map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id as any)}
                            className={cn(
                                "flex-1 min-w-[80px] py-2 rounded-lg text-[9px] font-black uppercase tracking-widest flex items-center justify-center gap-1.5 transition-all",
                                activeTab === tab.id 
                                    ? "bg-white text-primary shadow-sm ring-1 ring-border/50" 
                                    : "text-muted-foreground hover:text-foreground"
                            )}
                        >
                            <tab.icon className="h-3.5 w-3.5" /> {tab.label}
                        </button>
                    ))}
                </div>

                <div className="min-h-[400px]">
                    <AnimatePresence mode="wait">
                        <motion.div key={activeTab} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.2 }}>
                            {activeTab === 'ingredients' && <IngredientsTab recipe={recipe} scaleFactor={scaleFactor} pantryIngredients={pantryIngredients} onUpdatePantryItem={updateIngredient} onUpdateRecipe={updateRecipe} />}
                            {activeTab === 'steps' && <StepsTab steps={recipe.steps} />}
                            {activeTab === 'cost' && <CostTab recipe={recipe} scaleFactor={scaleFactor} pantryIngredients={pantryIngredients} />}
                            {activeTab === 'nutrition' && <NutritionTab recipe={recipe} scaleFactor={scaleFactor} />}
                        </motion.div>
                    </AnimatePresence>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useMemo, useCallback } from 'react';
import { Recipe, Ingredient, RecipeIngredient } from '../../types';
import { AlertTriangle, Scale, CookingPot, ClipboardCheck } from 'lucide-react';
import { ViewIngredientRow } from './ViewIngredientRow';
import { QuickEditIngredientModal } from './QuickEditIngredientModal';
import { AnimatePresence, motion } from 'framer-motion';
import { cn } from '../../lib/utils';

export const IngredientsTab: React.FC<{ 
    recipe: Recipe; 
    scaleFactor: number;
    pantryIngredients: Ingredient[];
    onUpdatePantryItem: (item: Ingredient) => void;
    onUpdateRecipe: (recipe: Recipe) => void;
}> = ({ recipe, scaleFactor, pantryIngredients = [], onUpdatePantryItem, onUpdateRecipe }) => {
    const [editingItem, setEditingItem] = useState<Ingredient | null>(null);
    const [displayUnits, setDisplayUnits] = useState<Record<string, string>>({});
    const [activeSystem, setActiveSystem] = useState<'original' | 'metric' | 'imperial'>('original');

    const unlinkedCount = useMemo(() => {
        const allIngredients = recipe.ingredientSections?.flatMap(s => s.ingredients || []) || [];
        return allIngredients.filter(ri => !pantryIngredients.find(pi => pi.id === ri.ingredientId)).length;
    }, [recipe, pantryIngredients]);

    const handleLinkIngredient = useCallback((sectionId: string, ingredientId: string, pantryId: string) => {
        const newSections = recipe.ingredientSections.map(sec => {
            if (sec.id !== sectionId) return sec;
            return {
                ...sec,
                ingredients: sec.ingredients.map(i => 
                    i.id === ingredientId ? { ...i, ingredientId: pantryId } : i
                )
            };
        });
        onUpdateRecipe({ ...recipe, ingredientSections: newSections });
    }, [recipe, onUpdateRecipe]);

    const handleUnitChange = useCallback((id: string, unit: string) => {
        setDisplayUnits(prev => ({...prev, [id]: unit}));
    }, []);

    const handleUpdateIngredientCost = useCallback((sectionId: string, ingredientId: string, newCostPerUnit: number) => {
         const newSections = recipe.ingredientSections.map(sec => {
            if (sec.id !== sectionId) return sec;
            return {
                ...sec,
                ingredients: sec.ingredients.map(i => 
                    i.id === ingredientId ? { ...i, manualCostPerUnit: newCostPerUnit } : i
                )
            };
        });
        onUpdateRecipe({ ...recipe, ingredientSections: newSections });
    }, [recipe, onUpdateRecipe]);

    const handleBatchConvert = (system: 'original' | 'metric' | 'imperial') => {
        setActiveSystem(system);
        if (system === 'original') {
            setDisplayUnits({});
            return;
        }

        const newUnits: Record<string, string> = { ...displayUnits };
        recipe.ingredientSections.forEach(sec => {
            sec.ingredients.forEach(ing => {
                let targetUnit = ing.unit;
                if (system === 'metric') {
                    if (['oz', 'lb'].includes(ing.unit)) targetUnit = 'g';
                    if (['cup', 'tbsp', 'tsp', 'gallon'].includes(ing.unit)) targetUnit = 'ml';
                } else {
                    if (['g', 'kg'].includes(ing.unit)) targetUnit = 'oz';
                    if (['ml', 'l'].includes(ing.unit)) targetUnit = 'cup';
                }
                newUnits[ing.id] = targetUnit;
            });
        });
        setDisplayUnits(newUnits);
    };

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4 bg-white border border-border/60 p-2 rounded-xl shadow-sm">
                <div className="flex items-center gap-4 pl-2">
                    <div className="flex items-center gap-2 text-xs font-bold text-muted-foreground">
                        <CookingPot className="h-4 w-4 text-primary" />
                        <span>{recipe.ingredientSections.length} Phases</span>
                    </div>
                    <div className="h-4 w-px bg-border"></div>
                    <div className="flex items-center gap-2 text-xs font-bold text-muted-foreground">
                        <ClipboardCheck className="h-4 w-4 text-primary" />
                        <span>{recipe.ingredientSections.reduce((acc, s) => acc + s.ingredients.length, 0)} Items</span>
                    </div>
                </div>
                <div className="flex bg-muted/40 p-1 rounded-lg w-full sm:w-auto">
                    {(['original', 'metric', 'imperial'] as const).map((sys) => (
                        <button 
                            key={sys}
                            onClick={() => handleBatchConvert(sys)}
                            className={cn(
                                "flex-1 sm:flex-none px-4 py-1.5 text-[10px] font-black uppercase rounded-md transition-all relative",
                                activeSystem === sys 
                                    ? "text-primary bg-white shadow-sm ring-1 ring-border/50" 
                                    : "text-muted-foreground hover:text-foreground"
                            )}
                        >
                            {sys}
                        </button>
                    ))}
                </div>
            </div>

            {unlinkedCount > 0 && (
                <div className="bg-amber-50 border border-amber-200 rounded-xl p-3 flex gap-3 items-center">
                    <AlertTriangle className="h-4 w-4 text-amber-600 shrink-0" />
                    <p className="text-[10px] text-amber-800 font-bold uppercase tracking-tight">
                        {unlinkedCount} items need pantry linking for precise costing
                    </p>
                </div>
            )}

            <div className="space-y-12">
                {recipe.ingredientSections?.map((section, idx) => (
                    <div key={section.id} className="relative">
                        {/* Sticky Section Header */}
                        <div className="sticky top-[108px] md:top-[128px] z-20 bg-[#fdfcfb]/95 backdrop-blur-md py-3 -mx-4 px-4 md:mx-0 md:px-0 transition-all border-b border-transparent">
                            <div className="flex items-center gap-3">
                                <div className="h-8 w-8 rounded bg-primary text-white flex items-center justify-center font-black text-xs shadow-sm shrink-0">
                                    {(idx + 1).toString().padStart(2, '0')}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <h3 className="font-black text-sm uppercase tracking-widest text-foreground truncate">
                                        {section.name}
                                    </h3>
                                    <p className="text-[9px] font-bold text-muted-foreground uppercase tracking-tighter">
                                        Phase {idx + 1} &bull; {section.ingredients.length} Required Assets
                                    </p>
                                </div>
                            </div>
                        </div>

                        <div className="mt-4 bg-white rounded-xl border border-border shadow-sm overflow-hidden divide-y divide-border/40">
                            {section.ingredients?.map((ing, index) => {
                                const pantryItem = pantryIngredients.find(pi => pi.id === ing.ingredientId);
                                return (
                                    <ViewIngredientRow
                                        key={ing.id}
                                        index={index}
                                        ing={ing}
                                        pantryItem={pantryItem}
                                        scaleFactor={scaleFactor}
                                        currentUnit={displayUnits[ing.id] || ing.unit}
                                        onUnitChange={handleUnitChange}
                                        onEditPantryItem={setEditingItem}
                                        onLinkIngredient={(ingId, pantryId) => handleLinkIngredient(section.id, ingId, pantryId)}
                                        onUpdateCost={(cost) => handleUpdateIngredientCost(section.id, ing.id, cost)}
                                        pantryIngredients={pantryIngredients}
                                    />
                                );
                            })}
                        </div>
                    </div>
                ))}
            </div>

            <AnimatePresence>
                {editingItem && (
                    <QuickEditIngredientModal 
                        ingredient={editingItem} 
                        onClose={() => setEditingItem(null)} 
                        onSave={onUpdatePantryItem} 
                    />
                )}
            </AnimatePresence>
        </div>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
