                </div>
                <div className="flex items-center gap-2 bg-card border border-border/60 p-1 rounded-lg shadow-sm">
                    <Calendar className="h-3.5 w-3.5 ml-2 text-muted-foreground" />
                    <select 
                        value={dateRange} 
                        onChange={(e) => setDateRange(e.target.value)}
                        className="bg-transparent border-none text-[10px] font-black uppercase tracking-widest focus:ring-0 cursor-pointer py-1.5 pr-8"
                    >
                        <option>This Week</option>
                        <option>This Month</option>
                        <option>This Year</option>
                        <option>All Time</option>
                    </select>
                </div>
            </div>

            {/* KPI Grid */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
                <MetricCard 
                    title="Gross Revenue" 
                    value={formatCurrency(stats.revenue)} 
                    trend={12}
                    icon={DollarSign}
                    color="text-blue-500"
                    description="Total Top-Line Sales"
                />
                <MetricCard 
                    title="COGS Total" 
                    value={formatCurrency(stats.cogs)} 
                    trend={-5}
                    icon={Layers}
                    color="text-orange-500"
                    description="Cost of Goods Sold"
                />
                <MetricCard 
                    title="Net Profit" 
                    value={formatCurrency(stats.profit)} 
                    trend={8}
                    icon={Target}
                    color="text-emerald-500"
                    description="Gross Profit Margin"
                />
                <MetricCard 
