                                    </div>
                                    <div className="space-y-2">
                                        {menuMatrix.stars.length > 0 ? menuMatrix.stars.map(i => (
                                            <div key={i.name} className="flex justify-between text-[11px] font-bold border-b border-emerald-200/30 pb-1">
                                                <span className="truncate pr-2">{i.name}</span>
                                                <span className="text-emerald-600 font-mono">{i.qty} units</span>
                                            </div>
                                        )) : <p className="text-[10px] text-muted-foreground italic">No Stars identified yet.</p>}
                                    </div>
