                                                <span className="text-blue-600 font-mono">{i.qty} units</span>
                                            </div>
                                        )) : <p className="text-[10px] text-muted-foreground italic">No Plowhorses identified.</p>}
                                    </div>
                                </div>

                                {/* Puzzles */}
                                <div className="bg-amber-50/50 dark:bg-amber-950/10 border border-amber-100 dark:border-amber-900/30 p-4 rounded-xl relative overflow-hidden">
                                    <div className="flex justify-between items-start mb-4">
                                        <span className="text-[10px] font-black bg-amber-500 text-white px-2 py-0.5 rounded uppercase tracking-widest">Puzzles</span>
                                        <span className="text-[8px] font-bold text-amber-600 uppercase">Aggressive Promo</span>
                                    </div>
                                    <div className="space-y-2">
                                        {menuMatrix.puzzles.length > 0 ? menuMatrix.puzzles.map(i => (
                                            <div key={i.name} className="flex justify-between text-[11px] font-bold border-b border-amber-200/30 pb-1">
                                                <span className="truncate pr-2">{i.name}</span>
                                                <span className="text-amber-600 font-mono">{i.qty} units</span>
                                            </div>
