import { CostTab } from '../components/recipes/CostTab';

const ResumeSessionsModal: React.FC<{ 
    sessions: CookingSession[]; 
    onClose: () => void;
    onResume: (session: CookingSession) => void;
    onUpdateSession: (id: string, updates: Partial<CookingSession>) => void;
}> = ({ sessions, onClose, onResume, onUpdateSession }) => {
    const [editingId, setEditingId] = useState<string | null>(null);
    const [tempName, setTempName] = useState('');

    const handleStartEdit = (session: CookingSession) => {
        setEditingId(session.id);
        setTempName(session.sessionName || `Session ${session.startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
    };

    const handleSaveName = (id: string) => {
        onUpdateSession(id, { sessionName: tempName });
        setEditingId(null);
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-md flex items-center justify-center p-4">
            <motion.div 
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="bg-card w-full max-w-md rounded-3xl border border-border shadow-2xl overflow-hidden"
            >
                <div className="p-4 border-b border-border bg-muted/30 flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <History className="h-4 w-4 text-primary" />
                        <h2 className="text-sm font-black uppercase tracking-widest">Active Progress Sessions</h2>
                    </div>
                    <button onClick={onClose} className="p-1 hover:bg-muted rounded-full transition-colors">
                        <X className="h-4 w-4 text-muted-foreground" />
                    </button>
                </div>
                <div className="p-4 max-h-[60vh] overflow-y-auto space-y-3">
                    {sessions.length === 0 ? (
                        <p className="text-center py-8 text-xs text-muted-foreground uppercase font-bold tracking-widest opacity-50">No active sessions found</p>
                    ) : (
                        sessions.map(session => (
                            <div key={session.id} className="bg-muted/10 border border-border/60 rounded-2xl p-4 hover:border-primary/30 transition-all group">
                                <div className="flex justify-between items-start mb-3">
                                    <div className="flex-1 mr-4">
                                        {editingId === session.id ? (
                                            <div className="flex items-center gap-2">
                                                <input 
                                                    autoFocus
                                                    value={tempName}
                                                    onChange={e => setTempName(e.target.value)}
                                                    className="bg-background border border-primary/30 rounded-md px-2 py-1 text-xs font-black uppercase tracking-tight focus:ring-1 focus:ring-primary w-full"
                                                />
                                                <button onClick={() => handleSaveName(session.id)} className="p-1.5 bg-primary text-white rounded-md shadow-lg shadow-primary/20">
                                                    <SaveIcon className="h-3 w-3" />
                                                </button>
                                            </div>
                                        ) : (
                                            <div className="flex items-center gap-2">
                                                <h3 className="text-xs font-black text-foreground uppercase tracking-tight truncate">
                                                    {session.sessionName || `Service @ ${session.startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`}
                                                </h3>
                                                <button onClick={() => handleStartEdit(session)} className="opacity-0 group-hover:opacity-100 p-1 hover:bg-muted rounded transition-all">
                                                    <Edit className="h-3 w-3 text-muted-foreground" />
                                                </button>
                                            </div>
                                        )}
                                        <p className="text-[10px] text-muted-foreground font-bold uppercase mt-0.5 tracking-tighter">
                                            {session.startTime.toLocaleDateString()} &bull; Step {session.currentStep + 1}
                                        </p>
                                    </div>
                                    <div className="text-right shrink-0">
                                        <div className="text-[10px] font-black text-primary uppercase">{session.servings} Servings</div>
                                    </div>
                                </div>
                                <button 
                                    onClick={() => onResume(session)}
                                    className="w-full py-2.5 bg-primary text-white rounded-xl font-black text-[9px] uppercase tracking-widest shadow-lg shadow-primary/10 hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-2"
                                >
                                    <Play className="h-3.5 w-3.5 fill-current" /> Resume Console
                                </button>
                            </div>
                        ))
                    )}
                </div>
            </motion.div>
        </div>
    );
};

