                                <Timer className="h-3.5 w-3.5 text-muted-foreground" />
                                <h3 className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground">Flow Control</h3>
                                <div className="h-px flex-1 bg-border/20"></div>
                            </div>
                            {steps[currentStepIndex]?.duration ? (
                                <CompactTimer 
                                    timeLeft={timeLeft} 
                                    totalTime={steps[currentStepIndex].duration! * 60} 
                                    isRunning={isTimerRunning} 
                                    onToggle={() => setIsTimerRunning(!isTimerRunning)} 
                                    onReset={() => setTimeLeft(steps[currentStepIndex].duration! * 60)} 
                                />
