                                <div className="bg-card border border-dashed border-border/60 p-8 rounded-2xl w-full flex flex-col items-center text-muted-foreground/20">
                                    <Clock className="h-8 w-8 mb-2" />
                                    <span className="text-[8px] font-black uppercase tracking-[0.4em]">Pace Enforced</span>
                                </div>
                            )}
                        </div>

                        {/* Step Ingredients Section - Grid Density Increased */}
                        <div className="animate-in fade-in slide-in-from-right duration-500">
                            <div className="flex items-center justify-between mb-3 px-1">
                                <div className="flex items-center gap-2">
                                    <Utensils className="h-3.5 w-3.5 text-muted-foreground" />
                                    <h3 className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.3em] text-muted-foreground">Required Assets</h3>
                                </div>
                                <span className={cn(
                                    "text-[8px] font-black uppercase tracking-widest px-2 py-0.5 rounded-full border transition-all",
                                    isCurrentStepTasksCompleted ? "bg-emerald-50 text-emerald-600 border-emerald-200" : "bg-primary/5 text-primary border-primary/10"
                                )}>
                                    {completedIngs.size} / {currentStepIngredients.length} Audit
                                </span>
                            </div>

                            <div className={cn(
                                "grid gap-2 transition-all",
                                currentStepIngredients.length > 2 ? "grid-cols-1 sm:grid-cols-2 lg:grid-cols-2" : "grid-cols-1"
                            )}>
                                {currentStepIngredients.length > 0 ? (
                                    currentStepIngredients.map((ing, idx) => {
                                        const isDone = completedIngs.has(ing.id);
                                        return (
                                            <motion.div 
                                                key={ing.id} 
                                                layout
                                                onClick={() => toggleIngredient(ing.id)}
                                                className={cn(
                                                    "group relative flex flex-col gap-2 p-3 rounded-xl border transition-all cursor-pointer select-none shadow-sm",
                                                    isDone 
                                                        ? "bg-emerald-50/40 border-emerald-200/60 dark:bg-emerald-900/10" 
                                                        : "bg-card border-border/40 hover:bg-muted/5"
                                                )}
                                            >
                                                <div className="flex items-center gap-2.5">
                                                    <div className={cn(
                                                        "w-8 h-8 rounded-lg border flex items-center justify-center transition-all shrink-0",
                                                        isDone 
                                                            ? "bg-emerald-500 border-emerald-500 text-white" 
                                                            : "border-border bg-muted/5 text-muted-foreground group-hover:bg-primary/5"
                                                    )}>
                                                        {isDone ? <Check className="h-4 w-4 stroke-[4]" /> : <span className="text-[9px] font-black">{idx + 1}</span>}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <p className={cn(
                                                            "text-[9px] md:text-[10px] font-black truncate leading-tight uppercase tracking-tight", 
                                                            isDone ? "line-through text-muted-foreground/50" : "text-foreground"
                                                        )}>
                                                            {ing.name}
                                                        </p>
                                                        <p className={cn(
                                                            "text-[8px] font-black uppercase tracking-widest mt-0.5",
                                                            isDone ? "text-emerald-500/50" : "text-primary"
                                                        )}>
                                                            {(ing.quantity * scaleFactor).toFixed(1)} {ing.unit}
                                                        </p>
                                                    </div>
                                                </div>
                                            </motion.div>
                                        );
                                    })
                                ) : (
                                    <div className="col-span-full py-12 text-center text-muted-foreground/20 flex flex-col items-center gap-3 border border-dashed border-border/20 rounded-2xl bg-muted/5">
                                        <BookOpen className="h-8 w-8 opacity-30" />
                                        <p className="text-[9px] font-black uppercase tracking-[0.3em]">Autonomous Phase</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Sticky Navigation Footer - Height Reduced */}
            <div className="bg-white border-t border-border/40 h-14 md:h-16 flex items-center px-4 md:px-8 shadow-2xl z-40">
                <div className="max-w-6xl mx-auto w-full flex items-center justify-between gap-4">
                    <button 
                        disabled={currentStepIndex === 0}
                        onClick={() => setCurrentStepIndex(c => c - 1)}
                        className="h-9 md:h-10 px-4 rounded-lg border border-border flex items-center gap-2 hover:bg-muted disabled:opacity-10 transition-all active:scale-90"
                    >
                        <ArrowLeft className="h-4 w-4 text-foreground" />
                        <span className="text-[9px] font-black uppercase tracking-widest hidden sm:inline">Prior</span>
                    </button>

                    <div className="flex-1 flex flex-col items-center gap-1.5 max-w-md">
                        <div className="flex items-center gap-1.5 h-1 w-full bg-muted/20 rounded-full overflow-hidden">
                            {steps.map((_, i) => (
                                <div 
                                    key={i} 
                                    className={cn(
                                        "h-full transition-all duration-700",
                                        i === currentStepIndex ? "flex-[6] bg-primary" : i < currentStepIndex ? "flex-1 bg-primary/40" : "flex-1 bg-muted/50"
                                    )}
                                />
                            ))}
                        </div>
                        <div className="flex items-center gap-4">
                             {!isCurrentStepTasksCompleted && (
                                <span className="flex items-center gap-1 text-[7px] font-black uppercase text-amber-600 tracking-widest animate-pulse">
                                    <AlertCircle className="h-2 w-2" /> Verify Assets
                                </span>
                             )}
                             <span className="text-[8px] font-black uppercase text-foreground tracking-[0.2em] font-mono">FLOW: {progressPercent}%</span>
                        </div>
                    </div>

                    <button 
                        disabled={!isCurrentStepTasksCompleted}
                        onClick={() => currentStepIndex === steps.length - 1 ? handleFinish() : setCurrentStepIndex(c => c + 1)}
                        className={cn(
                            "h-9 md:h-10 px-6 md:px-10 rounded-lg font-black text-[9px] uppercase tracking-[0.2em] flex items-center gap-2 transition-all active:scale-[0.98] shadow-lg disabled:opacity-20 disabled:grayscale disabled:cursor-not-allowed", 
                            currentStepIndex === steps.length - 1 
                                ? "bg-emerald-600 text-white shadow-emerald-500/20" 
                                : "bg-primary text-white shadow-primary/20 hover:brightness-110"
                        )}
                    >
                        <span>{currentStepIndex === steps.length - 1 ? "End" : "Next"}</span>
                        {isCurrentStepTasksCompleted ? <ChevronRight className="h-4 w-4" /> : <Lock className="h-3 w-3" />}
                    </button>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useData } from '../context/DataContext';
import { Recipe, CookingSession } from '../types';
import { 
    Clock, Flame, Utensils, ArrowLeft, Star, 
    Edit, Printer, ChefHat, Package, Calculator, HeartPulse, ListOrdered, 
    Minus, Plus, Play, History, FastForward, X, Save as SaveIcon, Trash2, CheckCircle2, Timer
} from 'lucide-react';
import { cn, formatDate } from '../lib/utils';
import { motion, AnimatePresence } from 'framer-motion';
import { NutritionTab } from '../components/recipes/NutritionTab';
import { PrintRecipeModal } from '../components/recipes/PrintRecipeModal';
import { IngredientsTab } from '../components/recipes/IngredientsTab';
import { StepsTab } from '../components/recipes/StepsTab';
import { CostTab } from '../components/recipes/CostTab';

const ResumeSessionsModal: React.FC<{ 
    sessions: CookingSession[]; 
    recipeStepsCount: number;
    onClose: () => void;
    onResume: (session: CookingSession) => void;
    onUpdateSession: (id: string, updates: Partial<CookingSession>) => void;
}> = ({ sessions, recipeStepsCount, onClose, onResume, onUpdateSession }) => {
    const [editingId, setEditingId] = useState<string | null>(null);
    const [tempName, setTempName] = useState('');

    const handleStartEdit = (session: CookingSession) => {
        setEditingId(session.id);
        setTempName(session.sessionName || `Service ${session.startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
    };

    const handleSaveName = (id: string) => {
        onUpdateSession(id, { sessionName: tempName });
        setEditingId(null);
    };

    const handleDiscard = (id: string) => {
        if (window.confirm("Abandon this cooking session? All progress will be lost.")) {
            onUpdateSession(id, { status: 'abandoned', endTime: new Date() });
        }
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-xl flex items-center justify-center p-4">
            <motion.div 
                initial={{ scale: 0.9, opacity: 0, y: 20 }}
                animate={{ scale: 1, opacity: 1, y: 0 }}
                exit={{ scale: 0.9, opacity: 0, y: 20 }}
                className="bg-card w-full max-w-lg rounded-[2rem] border border-border/60 shadow-2xl overflow-hidden flex flex-col max-h-[85vh]"
            >
                <div className="p-6 border-b border-border/40 bg-muted/20 flex justify-between items-center">
                    <div>
                        <div className="flex items-center gap-2 mb-1">
                            <div className="p-1.5 bg-primary/10 rounded-lg">
                                <History className="h-4 w-4 text-primary" />
                            </div>
                            <h2 className="text-base font-black uppercase tracking-widest text-foreground">Mission Logs</h2>
                        </div>
                        <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">Select an active service instance to resume</p>
                    </div>
                    <button onClick={onClose} className="p-2 hover:bg-muted rounded-full transition-colors text-muted-foreground">
                        <X className="h-5 w-5" />
                    </button>
                </div>

                <div className="p-4 md:p-6 overflow-y-auto space-y-4 bg-[#fdfcfb] dark:bg-zinc-950/50">
                    {sessions.length === 0 ? (
                        <div className="text-center py-16 opacity-40 flex flex-col items-center gap-4">
                            <History className="h-12 w-12" />
                            <p className="text-[10px] uppercase font-black tracking-[0.3em]">No saved progress detected</p>
                        </div>
                    ) : (
                        sessions.map(session => {
                            const progress = Math.round(((session.currentStep + 1) / recipeStepsCount) * 100);
                            const timeActive = Math.round((new Date().getTime() - session.startTime.getTime()) / (1000 * 60));

                            return (
                                <motion.div 
                                    key={session.id} 
                                    layout
                                    className="bg-card border border-border/60 rounded-2xl p-5 hover:border-primary/40 transition-all group relative overflow-hidden"
                                >
                                    <div className="absolute top-0 left-0 w-1 h-full bg-primary/20 group-hover:bg-primary transition-colors"></div>

                                    <div className="flex justify-between items-start mb-4">
                                        <div className="flex-1 mr-4">
                                            {editingId === session.id ? (
                                                <div className="flex items-center gap-2">
                                                    <input 
                                                        autoFocus
                                                        value={tempName}
                                                        onChange={e => setTempName(e.target.value)}
                                                        onKeyDown={(e) => e.key === 'Enter' && handleSaveName(session.id)}
                                                        className="bg-muted/30 border border-primary/30 rounded-lg px-3 py-1.5 text-xs font-black uppercase tracking-tight focus:ring-1 focus:ring-primary w-full outline-none"
                                                    />
                                                    <button onClick={() => handleSaveName(session.id)} className="p-2 bg-primary text-white rounded-lg shadow-lg shadow-primary/20 hover:brightness-110">
                                                        <SaveIcon className="h-3.5 w-3.5" />
                                                    </button>
                                                </div>
                                            ) : (
                                                <div className="flex items-center gap-2 group/title">
                                                    <h3 className="text-sm font-black text-foreground uppercase tracking-tight truncate">
                                                        {session.sessionName || `Station @ ${session.startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`}
                                                    </h3>
                                                    <button onClick={() => handleStartEdit(session)} className="opacity-0 group-hover/title:opacity-100 p-1 hover:bg-muted rounded transition-all text-muted-foreground hover:text-primary">
                                                        <Edit className="h-3.5 w-3.5" />
                                                    </button>
                                                </div>
                                            )}
                                            <div className="flex items-center gap-3 mt-1.5">
                                                <div className="flex items-center gap-1 text-[9px] font-black text-muted-foreground/60 uppercase">
                                                    <Clock className="h-3 w-3" /> {session.startTime.toLocaleDateString()}
                                                </div>
                                                <div className="h-1 w-1 rounded-full bg-border"></div>
                                                <div className="flex items-center gap-1 text-[9px] font-black text-muted-foreground/60 uppercase">
                                                    <Timer className="h-3 w-3" /> {timeActive > 60 ? `${Math.floor(timeActive/60)}h ${timeActive%60}m` : `${timeActive}m`} elapsed
                                                </div>
                                            </div>
                                        </div>
                                        <div className="flex flex-col items-end shrink-0 gap-1">
                                            <div className="text-[10px] font-black text-primary uppercase bg-primary/5 px-2 py-0.5 rounded border border-primary/10 tracking-widest">{session.servings} Servings</div>
                                            <button 
                                                onClick={() => handleDiscard(session.id)}
                                                className="p-1.5 text-muted-foreground/40 hover:text-red-500 transition-colors"
                                                title="Discard progress"
                                            >
                                                <Trash2 className="h-3.5 w-3.5" />
                                            </button>
                                        </div>
                                    </div>

                                    <div className="space-y-3">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-1.5">
                                                <CheckCircle2 className="h-3 w-3 text-emerald-500" />
                                                <span className="text-[9px] font-black uppercase text-muted-foreground tracking-widest">Step {session.currentStep + 1} of {recipeStepsCount}</span>
                                            </div>
                                            <span className="text-[10px] font-black font-mono text-primary">{progress}% Complete</span>
                                        </div>
                                        <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                                            <motion.div 
                                                initial={{ width: 0 }}
                                                animate={{ width: `${progress}%` }}
                                                className="h-full bg-primary shadow-[0_0_8px_rgba(var(--primary),0.3)]"
                                            />
                                        </div>

                                        <button 
                                            onClick={() => onResume(session)}
                                            className="w-full mt-2 py-3 bg-zinc-900 dark:bg-primary text-white rounded-xl font-black text-[10px] uppercase tracking-[0.2em] shadow-xl hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-2 group/btn"
                                        >
                                            <Play className="h-3.5 w-3.5 fill-current group-hover:scale-110 transition-transform" /> Resume Command Center
                                        </button>
                                    </div>
                                </motion.div>
                            )
                        })
                    )}
                </div>

                <div className="p-4 bg-muted/10 border-t border-border/40 text-center">
                     <p className="text-[8px] font-bold text-muted-foreground uppercase tracking-widest opacity-50">iKitchen Pro Service Persistence Engine v2.0</p>
                </div>
            </motion.div>
        </div>
    );
};

export default function RecipeDetailPage() {
    const { recipeId } = useParams<{ recipeId: string }>();
    const navigate = useNavigate();
    const { getRecipeById, updateRecipe, ingredients: pantryIngredients, updateIngredient, cookingSessions, updateCookingSession } = useData();

    const [activeTab, setActiveTab] = useState<'ingredients' | 'steps' | 'cost' | 'nutrition'>('ingredients');
    const [showPrintModal, setShowPrintModal] = useState(false);
    const [showResumeList, setShowResumeList] = useState(false);
    const [localServings, setLocalServings] = useState<number | null>(null);

    const recipe = useMemo(() => getRecipeById(recipeId || ''), [recipeId, getRecipeById]);

    // Detect active sessions for this recipe
    const activeSessions = useMemo(() => 
        cookingSessions.filter(s => s.recipeId === recipeId && s.status === 'in_progress'),
    [cookingSessions, recipeId]);

    useEffect(() => {
        setLocalServings(null);
    }, [recipeId]);

    if (!recipe) return null;

    const currentServings = localServings ?? recipe.servings ?? 1;
    const scaleFactor = currentServings / (recipe.servings || 1);

    const handleResume = (session: CookingSession) => {
        navigate(`/recipes/${recipeId}/cook?sessionId=${session.id}`);
    };

    return (
        <div className="min-h-screen pb-20 -mt-2 -mx-2 md:-mx-6 lg:-mx-8 font-sans bg-[#fdfcfb] relative">
            {showPrintModal && <PrintRecipeModal recipe={recipe} onClose={() => setShowPrintModal(false)} />}

            <AnimatePresence>
                {showResumeList && (
                    <ResumeSessionsModal 
                        sessions={activeSessions} 
                        recipeStepsCount={recipe.steps.length}
                        onClose={() => setShowResumeList(false)}
                        onResume={handleResume}
                        onUpdateSession={updateCookingSession}
