                <div className="absolute top-3 left-4 right-4 flex justify-between items-start z-20">
                    <button onClick={() => navigate('/recipes')} className="p-2 bg-white/20 hover:bg-white/40 backdrop-blur-xl rounded-xl text-white border border-white/30 transition-all active:scale-90 shadow-lg">
                        <ArrowLeft className="h-5 w-5" />
                    </button>

                    <div className="flex items-center gap-1 p-1 bg-black/30 backdrop-blur-2xl rounded-xl border border-white/20 shadow-2xl">
                        <div className="flex items-center bg-white/10 rounded-lg px-0.5">
                             <button onClick={() => setLocalServings(Math.max(1, currentServings - 1))} className="w-7 h-7 flex items-center justify-center text-white hover:bg-white/20 rounded-md font-black transition-all active:scale-90 text-xs">-</button>
                             {/* Reduced width container for manual serving count */}
                             <div className="px-1 text-center min-w-[20px]">
                                <input 
