const getRelativeTime = (date: Date) => {
    const now = new Date();
    const diff = Math.floor((now.getTime() - date.getTime()) / 1000);
    if (diff < 60) return 'Just now';
    if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
    return date.toLocaleDateString();
};

const ResumeSessionsModal: React.FC<{ 
    sessions: CookingSession[]; 
    recipeStepsCount: number;
    onClose: () => void;
    onResume: (session: CookingSession) => void;
    onUpdateSession: (id: string, updates: Partial<CookingSession>) => void;
    onDeleteSession: (id: string) => void;
}> = ({ sessions, recipeStepsCount, onClose, onResume, onUpdateSession, onDeleteSession }) => {
    const [editingId, setEditingId] = useState<string | null>(null);
    const [tempName, setTempName] = useState('');

    const handleStartEdit = (session: CookingSession) => {
        setEditingId(session.id);
        setTempName(session.sessionName || `Station ${session.startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`);
    };

    const handleSaveName = (id: string) => {
        onUpdateSession(id, { sessionName: tempName });
        setEditingId(null);
    };

    const handleDiscard = (id: string) => {
        if (window.confirm("Permanently delete this cooking log? This cannot be undone.")) {
            onDeleteSession(id);
        }
    };

    return (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-md flex items-center justify-center p-4" onClick={onClose}>
            <motion.div 
                initial={{ scale: 0.98, opacity: 0, y: 10 }}
                animate={{ scale: 1, opacity: 1, y: 0 }}
                exit={{ scale: 0.98, opacity: 0, y: 10 }}
                className="bg-card w-full max-w-[340px] rounded-[1.25rem] border border-border/80 shadow-2xl overflow-hidden flex flex-col max-h-[60vh]"
                onClick={e => e.stopPropagation()}
            >
                <div className="p-3.5 border-b border-border bg-muted/20 flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <div className="p-1.5 bg-primary/10 rounded-lg text-primary">
                            <History className="h-3.5 w-3.5" />
                        </div>
                        <h2 className="text-[11px] font-black uppercase tracking-[0.2em] text-foreground">Mission Logs</h2>
                    </div>
                    <button onClick={onClose} className="p-1.5 hover:bg-muted rounded-full transition-colors text-muted-foreground">
                        <X className="h-4 w-4" />
                    </button>
                </div>

                <div className="p-2 overflow-y-auto space-y-2 bg-[#fdfcfb] dark:bg-zinc-950/50">
                    {sessions.length === 0 ? (
                        <div className="text-center py-10 opacity-30">
                            <History className="h-8 w-8 mx-auto mb-2" />
                            <p className="text-[9px] uppercase font-black tracking-widest">Archive Empty</p>
                        </div>
                    ) : (
                        sessions.map(session => {
                            const progress = Math.round(((session.currentStep + 1) / recipeStepsCount) * 100);
                            const isEditing = editingId === session.id;

                            return (
                                <motion.div 
                                    key={session.id} 
                                    layout
                                    className="bg-card border border-border/60 rounded-xl p-3 hover:border-primary/40 transition-all group relative"
                                >
                                    <div className="flex justify-between items-start gap-2 mb-2.5">
                                        <div className="flex-1 min-w-0">
                                            {isEditing ? (
                                                <div className="flex items-center gap-1">
                                                    <input 
                                                        autoFocus
                                                        value={tempName}
                                                        onChange={e => setTempName(e.target.value)}
                                                        onKeyDown={(e) => e.key === 'Enter' && handleSaveName(session.id)}
                                                        className="bg-muted/50 border border-primary/30 rounded-md px-2 py-1 text-[10px] font-black uppercase tracking-tight focus:ring-1 focus:ring-primary w-full outline-none"
                                                    />
                                                    <button onClick={() => handleSaveName(session.id)} className="p-1.5 bg-primary text-white rounded-md flex items-center justify-center">
                                                        <Check className="h-3 w-3" />
                                                    </button>
                                                </div>
                                            ) : (
                                                <div className="flex items-center gap-1.5 group/title">
                                                    <h3 className="text-[11px] font-black text-foreground uppercase tracking-tight truncate leading-none">
                                                        {session.sessionName || `Station ${session.startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`}
                                                    </h3>
                                                    <button onClick={() => handleStartEdit(session)} className="opacity-0 group-hover/title:opacity-100 p-0.5 hover:bg-muted rounded transition-all text-muted-foreground hover:text-primary">
                                                        <Edit className="h-2.5 w-2.5" />
                                                    </button>
                                                </div>
                                            )}
                                            <div className="flex items-center gap-2 mt-1.5">
                                                <span className="text-[7px] font-black text-muted-foreground/60 uppercase tracking-widest">
                                                    {getRelativeTime(session.startTime)}
                                                </span>
                                                <div className="h-0.5 w-0.5 rounded-full bg-border"></div>
                                                <span className="text-[7px] font-black text-primary uppercase tracking-widest">
                                                    {session.servings} Serv.
                                                </span>
                                            </div>
                                        </div>

                                        <button 
                                            onClick={() => handleDiscard(session.id)}
                                            className="p-1 text-muted-foreground/20 hover:text-red-500 transition-colors"
                                            title="Delete Log"
                                        >
                                            <Trash2 className="h-3 w-3" />
                                        </button>
                                    </div>

                                    <div className="space-y-1.5 mb-3">
                                        <div className="flex items-center justify-between">
                                            <span className="text-[8px] font-black uppercase text-muted-foreground tracking-tighter">Step {session.currentStep + 1} / {recipeStepsCount}</span>
                                            <span className="text-[8px] font-black text-primary font-mono">{progress}%</span>
                                        </div>
                                        <div className="h-1 w-full bg-muted/40 rounded-full overflow-hidden">
                                            <motion.div 
                                                initial={{ width: 0 }}
                                                animate={{ width: `${progress}%` }}
                                                className="h-full bg-primary" 
                                            />
                                        </div>
                                    </div>

                                    <button 
                                        onClick={() => onResume(session)}
                                        className="w-full py-1.5 bg-zinc-900 dark:bg-primary text-white rounded-lg font-black text-[9px] uppercase tracking-widest hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-1.5"
                                    >
                                        <Play className="h-2.5 w-2.5 fill-current" /> Resume Service
                                    </button>
                                </motion.div>
                            )
                        })
                    )}
                </div>
            </motion.div>
        </div>
    );
};

