    MoreHorizontal, BarChart3, ListChecks, Calendar
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn } from '../lib/utils';

const getRelativeTime = (date: Date) => {
    const now = new Date();
    const diff = Math.floor((now.getTime() - date.getTime()) / 1000);
    if (diff < 60) return 'Just now';
    if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
    return date.toLocaleDateString();
};

const LogItem: React.FC<{
    session: CookingSession;
    recipeStepsCount: number;
    onUpdate: (id: string, updates: Partial<CookingSession>) => void;
    onDelete: (id: string) => void;
    onResume: (session: CookingSession) => void;
}> = ({ session, recipeStepsCount, onUpdate, onDelete, onResume }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [tempName, setTempName] = useState(session.sessionName || '');
    const progress = Math.round(((session.currentStep + 1) / recipeStepsCount) * 100);

    const handleSave = () => {
        onUpdate(session.id, { sessionName: tempName });
        setIsEditing(false);
    };

    return (
        <motion.div 
            layout
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className="bg-card border border-border/60 rounded-2xl p-4 hover:border-primary/40 transition-all group relative overflow-hidden"
        >
            <div className="absolute top-0 left-0 w-1 h-full bg-primary/20 group-hover:bg-primary transition-colors"></div>

            <div className="flex flex-col md:flex-row gap-4 items-stretch md:items-center">
                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1.5">
                        {isEditing ? (
                            <div className="flex items-center gap-1.5 w-full max-w-xs">
                                <input 
                                    autoFocus
                                    value={tempName}
                                    onChange={e => setTempName(e.target.value)}
                                    onKeyDown={e => e.key === 'Enter' && handleSave()}
                                    className="bg-muted/50 border border-primary/30 rounded-lg px-3 py-1 text-xs font-black uppercase tracking-tight w-full outline-none"
                                />
                                <button onClick={handleSave} className="p-1.5 bg-primary text-white rounded-lg shadow-lg shadow-primary/20">
                                    <Check className="h-3.5 w-3.5" />
                                </button>
                                <button onClick={() => setIsEditing(false)} className="p-1.5 bg-muted text-muted-foreground rounded-lg">
                                    <XCircle className="h-3.5 w-3.5" />
                                </button>
                            </div>
                        ) : (
                            <div className="flex items-center gap-2 group/title">
                                <h3 className="text-sm font-black text-foreground uppercase tracking-tight truncate">
                                    {session.sessionName || `Station @ ${session.startTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`}
                                </h3>
                                <button 
                                    onClick={() => { setTempName(session.sessionName || ''); setIsEditing(true); }} 
                                    className="opacity-0 group-hover/title:opacity-100 p-1 hover:bg-muted rounded transition-all text-muted-foreground hover:text-primary"
                                >
                                    <Edit className="h-3 w-3" />
                                </button>
                            </div>
                        )}
                    </div>

                    <div className="flex flex-wrap items-center gap-3">
                        <div className="flex items-center gap-1.5 text-[9px] font-black text-muted-foreground/60 uppercase tracking-widest">
                            <Calendar className="h-3 w-3" /> {getRelativeTime(session.startTime)}
                        </div>
                        <div className="h-1 w-1 rounded-full bg-border"></div>
                        <div className="flex items-center gap-1.5 text-[9px] font-black text-primary uppercase tracking-widest">
                            <Utensils className="h-3 w-3" /> {session.servings} Servings
                        </div>
                    </div>
                </div>

                <div className="w-full md:w-48 space-y-2">
                    <div className="flex items-center justify-between">
                        <span className="text-[8px] font-black uppercase text-muted-foreground tracking-widest">
                            {session.status === 'in_progress' ? `Step ${session.currentStep + 1} / ${recipeStepsCount}` : session.status.toUpperCase()}
                        </span>
                        <span className="text-[10px] font-black font-mono text-primary">{progress}%</span>
                    </div>
                    <div className="h-1.5 w-full bg-muted rounded-full overflow-hidden">
                        <motion.div 
                            initial={{ width: 0 }}
                            animate={{ width: `${progress}%` }}
                            className={cn(
                                "h-full transition-all duration-1000",
                                session.status === 'completed' ? "bg-emerald-500" : 
                                session.status === 'abandoned' ? "bg-red-400" : "bg-primary shadow-[0_0_8px_rgba(var(--primary),0.3)]"
                            )}
                        />
                    </div>
                </div>

                <div className="flex items-center gap-2 shrink-0 border-t md:border-t-0 md:border-l border-border/40 pt-3 md:pt-0 md:pl-4">
                    {session.status === 'in_progress' ? (
                        <button 
                            onClick={() => onResume(session)}
                            className="flex-1 md:flex-none px-4 py-2 bg-zinc-900 dark:bg-primary text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-2"
                        >
                            <Play className="h-3.5 w-3.5 fill-current" /> Resume
                        </button>
                    ) : (
                         <div className={cn(
                             "px-3 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest border",
                             session.status === 'completed' ? "bg-emerald-50 text-emerald-600 border-emerald-100" : "bg-red-50 text-red-600 border-red-100"
                         )}>
                            {session.status}
                         </div>
                    )}

                    <button 
                        onClick={() => onDelete(session.id)}
                        className="h-9 w-9 flex items-center justify-center text-muted-foreground/30 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                        title="Purge session"
                    >
                        <Trash2 className="h-4 w-4" />
                    </button>
                </div>
            </div>
        </motion.div>
    );
};

export default function CookingLogsPage() {
    const { recipeId } = useParams<{ recipeId: string }>();
    const navigate = useNavigate();
    const { getRecipeById, getSessionsByRecipeId, updateCookingSession, deleteCookingSession } = useData();

    const [activeTab, setActiveTab] = useState<'ongoing' | 'history' | 'all'>('ongoing');
    const [searchQuery, setSearchQuery] = useState('');

    const recipe = useMemo(() => getRecipeById(recipeId || ''), [recipeId, getRecipeById]);
    const sessions = useMemo(() => getSessionsByRecipeId(recipeId || ''), [recipeId, getSessionsByRecipeId]);

    const filteredSessions = useMemo(() => {
        let list = sessions;
        if (activeTab === 'ongoing') list = list.filter(s => s.status === 'in_progress');
        if (activeTab === 'history') list = list.filter(s => s.status !== 'in_progress');

        if (searchQuery) {
            const q = searchQuery.toLowerCase();
            list = list.filter(s => 
                (s.sessionName?.toLowerCase().includes(q)) || 
                s.startTime.toLocaleDateString().includes(q)
            );
        }
