    const [showOrderForm, setShowOrderForm] = useState(false);
    const [invoiceOrder, setInvoiceOrder] = useState<Order | null>(null);
    const [ticketOrder, setTicketOrder] = useState<Order | null>(null);
    const [editingOrder, setEditingOrder] = useState<Order | null>(null);

    // Metrics
    const metrics = useMemo(() => ({
        pending: orders.filter(o => o.status === 'pending_approval').length,
        active: orders.filter(o => o.status === 'processing').length,
        revenue: orders.filter(o => o.status === 'completed').reduce((sum, o) => sum + o.totalAmount, 0),
        total: orders.length
    }), [orders]);

    // Filtering & Sorting (Priority first, then time)
    const filteredOrders = useMemo(() => {
        return orders
            .filter(order => {
                const matchesSearch = 
                    order.customerName.toLowerCase().includes(searchQuery.toLowerCase()) || 
                    order.orderNumber.toLowerCase().includes(searchQuery.toLowerCase());
                const matchesStatus = statusFilter === 'all' || order.status === statusFilter;
                return matchesSearch && matchesStatus;
            })
            .sort((a, b) => {
                // Urgent/High priority always on top
                const priorityOrder = { high: 0, normal: 1, low: 2 };
                if (priorityOrder[a.priority] !== priorityOrder[b.priority]) {
                    return priorityOrder[a.priority] - priorityOrder[b.priority];
                }
                return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
            });
    }, [orders, searchQuery, statusFilter]);

