                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* Orders Feed */}
            <div className="space-y-4 px-1">
                <AnimatePresence mode="popLayout">
                    {filteredOrders.length > 0 ? (
                        filteredOrders.map(order => (
                            <OrderCard 
                                key={order.id} 
                                order={order} 
                                onStatusChange={updateOrderStatus}
                                onDelete={deleteOrder}
                                onEdit={(o) => setEditingOrder(o)}
                                onShowInvoice={setInvoiceOrder}
                                onShowTicket={setTicketOrder}
                                recipes={recipes}
                            />
                        ))
                    ) : (
                        <motion.div
                            key="empty"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            className="flex flex-col items-center justify-center py-24 text-center bg-muted/5 border-2 border-dashed border-border/40 rounded-[2.5rem]"
                        >
                            <div className="h-20 w-20 bg-muted/10 rounded-full flex items-center justify-center mb-4">
                                <Terminal className="h-10 w-10 text-muted-foreground/30" />
                            </div>
                            <h3 className="text-sm font-black text-muted-foreground uppercase tracking-[0.2em]">Zero Activity Detected</h3>
                            <p className="text-[10px] text-muted-foreground/60 font-bold uppercase mt-2 tracking-widest">Awaiting incoming data streams</p>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* Global Modals */}
            <AnimatePresence>
                {showOrderForm && (
                    <OrderFormModal 
                        recipes={recipes} 
                        onClose={() => setShowOrderForm(false)}
                        onSave={handleCreateOrder}
                    />
                )}
                {editingOrder && (
                    <OrderFormModal 
                        recipes={recipes} 
                        initialData={editingOrder}
                        onClose={() => setEditingOrder(null)}
                        onSave={handleUpdateOrder}
                    />
                )}
                {invoiceOrder && (
                    <InvoiceModal 
                        order={invoiceOrder}
                        onClose={() => setInvoiceOrder(null)}
                    />
