export const StatusBadge: React.FC<{ status: OrderStatus }> = ({ status }) => {
    const config: Record<OrderStatus, { color: string; icon: any; label: string }> = {
        pending_approval: { color: 'bg-amber-100 text-amber-700 border-amber-200 dark:bg-amber-950/40 dark:text-amber-400 dark:border-amber-900/50', icon: Clock, label: 'Queued' },
        approved: { color: 'bg-blue-100 text-blue-700 border-blue-200 dark:bg-blue-950/40 dark:text-blue-400 dark:border-blue-900/50', icon: CheckCircle2, label: 'Authorized' },
        processing: { color: 'bg-orange-100 text-orange-700 border-orange-200 dark:bg-orange-950/40 dark:text-orange-400 dark:border-orange-900/50', icon: Utensils, label: 'In Service' },
        completed: { color: 'bg-emerald-100 text-emerald-700 border-emerald-200 dark:bg-emerald-950/40 dark:text-emerald-400 dark:border-emerald-900/50', icon: Truck, label: 'Finalized' },
        cancelled: { color: 'bg-red-100 text-red-700 border-red-200 dark:bg-red-950/40 dark:text-red-400 dark:border-red-900/50', icon: X, label: 'Aborted' },
    };
    const { color, icon: Icon, label } = config[status];
    return (
        <span className={cn("flex items-center gap-1.5 px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest border shadow-sm", color)}>
            <Icon className="h-3 w-3" /> {label}
        </span>
    );
};

export const PriorityBadge: React.FC<{ priority: OrderPriority }> = ({ priority }) => {
    const config = {
        low: { color: 'bg-slate-100 text-slate-500 border-slate-200 dark:bg-slate-900/40 dark:text-slate-500 dark:border-slate-800', icon: ArrowRight, label: 'Standard' },
        normal: { color: 'bg-blue-50 text-blue-600 border-blue-100 dark:bg-blue-900/40 dark:text-blue-400 dark:border-blue-800', icon: Zap, label: 'Priority' },
        high: { color: 'bg-red-100 text-red-600 border-red-200 animate-pulse dark:bg-red-950/40 dark:text-red-400 dark:border-red-900', icon: ShieldAlert, label: 'Critical' },
    };

    const safePriority = (priority && config[priority]) ? priority : 'normal';
    const { color, icon: Icon, label } = config[safePriority];

    return (
        <span className={cn("flex items-center gap-1 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-widest border", color)}>
            <Icon className="h-2.5 w-2.5" /> {label}
        </span>
    );
};

