const getRelativeTime = (date: Date) => {
    const now = new Date();
    const diff = Math.floor((now.getTime() - date.getTime()) / 1000);
    if (diff < 60) return 'Just now';
    if (diff < 3600) return `${Math.floor(diff / 60)}m ago`;
    if (diff < 86400) return `${Math.floor(diff / 3600)}h ago`;
    return date.toLocaleDateString();
};

const LogItem: React.FC<{
    session: CookingSession;
    recipeStepsCount: number;
    onUpdate: (id: string, updates: Partial<CookingSession>) => void;
    onDelete: (id: string) => void;
    onResume: (session: CookingSession) => void;
}> = ({ session, recipeStepsCount, onUpdate, onDelete, onResume }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [tempName, setTempName] = useState(session.sessionName || '');
    const progress = Math.round(((session.currentStep + 1) / (recipeStepsCount || 1)) * 100);

    const handleSave = () => {
        onUpdate(session.id, { sessionName: tempName });
        setIsEditing(false);
    };

    return (
        <motion.div 
            layout
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className="bg-card border border-border/60 rounded-2xl p-4 hover:border-primary/40 transition-all group relative overflow-hidden shadow-sm"
        >
            <div className={cn(
                "absolute top-0 left-0 w-1.5 h-full transition-colors",
                session.status === 'in_progress' ? "bg-primary animate-pulse" : "bg-muted-foreground/20"
            )}></div>

            <div className="flex flex-col md:flex-row gap-4 items-stretch md:items-center">
                <div className="flex-1 min-w-0 md:pl-2">
                    <div className="flex items-center gap-2 mb-1.5">
                        {isEditing ? (
                            <div className="flex items-center gap-1.5 w-full max-w-xs">
                                <input 
                                    autoFocus
                                    value={tempName}
                                    onChange={e => setTempName(e.target.value)}
                                    onKeyDown={e => e.key === 'Enter' && handleSave()}
                                    className="bg-muted/50 border border-primary/30 rounded-lg px-3 py-1 text-xs font-black uppercase tracking-tight w-full outline-none focus:ring-2 focus:ring-primary/20"
                                />
