));

const DashboardPage: React.FC = () => {
    const { recipes, ingredients, orders, updateIngredient } = useData();
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const timer = setTimeout(() => setLoading(false), 500);
        return () => clearTimeout(timer);
    }, []);

    const totalRevenue = useMemo(() => orders.filter(o => o.status === 'completed').reduce((sum, o) => sum + o.totalAmount, 0), [orders]);

    const { criticalStock, warningStock } = useMemo(() => {
        const critical = ingredients.filter(i => i.packagesInStock === 0);
        const warning = ingredients.filter(i => i.packagesInStock > 0 && i.packagesInStock <= 2);
        return { criticalStock: critical, warningStock: warning };
    }, [ingredients]);

    const activePrepItems = useMemo(() => {
        const counts: Record<string, { count: number, id: string }> = {};
        orders.filter(o => o.status === 'approved' || o.status === 'processing').forEach(order => {
            order.items.forEach(item => {
                if (!counts[item.recipeName]) {
                    counts[item.recipeName] = { count: 0, id: item.recipeId };
                }
                counts[item.recipeName].count += item.quantity;
            });
        });
        return Object.entries(counts)
            .map(([name, data]) => ({ name, ...data }))
            .sort((a, b) => b.count - a.count);
    }, [orders]);

    const topRecipes = useMemo(() => recipes.slice(0, 4), [recipes]);

    const handleQuickRestock = (item: any) => {
        const restockQty = 5;
        const updated = {
            ...item,
            packagesInStock: item.packagesInStock + restockQty,
            quantityInStock: (item.packagesInStock + restockQty) * item.packageSize,
            last_verified: new Date()
        };
        updateIngredient(updated);
    };

    if (loading) return (
        <div className="flex h-[80vh] items-center justify-center">
            <div className="flex flex-col items-center gap-4">
                <ChefHat className="animate-bounce text-primary w-12 h-12" />
                <p className="text-[10px] font-black uppercase tracking-[0.5em] text-muted-foreground">Booting Console...</p>
            </div>
        </div>
    );

    const dailyTarget = 5000;
    const progressPercent = Math.min(100, (totalRevenue / dailyTarget) * 100);

    return (
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-8 pb-32 max-w-7xl mx-auto px-4 md:px-0">
            <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-8">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <Terminal className="h-6 w-6 text-primary" />
                        <h1 className="text-3xl md:text-4xl font-black tracking-tighter text-foreground uppercase">Service Command</h1>
                    </div>
                    <p className="text-[11px] font-black text-muted-foreground uppercase tracking-[0.4em] ml-1">Real-time Establishment Control & Analytics</p>
                </div>

                <div className="bg-card border border-border/60 rounded-[2rem] p-6 flex flex-col md:flex-row items-center gap-8 min-w-[320px] shadow-sm relative overflow-hidden group">
                    <div className="absolute top-0 right-0 p-4 opacity-[0.03] group-hover:opacity-[0.08] transition-opacity">
                        <TrendingUp className="h-16 w-16 text-primary" />
                    </div>
                    <div className="flex-1 w-full">
                        <div className="flex justify-between items-center mb-3">
                            <span className="text-[10px] font-black uppercase text-muted-foreground tracking-widest flex items-center gap-2">
                                <Activity className="h-3 w-3 text-primary" /> Revenue Target
                            </span>
                            <span className="text-[10px] font-black text-primary uppercase">{Math.round(progressPercent)}% Success</span>
                        </div>
                        <div className="h-2 w-full bg-muted/50 rounded-full overflow-hidden">
                            <motion.div initial={{ width: 0 }} animate={{ width: `${progressPercent}%` }} transition={{ duration: 1, ease: "easeOut" }} className="h-full bg-primary shadow-[0_0_12px_rgba(29,185,84,0.4)]" />
                        </div>
                    </div>
                    <div className="text-center md:text-right border-t md:border-t-0 md:border-l border-border/40 pt-4 md:pt-0 md:pl-8">
                        <p className="text-2xl font-black leading-none tracking-tighter">{formatCurrency(totalRevenue).split('.')[0]}</p>
                        <p className="text-[9px] font-black text-muted-foreground uppercase mt-2 tracking-widest">Realized Sale</p>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <MetricCard icon={UtensilsCrossed} label="Curated Dishes" value={recipes.length} colorClass="text-slate-500" />
