import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useData } from '../context/DataContext';
import { Recipe, CookingSession } from '../types';
import { 
    Clock, Flame, Utensils, ArrowLeft, Star, 
    Edit, Printer, ChefHat, Package, Calculator, HeartPulse, ListOrdered, 
    Minus, Plus, Play, History, FastForward, X, Save as SaveIcon, Trash2, CheckCircle2, Timer,
    Check
} from 'lucide-react';
import { cn, formatDate } from '../lib/utils';
import { motion, AnimatePresence } from 'framer-motion';
import { NutritionTab } from '../components/recipes/NutritionTab';
import { PrintRecipeModal } from '../components/recipes/PrintRecipeModal';
import { IngredientsTab } from '../components/recipes/IngredientsTab';
import { StepsTab } from '../components/recipes/StepsTab';
import { CostTab } from '../components/recipes/CostTab';

export default function RecipeDetailPage() {
    const { recipeId } = useParams<{ recipeId: string }>();
    const navigate = useNavigate();
    const { getRecipeById, updateRecipe, ingredients: pantryIngredients, updateIngredient, cookingSessions } = useData();

    const [activeTab, setActiveTab] = useState<'ingredients' | 'steps' | 'cost' | 'nutrition'>('ingredients');
    const [showPrintModal, setShowPrintModal] = useState(false);
    const [localServings, setLocalServings] = useState<number | null>(null);

    const recipe = useMemo(() => getRecipeById(recipeId || ''), [recipeId, getRecipeById]);

    const activeSessionsCount = useMemo(() => 
        cookingSessions.filter(s => s.recipeId === recipeId && s.status === 'in_progress').length,
    [cookingSessions, recipeId]);

    useEffect(() => {
        setLocalServings(null);
    }, [recipeId]);

    if (!recipe) return null;

    const currentServings = localServings ?? recipe.servings ?? 1;
    const scaleFactor = currentServings / (recipe.servings || 1);

    return (
        <div className="min-h-screen pb-20 -mt-2 -mx-2 md:-mx-6 lg:-mx-8 font-sans bg-background relative">
            {showPrintModal && <PrintRecipeModal recipe={recipe} onClose={() => setShowPrintModal(false)} />}

            <div className="relative h-[22vh] md:h-[35vh] w-full overflow-hidden bg-slate-900 border-b border-border/40 shadow-inner">
                <img src={recipe.imageUrl} className="w-full h-full object-cover opacity-80 group-hover:grayscale-0 transition-all duration-700" alt={recipe.name} />
                <div className="absolute inset-0 bg-gradient-to-t from-background via-transparent to-black/20" />

                <div className="absolute top-3 left-4 right-4 flex justify-between items-start z-20">
                    <button onClick={() => navigate('/recipes')} className="p-2 bg-white/10 dark:bg-black/20 hover:bg-white/20 backdrop-blur-xl rounded-xl text-white border border-white/20 transition-all active:scale-90 shadow-lg">
                        <ArrowLeft className="h-5 w-5" />
                    </button>

                    <div className="flex items-center gap-1.5 p-1.5 bg-black/40 backdrop-blur-2xl rounded-2xl border border-white/10 shadow-2xl">
                        <div className="flex items-center bg-white/10 rounded-xl px-1">
                             <button onClick={() => setLocalServings(Math.max(1, currentServings - 1))} className="w-8 h-8 flex items-center justify-center text-white hover:bg-white/20 rounded-lg font-black transition-all active:scale-90 text-xs">-</button>
                             <div className="px-2 text-center min-w-[30px]">
                                <input 
                                    type="number" 
                                    value={currentServings} 
                                    onChange={(e) => setLocalServings(Math.max(1, parseInt(e.target.value) || 1))}
                                    className="block w-full bg-transparent text-center font-black text-xs text-white tabular-nums outline-none appearance-none"
                                />
                             </div>
                             <button onClick={() => setLocalServings(currentServings + 1)} className="w-8 h-8 flex items-center justify-center text-white hover:bg-white/20 rounded-lg font-black transition-all active:scale-90 text-xs">+</button>
                        </div>

                        <button onClick={() => setShowPrintModal(true)} className="h-9 w-9 flex items-center justify-center text-white/80 hover:text-white hover:bg-white/10 rounded-xl transition-all" title="Print Recipe">
                            <Printer className="h-4.5 w-4.5" />
                        </button>

                        <button 
                            onClick={() => navigate(`/recipes/${recipeId}/logs?servings=${currentServings}`)}
                            className="h-9 px-4 bg-primary text-black rounded-xl font-black text-[11px] uppercase tracking-widest shadow-xl shadow-primary/20 hover:brightness-110 active:scale-95 transition-all flex items-center gap-2"
                        >
                            <ChefHat className="h-4 w-4" />
                            <span className="hidden xs:inline">Service</span>
                        </button>

                        <button 
                            onClick={() => navigate(`/recipes/${recipe.id}/edit`)} 
                            className="h-9 w-9 flex items-center justify-center text-white/80 hover:text-white hover:bg-white/10 rounded-xl transition-all border-l border-white/10 ml-0.5"
                            title="Edit Recipe"
                        >
                            <Edit className="h-4.5 w-4.5" />
                        </button>

                        <motion.button 
                            initial={{ scale: 0.8, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            onClick={() => navigate(`/recipes/${recipeId}/logs`)}
                            className={cn(
                                "h-9 px-3.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center gap-2 ml-0.5 shadow-lg",
                                activeSessionsCount > 0 
                                    ? "bg-emerald-500 text-white shadow-emerald-500/20 hover:brightness-110" 
                                    : "bg-white/10 text-white border border-white/10 hover:bg-white/20"
                            )}
                            title={`Mission Logs (${activeSessionsCount} active)`}
                        >
                            <History className="h-4 w-4" />
                            <span className="hidden sm:inline">Logs</span>
                            {activeSessionsCount > 0 && (
                                <span className="flex h-2 w-2 rounded-full bg-white animate-pulse" />
                            )}
                        </motion.button>
                    </div>
                </div>

                <div className="absolute bottom-6 left-6 right-6 max-w-7xl mx-auto">
                    <motion.div initial={{ y: 20, opacity: 0 }} animate={{ y: 0, opacity: 1 }}>
                        <div className="flex flex-wrap gap-2 mb-2">
                            <span className="px-3 py-1 rounded-lg bg-primary text-black text-[9px] font-black uppercase tracking-widest shadow-xl shadow-primary/20">{recipe.category}</span>
                            <span className="px-3 py-1 rounded-lg bg-black/40 text-white backdrop-blur-md border border-white/10 text-[9px] font-black uppercase tracking-widest">{recipe.cuisine}</span>
                        </div>
                        <h1 className="text-3xl md:text-5xl font-black text-white leading-tight tracking-tighter uppercase">{recipe.name}</h1>
                    </motion.div>
                </div>
            </div>

            <div className="max-w-7xl mx-auto px-4 md:px-8 mt-8">
                <div className="grid grid-cols-4 gap-3 mb-8">
                    {[
                        { label: 'KCAL', val: Math.round((recipe.nutrition?.calories || 0) * scaleFactor), color: 'text-orange-500 bg-orange-500/10 border-orange-500/20' },
                        { label: 'PRO', val: Math.round((recipe.nutrition?.protein || 0) * scaleFactor) + 'g', color: 'text-blue-500 bg-blue-500/10 border-blue-500/20' },
                        { label: 'CARB', val: Math.round((recipe.nutrition?.carbs || 0) * scaleFactor) + 'g', color: 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20' },
                        { label: 'FAT', val: Math.round((recipe.nutrition?.fat || 0) * scaleFactor) + 'g', color: 'text-pink-500 bg-pink-500/10 border-pink-500/20' }
                    ].map(stat => (
                        <div key={stat.label} className={cn("border py-3 px-2 rounded-xl flex flex-col items-center justify-center transition-all shadow-sm", stat.color)}>
                            <p className="text-[8px] font-black uppercase tracking-[0.15em] opacity-70 mb-1">{stat.label}</p>
                            <p className="text-sm md:text-lg font-black tabular-nums">{stat.val}</p>
                        </div>
                    ))}
                </div>

                <div className="flex gap-1.5 p-1.5 bg-card border border-border/60 rounded-2xl mb-8 overflow-x-auto scrollbar-hide shadow-inner">
                    {[
                        { id: 'ingredients', label: 'Prep', icon: ListOrdered },
                        { id: 'steps', label: 'Method', icon: Utensils },
                        { id: 'cost', label: 'Finance', icon: Calculator },
                        { id: 'nutrition', label: 'Vitality', icon: HeartPulse }
                    ].map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id as any)}
                            className={cn(
                                "flex-1 min-w-[90px] py-3 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 transition-all",
                                activeTab === tab.id 
                                    ? "bg-background text-primary shadow-xl ring-1 ring-border/30" 
                                    : "text-muted-foreground hover:text-foreground hover:bg-muted/50"
                            )}
                        >
                            <tab.icon className="h-4 w-4" /> {tab.label}
                        </button>
                    ))}
                </div>

                <div className="min-h-[400px]">
                    <AnimatePresence mode="wait">
                        <motion.div key={activeTab} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.2 }}>
                            {activeTab === 'ingredients' && <IngredientsTab recipe={recipe} scaleFactor={scaleFactor} pantryIngredients={pantryIngredients} onUpdatePantryItem={updateIngredient} onUpdateRecipe={updateRecipe} />}
                            {activeTab === 'steps' && <StepsTab steps={recipe.steps} />}
                            {activeTab === 'cost' && <CostTab recipe={recipe} scaleFactor={scaleFactor} pantryIngredients={pantryIngredients} />}
                            {activeTab === 'nutrition' && <NutritionTab recipe={recipe} scaleFactor={scaleFactor} />}
                        </motion.div>
                    </AnimatePresence>
                </div>
            </div>
        </div>
    );
}

