                    <span className={cn('relative z-10 text-[11px] font-black uppercase tracking-[0.1em] transition-all', isActive ? 'text-black' : 'text-muted-foreground group-hover:text-foreground')}>{label}</span>
                    {isActive && (
                        <motion.div initial={{ x: -100 }} animate={{ x: 0 }} className="absolute right-4">
                            <div className="h-1.5 w-1.5 rounded-full bg-black" />
                        </motion.div>
                    )}
                </>
            )}
          </NavLink>
        ))}
      </nav>

      <div className="p-6 mt-auto">
        <div className="bg-card border border-border/60 p-5 rounded-[2rem] shadow-sm hover:border-primary/40 transition-all cursor-pointer group relative overflow-hidden">
            <div className="absolute top-0 left-0 w-1 h-full bg-primary opacity-20 group-hover:opacity-100 transition-opacity" />
            <div className="flex items-center gap-4">
                <div className="h-12 w-12 rounded-2xl bg-muted/40 flex items-center justify-center border border-border/40 shadow-inner group-hover:bg-primary/10 transition-colors">
                    <User className="h-6 w-6 text-foreground" />
                </div>
                <div className="flex-1 min-w-0">
                    <p className="text-xs font-black text-foreground truncate leading-none uppercase tracking-tight">Executive Chef</p>
                    <p className="text-[9px] text-muted-foreground/60 font-black tracking-widest truncate uppercase mt-1.5">Terminal Active</p>
                </div>
                <LogOut className="h-4 w-4 text-muted-foreground/30 group-hover:text-red-500 transition-colors" />
            </div>
        </div>
      </div>
    </aside>
  );
};

