import React, { useState, useMemo, useEffect, useRef } from 'react';
import { useParams, useNavigate, useSearchParams } from 'react-router-dom';
import { useData } from '../context/DataContext';
import { 
    Play, Pause, RotateCcw, PartyPopper, ArrowLeft, 
    Check, BookOpen, Utensils, CheckSquare, Clock, ChevronRight,
    Users, Plus, Minus, Timer, ListChecks,
    Lock, AlertCircle, Volume2, VolumeX, FastForward, Activity,
    Save, History, LogOut, RefreshCw, X, Tag
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { cn, playTickSound } from '../lib/utils';
import { CookingSession } from '../types';

const CompactTimer: React.FC<{ timeLeft: number; totalTime: number; isRunning: boolean; onToggle: () => void; onReset: () => void; }> = ({ timeLeft, totalTime, isRunning, onToggle, onReset }) => {
    const progress = totalTime > 0 ? timeLeft / totalTime : 0;
    const formatTime = (s: number) => `${Math.floor(s / 60)}:${((s % 60) || 0).toString().padStart(2, '0')}`;

    return (
        <div className="flex flex-col items-center bg-card border border-border/50 p-4 md:p-6 rounded-[2rem] shadow-sm w-full">
             <div className="relative h-28 w-28 md:h-40 md:w-40 flex items-center justify-center mb-6">
                 <svg className="absolute inset-0 transform -rotate-90 w-full h-full">
                    <circle cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="1.5" className="text-muted/10" />
                    <motion.circle
                        cx="50%" cy="50%" r="44%" fill="transparent" stroke="currentColor" strokeWidth="3" strokeLinecap="round"
                        initial={{ strokeDashoffset: 400 }}
                        animate={{ strokeDashoffset: 400 - (400 * progress) }}
                        transition={{ duration: 1, ease: "linear" }}
                        style={{ strokeDasharray: 400 }}
                        className="text-primary"
                    />
                </svg>
                <div className="flex flex-col items-center z-10">
                    <span className="text-3xl md:text-5xl font-black tabular-nums tracking-tighter text-foreground font-mono">{formatTime(timeLeft)}</span>
                    <span className="text-[7px] font-black uppercase text-muted-foreground tracking-[0.4em] mt-1">Countdown</span>
                </div>
                {isRunning && (
                    <motion.div 
                        animate={{ scale: [1, 1.05, 1], opacity: [0.1, 0.2, 0.1] }}
                        transition={{ repeat: Infinity, duration: 1 }}
                        className="absolute inset-0 bg-primary rounded-full -z-0"
                    />
                )}
             </div>
             <div className="flex gap-2 w-full max-w-[280px]">
                <button 
                    onClick={onReset} 
                    className="w-12 h-12 rounded-xl bg-muted/40 hover:bg-muted text-muted-foreground flex items-center justify-center transition-all active:scale-90 border border-border/40"
                    title="Reset Timer"
                >
                    <RotateCcw className="h-4 w-4"/>
                </button>
                <button 
                    onClick={onToggle} 
                    className={cn(
                        "flex-1 h-12 rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all shadow-xl", 
                        isRunning 
                            ? "bg-red-500 text-white shadow-red-500/20" 
                            : "bg-primary text-black shadow-primary/20 hover:scale-[1.02]"
                    )}
                >
                    {isRunning ? <Pause className="h-5 w-5 fill-current"/> : <Play className="h-5 w-5 fill-current"/>}
                    <span>{isRunning ? 'Pause' : 'Ignite'}</span>
                </button>
             </div>
        </div>
    );
};

export default function CookingModePage() {
    const { recipeId } = useParams<{ recipeId: string }>();
    const [searchParams] = useSearchParams();
    const initialServings = searchParams.get('servings') ? parseInt(searchParams.get('servings')!) : 1;
    const requestedSessionId = searchParams.get('sessionId');
    const { getRecipeById, cookingSessions, addCookingSession, updateCookingSession } = useData();
    const navigate = useNavigate();
    const recipe = getRecipeById(recipeId || '');

    const activeStepRef = useRef<HTMLDivElement>(null);

    const [currentStepIndex, setCurrentStepIndex] = useState(0);
    const [localServings, setLocalServings] = useState(initialServings);
    const [isFinished, setIsFinished] = useState(false);
    const [timeLeft, setTimeLeft] = useState(0);
    const [isTimerRunning, setIsTimerRunning] = useState(false);
    const [completedIngs, setCompletedIngs] = useState<Set<string>>(new Set());
    const [isSpeaking, setIsSpeaking] = useState(false);
    const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
    const [isSaving, setIsSaving] = useState(false);
    const [showResumeModal, setShowResumeModal] = useState(false);
    const [showSaveNamingModal, setShowSaveNamingModal] = useState(false);
    const [sessionNameInput, setSessionNameInput] = useState('');

    const steps = recipe?.steps || [];
    const scaleFactor = recipe ? localServings / recipe.servings : 1;

    useEffect(() => {
        if (!recipeId) return;
        if (requestedSessionId) {
            const specificSession = cookingSessions.find(s => s.id === requestedSessionId);
            if (specificSession) {
                setActiveSessionId(specificSession.id);
                setCurrentStepIndex(specificSession.currentStep || 0);
                setCompletedIngs(new Set(specificSession.completedIngredients || []));
                setLocalServings(specificSession.servings || initialServings);
                setSessionNameInput(specificSession.sessionName || '');
                return;
            }
        }
        const activeSession = cookingSessions.find(s => s.recipeId === recipeId && s.status === 'in_progress');
        if (activeSession) setShowResumeModal(true);
        else createNewSession();
    }, [recipeId, requestedSessionId]);

    const createNewSession = async () => {
        const id = `sess_${Date.now()}`;
        const defaultName = `Station @ ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
        const newSession: CookingSession = {
            id,
            recipeId: recipeId!,
            servings: localServings,
            currentStep: 0,
            completedIngredients: [],
            startTime: new Date(),
            status: 'in_progress',
            sessionName: defaultName
        };
        setActiveSessionId(id);
        setSessionNameInput(defaultName);
        addCookingSession(newSession);
    };

    const handleResume = () => {
        const activeSession = cookingSessions.find(s => s.recipeId === recipeId && s.status === 'in_progress');
        if (activeSession) {
            setActiveSessionId(activeSession.id);
            setCurrentStepIndex(activeSession.currentStep || 0);
            setCompletedIngs(new Set(activeSession.completedIngredients || []));
            setLocalServings(activeSession.servings || initialServings);
            setSessionNameInput(activeSession.sessionName || '');
        }
        setShowResumeModal(false);
    };

    const handleStartFresh = () => {
        const activeSession = cookingSessions.find(s => s.recipeId === recipeId && s.status === 'in_progress');
        if (activeSession) updateCookingSession(activeSession.id, { status: 'abandoned', endTime: new Date() });
        createNewSession();
        setShowResumeModal(false);
    };

    useEffect(() => {
        if (!activeSessionId) return;
        const saveProgress = async () => {
            setIsSaving(true);
            try {
                await updateCookingSession(activeSessionId, {
                    currentStep: currentStepIndex,
                    completedIngredients: Array.from(completedIngs),
                    servings: localServings
                });
            } finally {
                setTimeout(() => setIsSaving(false), 800);
            }
        };
        const timer = setTimeout(saveProgress, 1000);
        return () => clearTimeout(timer);
    }, [currentStepIndex, completedIngs, localServings, activeSessionId]);

    const currentStepIngredients = useMemo(() => {
        if (!recipe) return [];
        const currentStepData = steps[currentStepIndex];
        if (currentStepData?.linkedIngredientIds && currentStepData.linkedIngredientIds.length > 0) {
            const allIngredients = recipe.ingredientSections.flatMap(s => s.ingredients);
            return allIngredients.filter(ing => currentStepData.linkedIngredientIds!.includes(ing.id));
        }
        const stepNum = currentStepData?.stepNumber || (currentStepIndex + 1);
        return recipe.ingredientSections[stepNum - 1]?.ingredients || [];
    }, [recipe, currentStepIndex, steps]);

    const isCurrentStepTasksCompleted = useMemo(() => {
        if (currentStepIngredients.length === 0) return true;
        return currentStepIngredients.every(ing => completedIngs.has(ing.id));
    }, [currentStepIngredients, completedIngs]);

    const speakInstruction = () => {
        if ('speechSynthesis' in window) {
            window.speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(steps[currentStepIndex].instruction);
            utterance.onstart = () => setIsSpeaking(true);
            utterance.onend = () => setIsSpeaking(false);
            window.speechSynthesis.speak(utterance);
        }
    };

    useEffect(() => {
        if (steps[currentStepIndex]?.duration) setTimeLeft(steps[currentStepIndex].duration! * 60);
        else setTimeLeft(0);
        setIsTimerRunning(false);
        activeStepRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, [currentStepIndex, steps]);

    // Timer loop with tick sound
    useEffect(() => {
        let interval: any;
        if (isTimerRunning && timeLeft > 0) {
            interval = setInterval(() => {
                setTimeLeft(p => {
                    if (p > 1) playTickSound(); // Play sound for every tick
                    return p - 1;
                });
            }, 1000);
        } else if (timeLeft === 0) {
            setIsTimerRunning(false);
        }
        return () => clearInterval(interval);
    }, [isTimerRunning, timeLeft]);

    const toggleIngredient = (id: string) => {
        setCompletedIngs(prev => {
            const next = new Set(prev);
            if (next.has(id)) next.delete(id);
            else next.add(id);
            return next;
        });
    };

    const handleFinish = async () => {
        if (activeSessionId) await updateCookingSession(activeSessionId, { status: 'completed', endTime: new Date() });
        setIsFinished(true);
    };

    const handleSaveAndExitRequest = () => setShowSaveNamingModal(true);

    const handleConfirmSaveExit = async () => {
        if (activeSessionId) {
            await updateCookingSession(activeSessionId, { 
                sessionName: sessionNameInput || `Station @ ${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}` 
            });
        }
        navigate(`/recipes/${recipeId}`);
    };

    if (!recipe) return null;

    if (isFinished) {
        return (
            <div className="fixed inset-0 bg-background z-[200] flex items-center justify-center p-4 font-sans text-foreground">
                <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} className="max-w-md w-full bg-card p-8 rounded-[2rem] border border-border shadow-2xl text-center">
                    <div className="h-16 w-16 bg-primary/10 text-primary rounded-full flex items-center justify-center mx-auto mb-6">
                        <PartyPopper className="h-8 w-8" />
                    </div>
                    <h1 className="text-2xl font-black text-foreground mb-2 tracking-tighter uppercase">Service Completed</h1>
                    <p className="text-[10px] text-muted-foreground mb-8 font-bold leading-relaxed uppercase tracking-widest">{recipe.name} IS READY FOR PLATING.</p>
                    <button onClick={() => navigate(`/recipes/${recipeId}`)} className="w-full py-4 bg-primary text-white rounded-xl font-black text-[10px] uppercase tracking-[0.3em] shadow-xl hover:brightness-105 active:scale-[0.99] transition-all">Exit Console</button>
                </motion.div>
            </div>
        );
    }

    const progressPercent = Math.round(((currentStepIndex + 1) / (steps.length || 1)) * 100);

    return (
        <div className="fixed inset-0 bg-background z-[150] flex flex-col font-sans overflow-hidden text-foreground">
            <AnimatePresence>
                {showResumeModal && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[300] bg-black/80 backdrop-blur-md flex items-center justify-center p-4">
                        <motion.div initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }} className="bg-card w-full max-w-sm rounded-[2rem] border border-border shadow-2xl p-8 text-center">
                            <History className="h-10 w-10 text-primary mx-auto mb-4" />
                            <h2 className="text-xl font-black text-foreground mb-2 uppercase tracking-tight">Active Logs Found</h2>
                            <p className="text-xs text-muted-foreground mb-6 font-medium leading-relaxed uppercase tracking-tighter">We found an ongoing session. Resume established protocol?</p>
                            <div className="space-y-2">
                                <button onClick={handleResume} className="w-full py-4 bg-primary text-black rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all">Resume Session</button>
                                <button onClick={handleStartFresh} className="w-full py-4 bg-muted text-muted-foreground rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-muted/80">Override & Restart</button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
                {showSaveNamingModal && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[300] bg-black/80 backdrop-blur-md flex items-center justify-center p-4">
                        <motion.div initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }} className="bg-card w-full max-w-sm rounded-[2.5rem] border border-border shadow-2xl overflow-hidden p-8">
                            <Tag className="h-10 w-10 text-primary mx-auto mb-4" />
                            <h2 className="text-xl font-black text-foreground mb-1 uppercase tracking-tight text-center">Mission Label</h2>
                            <p className="text-[10px] text-muted-foreground mb-6 font-bold uppercase tracking-widest text-center">Identifying this service run</p>
                            <input autoFocus value={sessionNameInput} onChange={e => setSessionNameInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleConfirmSaveExit()} placeholder="e.g. DINNER RUSH 01" className="w-full h-14 px-4 rounded-xl bg-muted/30 border border-border focus:ring-2 focus:ring-primary/20 focus:border-primary text-sm font-black uppercase tracking-tight transition-all text-center mb-6 text-foreground" />
                            <div className="space-y-2">
                                <button onClick={handleConfirmSaveExit} className="w-full py-4 bg-primary text-black rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all">Archive & Exit</button>
                                <button onClick={() => setShowSaveNamingModal(false)} className="w-full py-4 text-[9px] font-black text-muted-foreground uppercase tracking-widest">Back to Console</button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            <div className="bg-card border-b border-border/40 h-14 md:h-20 flex items-stretch sticky top-0 z-30 shadow-sm px-4 md:px-12">
                <div className="flex items-center flex-1 min-w-0">
                    <button onClick={handleSaveAndExitRequest} className="p-2 hover:bg-muted rounded-xl transition-all active:scale-90 mr-4 border border-border/40">
                        <ArrowLeft className="h-5 w-5 text-muted-foreground"/>
                    </button>
                    <div className="min-w-0">
                        <h2 className="text-xs md:text-lg font-black text-foreground tracking-tight truncate uppercase leading-none">{recipe.name}</h2>
                        <div className="flex items-center gap-3 mt-1.5">
                            <span className="flex h-2 w-2 rounded-full bg-primary animate-pulse"></span>
                            <span className="text-[8px] md:text-[10px] font-black uppercase text-primary tracking-widest leading-none">
                                {sessionNameInput || 'Unlabeled Station'} &bull; Step {currentStepIndex + 1}/{steps.length} 
                                {isSaving && <span className="ml-2 opacity-40 italic tracking-normal">(Syncing...)</span>}
                            </span>
                        </div>
                    </div>
                </div>

                <div className="flex items-center justify-end gap-3 md:gap-6">
                    <button onClick={handleSaveAndExitRequest} className="hidden lg:flex items-center gap-2 px-4 py-2.5 rounded-xl border border-border/60 text-[10px] font-black uppercase tracking-widest hover:bg-muted transition-all text-foreground">
                        <Save className="h-4 w-4" /> Save Logs
                    </button>
                    <div className="flex items-center gap-2 bg-muted/20 p-1 rounded-xl border border-border/40">
                        <button onClick={() => setLocalServings(Math.max(1, localServings - 1))} className="h-8 w-8 md:h-12 md:w-12 rounded-lg bg-background shadow-sm border border-border/50 flex items-center justify-center text-muted-foreground hover:text-primary transition-all active:scale-90"><Minus className="h-4 w-4" strokeWidth={3} /></button>
                        <div className="flex flex-col items-center px-3">
                            <input type="number" min="1" value={localServings} onChange={(e) => setLocalServings(Math.max(1, parseInt(e.target.value) || 1))} className="w-10 md:w-14 bg-transparent text-center text-xs md:text-lg font-black tabular-nums text-foreground outline-none border-none focus:ring-0" />
                            <span className="text-[7px] font-black uppercase text-muted-foreground tracking-widest leading-none">Units</span>
                        </div>
                        <button onClick={() => setLocalServings(localServings + 1)} className="h-8 w-8 md:h-12 md:w-12 rounded-lg bg-primary shadow-md flex items-center justify-center text-black transition-all active:scale-90"><Plus className="h-4 w-4" strokeWidth={3} /></button>
                    </div>
                </div>
            </div>

            <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
                <div className="w-full md:w-1/2 lg:w-3/5 overflow-y-auto p-4 md:p-12 md:border-r border-border/30 bg-background scrollbar-hide">
                    <div className="max-w-3xl mx-auto space-y-12 pb-32">
                        <div className="flex items-center gap-3 px-2">
                            <ListChecks className="h-5 w-5 text-primary" />
                            <h3 className="text-[10px] md:text-xs font-black uppercase tracking-[0.4em] text-muted-foreground/60">Operational Feed</h3>
                            <div className="h-px flex-1 bg-border/20"></div>
                        </div>

                        <div className="space-y-6">
                            <AnimatePresence mode="wait">
                                {steps.map((step, idx) => {
                                    const isActive = currentStepIndex === idx;
                                    const isDone = currentStepIndex > idx;
                                    if (!isActive && !isDone) return null;
                                    return (
                                        <motion.div key={step.id} ref={isActive ? activeStepRef : null} initial={isActive ? { x: -20, opacity: 0 } : false} animate={{ x: 0, opacity: 1 }} className={cn("relative p-6 md:p-10 rounded-[2.5rem] border transition-all select-none", isActive ? "bg-card border-primary shadow-2xl ring-8 ring-primary/5 z-10" : "bg-muted/5 border-border/20 opacity-20 grayscale blur-[1px]")}>
                                            <div className="flex gap-6 items-start">
                                                <div className={cn("h-10 w-10 md:h-12 md:w-12 rounded-2xl border-2 flex items-center justify-center transition-all shrink-0", isActive ? "bg-primary border-primary text-black scale-110 shadow-lg" : "bg-background border-border text-muted-foreground")}>
                                                    {isDone ? <Check className="h-6 w-6" strokeWidth={4} /> : <span className="text-xs md:text-sm font-black">{idx + 1}</span>}
                                                </div>
                                                <div className="flex-1 min-w-0">
                                                    {isActive && (
                                                        <div className="flex items-center justify-between mb-4">
                                                            <div className="flex items-center gap-2">
                                                                <span className="flex h-2 w-2 rounded-full bg-primary animate-pulse"></span>
                                                                <span className="text-[10px] font-black text-primary uppercase tracking-[0.3em]">Direct Instruction</span>
                                                            </div>
                                                            <button onClick={speakInstruction} className={cn("h-10 w-10 rounded-2xl flex items-center justify-center transition-all", isSpeaking ? "bg-primary text-black" : "bg-muted/40 text-muted-foreground hover:bg-primary/10")}>{isSpeaking ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}</button>
                                                        </div>
                                                    )}
                                                    <p className={cn("font-black leading-tight transition-all uppercase tracking-tight", isActive ? "text-xl md:text-4xl text-foreground" : "text-lg text-muted-foreground", isDone && "line-through opacity-40")}>{step.instruction}</p>
                                                    {isActive && currentStepIndex < steps.length - 1 && (
                                                        <div className="mt-8 p-4 rounded-2xl bg-muted/10 border border-border/10">
                                                            <div className="flex items-center gap-2 mb-2">
                                                                <FastForward className="h-4 w-4 text-muted-foreground" />
                                                                <span className="text-[9px] font-black uppercase text-muted-foreground tracking-widest">Upcoming Node</span>
                                                            </div>
                                                            <p className="text-[10px] font-bold text-muted-foreground/60 uppercase line-clamp-1">{steps[currentStepIndex + 1].instruction}</p>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        </motion.div>
                                    );
                                })}
                            </AnimatePresence>
                        </div>
                    </div>
                </div>

                <div className="w-full md:w-1/2 lg:w-2/5 overflow-y-auto p-4 md:p-12 bg-muted/30 scrollbar-hide">
                    <div className="max-w-xl mx-auto space-y-10">
                        <div className="animate-in fade-in slide-in-from-right duration-300">
                            <div className="flex items-center gap-3 mb-4 px-2">
                                <Timer className="h-5 w-5 text-muted-foreground" />
                                <h3 className="text-[10px] md:text-xs font-black uppercase tracking-[0.4em] text-muted-foreground/60">Flow Control</h3>
                                <div className="h-px flex-1 bg-border/20"></div>
                            </div>
                            {steps[currentStepIndex]?.duration ? (
                                <CompactTimer timeLeft={timeLeft} totalTime={steps[currentStepIndex].duration! * 60} isRunning={isTimerRunning} onToggle={() => setIsTimerRunning(!isTimerRunning)} onReset={() => setTimeLeft(steps[currentStepIndex].duration! * 60)} />
                            ) : (
                                <div className="bg-card border border-dashed border-border/60 p-12 rounded-[2.5rem] w-full flex flex-col items-center justify-center text-muted-foreground/20 opacity-50">
                                    <Clock className="h-10 w-10 mb-3" />
                                    <span className="text-[10px] font-black uppercase tracking-[0.5em]">No Timed Req.</span>
                                </div>
                            )}
                        </div>

                        <div className="animate-in fade-in slide-in-from-right duration-500">
                            <div className="flex items-center justify-between mb-4 px-2">
                                <div className="flex items-center gap-3">
                                    <Utensils className="h-5 w-5 text-muted-foreground" />
                                    <h3 className="text-[10px] md:text-xs font-black uppercase tracking-[0.4em] text-muted-foreground/60">Asset List</h3>
                                </div>
                                <span className={cn("text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full border transition-all shadow-sm", isCurrentStepTasksCompleted ? "bg-emerald-500 text-white border-emerald-500" : "bg-primary text-black border-primary")}>
                                    {completedIngs.size} / {currentStepIngredients.length} Ready
                                </span>
                            </div>

                            <div className="grid grid-cols-1 gap-3">
                                {currentStepIngredients.length > 0 ? (
                                    currentStepIngredients.map((ing, idx) => {
                                        const isDone = completedIngs.has(ing.id);
                                        return (
                                            <motion.div key={ing.id} layout onClick={() => toggleIngredient(ing.id)} className={cn("group relative flex flex-col gap-3 p-5 rounded-[2rem] border transition-all cursor-pointer select-none shadow-sm", isDone ? "bg-emerald-50 dark:bg-emerald-950/20 border-emerald-500/30" : "bg-card border-border/60 hover:border-primary/40")}>
                                                <div className="flex items-center gap-4">
                                                    <div className={cn("w-10 h-10 rounded-xl border-2 flex items-center justify-center transition-all shrink-0", isDone ? "bg-emerald-500 border-emerald-500 text-white" : "border-border bg-muted/20 text-muted-foreground")}>
                                                        {isDone ? <Check className="h-5 w-5 stroke-[4]" /> : <span className="text-xs font-black">{idx + 1}</span>}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <p className={cn("text-sm md:text-base font-black truncate leading-none uppercase tracking-tight", isDone ? "line-through text-muted-foreground/40" : "text-foreground")}>{ing.name}</p>
                                                        <p className={cn("text-[10px] font-bold uppercase tracking-widest mt-1.5", isDone ? "text-emerald-500/40" : "text-primary")}>{(ing.quantity * scaleFactor).toFixed(1)} {ing.unit}</p>
                                                    </div>
                                                </div>
                                            </motion.div>
                                        );
                                    })
                                ) : (
                                    <div className="py-20 text-center text-muted-foreground/10 flex flex-col items-center gap-4 border border-dashed border-border/20 rounded-[2.5rem] bg-muted/5">
                                        <Activity className="h-12 w-12 opacity-20" />
                                        <p className="text-[10px] font-black uppercase tracking-[0.5em]">Direct Processing</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="bg-card border-t border-border/40 h-16 md:h-24 flex items-center px-4 md:px-12 shadow-2xl z-40">
                <div className="max-w-7xl mx-auto w-full flex items-center justify-between gap-6">
                    <button disabled={currentStepIndex === 0} onClick={() => setCurrentStepIndex(c => c - 1)} className="h-10 md:h-14 px-6 rounded-2xl border border-border/60 flex items-center gap-3 hover:bg-muted disabled:opacity-5 transition-all active:scale-95 shadow-sm font-black text-[10px] uppercase tracking-widest text-foreground"><ArrowLeft className="h-5 w-5" /> Prev</button>
                    <div className="flex-1 flex flex-col items-center gap-3 max-w-2xl px-6">
                        <div className="flex items-center gap-1 h-2 w-full bg-muted/20 rounded-full overflow-hidden">
                            {steps.map((_, i) => (
                                <div key={i} className={cn("h-full transition-all duration-1000", i === currentStepIndex ? "flex-[10] bg-primary" : i < currentStepIndex ? "flex-1 bg-primary/40" : "flex-1 bg-muted/50")} />
                            ))}
                        </div>
                        <div className="flex items-center gap-6">
                             {!isCurrentStepTasksCompleted && <span className="flex items-center gap-2 text-[9px] font-black uppercase text-red-500 tracking-[0.2em] animate-pulse"><AlertCircle className="h-3 w-3" /> Audit Assets</span>}
                             <span className="text-[10px] font-black uppercase text-foreground tracking-[0.3em] font-mono">Mission Progress: {progressPercent}%</span>
                        </div>
                    </div>
                    <button disabled={!isCurrentStepTasksCompleted} onClick={() => currentStepIndex === steps.length - 1 ? handleFinish() : setCurrentStepIndex(c => c + 1)} className={cn("h-10 md:h-14 px-8 md:px-16 rounded-2xl font-black text-[10px] md:text-xs uppercase tracking-[0.3em] flex items-center gap-3 transition-all active:scale-95 shadow-2xl disabled:opacity-20 disabled:grayscale", currentStepIndex === steps.length - 1 ? "bg-emerald-500 text-white shadow-emerald-500/40" : "bg-primary text-black shadow-primary/40 hover:scale-[1.02]")}>
                        <span>{currentStepIndex === steps.length - 1 ? "Complete" : "Next"}</span>
                        {isCurrentStepTasksCompleted ? <ChevronRight className="h-5 w-5" /> : <Lock className="h-4 w-4" />}
                    </button>
                </div>
            </div>
        </div>
    );
}

import { type ClassValue, clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// --- Sound Utils ---
// Subtle tick sound for the cooking timer using Web Audio API
export const playTickSound = () => {
  if (typeof window === 'undefined') return;
  try {
    const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioContextClass) return;
    const audioCtx = new AudioContextClass();
    const oscillator = audioCtx.createOscillator();
    const gainNode = audioCtx.createGain();

    oscillator.connect(gainNode);
    gainNode.connect(audioCtx.destination);

    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(1000, audioCtx.currentTime);
    gainNode.gain.setValueAtTime(0.05, audioCtx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.01, audioCtx.currentTime + 0.05);

    oscillator.start();
    oscillator.stop(audioCtx.currentTime + 0.05);
  } catch (e) {
    // Silent fail if audio context is blocked or unavailable
  }
};

