const SettingsPage: React.FC = () => {
  const { theme, setTheme, isDarkMode, toggleDarkMode } = useTheme();
  const { seedDatabase, recipes, ingredients, orders, cookingSessions } = useData();
  const [activeTab, setActiveTab] = useState<'profile' | 'appearance' | 'data'>('profile');

  // --- Profile State ---
  const [kitchenName, setKitchenName] = useState('');
  const [chefName, setChefName] = useState('');
  const [currency, setCurrency] = useState(getGlobalCurrency());
  const [isSavingProfile, setIsSavingProfile] = useState(false);

  // --- Data State ---
  const [seeding, setSeeding] = useState(false);
  const [seeded, setSeeded] = useState(false);
  const [exporting, setExporting] = useState(false);

  // Load Preferences
  useEffect(() => {
    setKitchenName(localStorage.getItem('chef_kitchen_name') || 'iKitchen Pro');
    setChefName(localStorage.getItem('chef_name') || 'Head Chef');
  }, []);

  const handleSaveProfile = () => {
    setIsSavingProfile(true);
    localStorage.setItem('chef_kitchen_name', kitchenName);
    localStorage.setItem('chef_name', chefName);

    if (currency !== getGlobalCurrency()) {
        setGlobalCurrency(currency);
        window.dispatchEvent(new Event('profile-update'));
        setTimeout(() => {
             window.location.reload(); 
        }, 800);
    } else {
        window.dispatchEvent(new Event('profile-update'));
        setTimeout(() => setIsSavingProfile(false), 1000);
    }
  };

  const handleSeed = async () => {
      if (window.confirm("This will overwrite existing data with default mock data. Continue?")) {
          setSeeding(true);
          try {
              await seedDatabase();
              setSeeded(true);
              setTimeout(() => setSeeded(false), 3000);
          } catch (e) {
              console.error(e);
          } finally {
              setSeeding(false);
          }
      }
  };

  const handleExportData = async () => {
    setExporting(true);
    try {
        const data = {
            version: "2.1",
            exportedAt: new Date().toISOString(),
            kitchen: kitchenName,
            recipes,
            ingredients,
            orders,
            cookingSessions
        };
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `iKitchen_Backup_${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    } finally {
        setExporting(false);
    }
  };

  const tabs = [
      { id: 'profile', label: 'Establishment', icon: Building, desc: 'Identity & Localization' },
      { id: 'appearance', label: 'Terminal Interface', icon: Palette, desc: 'Themes & Aesthetics' },
      { id: 'data', label: 'System Storage', icon: HardDrive, desc: 'Backups & Persistence' },
  ];

  return (
    <div className="max-w-6xl mx-auto space-y-10 pb-32 font-sans px-2 md:px-4">
      {/* Header Section */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 border-b border-border/40 pb-8 mt-4">
        <motion.div initial={{ x: -20, opacity: 0 }} animate={{ x: 0, opacity: 1 }}>
            <div className="flex items-center gap-3 mb-2">
                <div className="h-10 w-10 bg-primary/10 rounded-2xl flex items-center justify-center border border-primary/20">
                    <ShieldCheck className="h-6 w-6 text-primary" />
                </div>
                <h1 className="text-4xl font-black tracking-tighter uppercase text-foreground">Control Center</h1>
            </div>
            <p className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.4em] ml-1">Configuration & Protocol Management</p>
        </motion.div>

        <div className="flex items-center gap-2 px-4 py-2 bg-card border border-border/60 rounded-2xl shadow-sm">
            <span className="flex h-2 w-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <span className="text-[9px] font-black uppercase text-muted-foreground tracking-widest">Environment Secure</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          {/* Settings Sidebar Nav */}
          <div className="lg:col-span-4 space-y-6">
              <div className="bg-card border border-border/60 rounded-3xl p-3 shadow-xl shadow-primary/5">
                <div className="space-y-1.5">
                    {tabs.map(tab => (
                        <button
                            key={tab.id}
                            onClick={() => setActiveTab(tab.id as any)}
                            className={cn(
                                "w-full flex items-center gap-5 px-5 py-4 rounded-2xl transition-all duration-300 group relative overflow-hidden",
                                activeTab === tab.id 
                                    ? "bg-primary text-primary-foreground shadow-xl shadow-primary/20 scale-[1.02]" 
                                    : "hover:bg-muted/60 text-muted-foreground hover:text-foreground"
                            )}
                        >
                            <div className={cn(
                                "p-2.5 rounded-xl shrink-0 transition-all duration-500",
                                activeTab === tab.id ? "bg-white/20 rotate-0" : "bg-muted group-hover:bg-background group-hover:-rotate-6"
                            )}>
                                <tab.icon className="h-5 w-5" />
                            </div>
                            <div className="text-left min-w-0">
                                <p className="text-xs font-black uppercase tracking-widest leading-none mb-1">{tab.label}</p>
                                <p className={cn("text-[9px] font-bold tracking-tight truncate", activeTab === tab.id ? "text-white/60" : "text-muted-foreground/60")}>{tab.desc}</p>
                            </div>
                            {activeTab === tab.id && (
                                <motion.div layoutId="tab-pill" className="absolute right-4">
                                    <ChevronRight className="h-4 w-4 text-white/50" />
                                </motion.div>
                            )}
                        </button>
                    ))}
                </div>
              </div>

              {/* Status Mini-Card */}
              <div className="bg-zinc-900 dark:bg-primary/5 p-6 rounded-[2.5rem] border border-white/5 relative overflow-hidden group">
                    <div className="absolute -right-4 -bottom-4 opacity-[0.03] group-hover:opacity-[0.08] transition-opacity">
                        <Zap className="h-32 w-32 text-primary rotate-12" />
