const RecipeBlockCard: React.FC<{ 
    recipe: Recipe; 
    onToggleFavorite: (recipe: Recipe) => void;
    pantryIngredients: Ingredient[];
}> = React.memo(({ recipe, onToggleFavorite, pantryIngredients }) => {
    const navigate = useNavigate();

    const { pricePerPerson } = useMemo(() => {
        let rawTotal = 0;
        recipe.ingredientSections?.forEach(sec => {
            sec.ingredients?.forEach(ing => {
                const pantryItem = pantryIngredients.find(pi => pi.id === ing.ingredientId);
                const unitCost = ing.manualCostPerUnit !== undefined ? ing.manualCostPerUnit : (pantryItem?.costPerUnit || 0);
                rawTotal += (ing.quantity * unitCost);
            });
        });
        const overhead = rawTotal * (recipe.overheadPercentage / 100);
        const profit = rawTotal * (recipe.profitMargin / 100);
        const totalMenuPrice = rawTotal + overhead + profit;
        return { pricePerPerson: totalMenuPrice / (recipe.servings || 1) };
    }, [recipe, pantryIngredients]);

    return (
        <motion.div 
            layout
            onClick={() => navigate(`/recipes/${recipe.id}`)}
            className="group block-entry bg-card border border-border/40 rounded-3xl overflow-hidden cursor-pointer transition-all hover:shadow-2xl hover:-translate-y-1 relative"
        >
            <div className="relative h-48 -mx-6 -mt-6 mb-6 overflow-hidden">
                <img src={recipe.imageUrl} alt={recipe.name} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
