                     <button 
                        onClick={(e) => { e.stopPropagation(); onToggleFavorite(recipe); }}
                        className="h-10 w-10 bg-white/20 backdrop-blur-xl border border-white/20 rounded-xl flex items-center justify-center text-white hover:bg-white/40 transition-all"
                    >
                         <Star className={cn("h-5 w-5 transition-all", recipe.isFavorite && "fill-yellow-400 text-yellow-400 scale-110")} />
                    </button>
                </div>
                <div className="absolute bottom-4 left-4 flex gap-2">
                    <span className="px-3 py-1 bg-primary text-white rounded-lg text-[9px] font-black uppercase tracking-widest shadow-xl">
