import React from 'react';
import { Ingredient } from '../../types';
import { formatCurrency, cn } from '../../lib/utils';
import { CheckSquare, Edit, Clock, AlertCircle } from 'lucide-react';
import { QuickStockControl } from './QuickStockControl';

const getDaysRemaining = (item: Ingredient) => {
    if (!item.last_verified) return 999;
    const lastVerified = new Date(item.last_verified);
    const expiryDate = new Date(lastVerified);
    expiryDate.setDate(expiryDate.getDate() + (item.shelf_life_days || 365));
    const now = new Date();
    const diffTime = expiryDate.getTime() - now.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const getCategoryIcon = (category: string) => {
    switch (category) {
        case 'Dairy': return '🥛';
        case 'Vegetable': return '🥬';
        case 'Protein': return '🥩';
        case 'Spices': return '🌶️';
        case 'Grains': return '🌾';
        case 'Oils & Fats': return '🫒';
        case 'Condiments': return '🧂';
        case 'Fruit': return '🍎';
        case 'Baking': return '🥖';
        case 'Beverage': return '🥤';
        default: return '📦';
    }
};

export const PantryItemCard: React.FC<{
    item: Ingredient;
    onEdit: (item: Ingredient) => void;
    isSelected: boolean;
    isSelectionMode: boolean;
    onToggleSelect: (id: string) => void;
    onUpdate: (item: Ingredient) => void;
    viewMode?: 'grid' | 'list';
}> = React.memo(({ item, onEdit, isSelected, isSelectionMode, onToggleSelect, onUpdate, viewMode = 'grid' }) => {
    const daysRemaining = getDaysRemaining(item);
    const isExpired = daysRemaining < 0;
    const isExpiringSoon = daysRemaining <= 7 && !isExpired;
    const isLowStock = item.packagesInStock <= 2;

    return (
        <div 
            onClick={() => isSelectionMode ? onToggleSelect(item.id) : onEdit(item)}
            className={cn(
                "group relative line-entry border border-border/40 transition-all select-none hover:shadow-xl hover:scale-[1.01] bg-card",
                isSelected ? "border-primary ring-1 ring-primary/20 shadow-xl" : "shadow-sm",
                isLowStock && "border-l-4 border-l-red-500"
            )}
        >
            <div className="flex items-center gap-5 w-full">
                {isSelectionMode && (
                    <div className={cn(
                        "h-5 w-5 rounded-md flex items-center justify-center transition-colors border",
                        isSelected ? "bg-primary border-primary text-white" : "bg-transparent border-border/60"
                    )}>
                        {isSelected && <CheckSquare className="h-4 w-4" />}
                    </div>
                )}

                <div className="h-12 w-12 rounded-2xl bg-muted/40 flex items-center justify-center text-xl shadow-inner border border-border/50 shrink-0 relative">
                    {getCategoryIcon(item.category)}
                    {isLowStock && (
                        <div className="absolute -top-1 -right-1 h-3.5 w-3.5 rounded-full bg-red-500 border-2 border-card" />
                    )}
                </div>

                <div className="flex-1 min-w-0 grid grid-cols-12 gap-4 items-center">
                    <div className="col-span-12 md:col-span-5 lg:col-span-6">
                        <h4 className="font-extrabold text-base text-foreground truncate uppercase tracking-tighter">{item.name}</h4>
                        <div className="flex items-center gap-3 mt-1">
                            <span className="text-[10px] font-black text-muted-foreground uppercase tracking-widest">{item.category}</span>
                            <div className="h-1 w-1 rounded-full bg-border" />
                            <span className="text-[10px] font-bold text-primary font-mono">{formatCurrency(item.costPerUnit)} / {item.baseUnit}</span>
                        </div>
                    </div>

                    <div className="hidden md:flex md:col-span-2 flex-col items-start">
                        <p className="text-[8px] font-black text-muted-foreground uppercase tracking-[0.2em] mb-1">Stock Health</p>
                        <div className={cn(
                            "flex items-center gap-1.5 text-[10px] font-black uppercase tracking-tighter px-2 py-0.5 rounded-lg border",
                            isExpired ? "bg-red-50 text-red-600 border-red-100" : 
                            isExpiringSoon ? "bg-orange-50 text-orange-600 border-orange-100" : 
                            "bg-emerald-50 text-emerald-600 border-emerald-100"
                        )}>
                            <Clock className="h-3 w-3" />
                            {isExpired ? 'REPLACE' : `${daysRemaining}D`}
                        </div>
                    </div>

                    <div className="col-span-12 md:col-span-5 lg:col-span-4 flex items-center justify-end gap-3" onClick={e => e.stopPropagation()}>
                        <QuickStockControl item={item} onUpdate={onUpdate} className="h-10 px-2" />
                        {!isSelectionMode && (
                             <button 
                                onClick={(e) => { e.stopPropagation(); onEdit(item); }}
                                className="h-10 w-10 rounded-2xl bg-muted/40 text-muted-foreground flex items-center justify-center hover:bg-zinc-900 hover:text-white dark:hover:bg-primary dark:hover:text-black transition-all border border-border/50"
                            >
                                <Edit className="h-4 w-4" />
                            </button>
