    Sun, Moon, Database, Check, Loader2, User, Building, Globe, 
    Download, AlertTriangle, Save, Bell, Volume2, Shield, 
    Palette, Zap, Trash2, ChevronRight, Briefcase, Mail,
    ShieldCheck, Info, RefreshCw, Layers, Monitor, HardDrive
} from 'lucide-react';
