  { name: 'light', color: 'bg-zinc-100', secondary: 'bg-zinc-800', label: 'Studio White' },
  { name: 'ocean', color: 'bg-blue-600', secondary: 'bg-blue-100', label: 'Pacific Blue' },
  { name: 'sunset', color: 'bg-orange-500', secondary: 'bg-orange-100', label: 'Amber Coast' },
