                    <ShieldCheck className="h-6 w-6 text-primary" />
                </div>
                <h1 className="text-4xl font-black tracking-tighter uppercase text-foreground">Control Center</h1>
            </div>
            <p className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.4em] ml-1">Configuration & Protocol Management</p>
        </motion.div>

        <div className="flex items-center gap-2 px-4 py-2 bg-card border border-border/60 rounded-2xl shadow-sm">
