                                <p className="text-xs font-black uppercase tracking-widest leading-none mb-1">{tab.label}</p>
                                <p className={cn("text-[9px] font-bold tracking-tight truncate", activeTab === tab.id ? "text-white/60" : "text-muted-foreground/60")}>{tab.desc}</p>
                            </div>
