                        </div>
                        <span className="text-[11px] font-black uppercase tracking-widest text-white dark:text-foreground">System Status</span>
                    </div>
                    <div className="space-y-3">
                         <div className="flex justify-between text-[10px] font-bold uppercase text-white/50 dark:text-muted-foreground">
