                            <span>Connectivity</span>
                            <span className="text-emerald-500">Encrypted / Active</span>
                         </div>
                         <div className="h-px bg-white/5" />
                         <div className="flex justify-between text-[10px] font-bold uppercase text-white/50 dark:text-muted-foreground">
                            <span>Persistence</span>
                            <span className="text-blue-400">Localized Cache</span>
                         </div>
                    </div>
              </div>

              <div className="flex items-center gap-3 p-4 bg-muted/20 border border-dashed border-border/60 rounded-3xl">
                    <Info className="h-4 w-4 text-muted-foreground/40 shrink-0" />
                    <p className="text-[9px] text-muted-foreground/80 leading-relaxed font-bold uppercase tracking-tight">
                        Protocol v2.4.1 initialized. All terminal configurations are automatically synchronized with the primary data stream.
                    </p>
              </div>
          </div>

          {/* Main Settings Content */}
          <div className="lg:col-span-8 min-w-0">
            <AnimatePresence mode="wait">
                {activeTab === 'profile' && (
                    <motion.div 
                        key="profile" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }}
                        className="space-y-8"
                    >
                        <Card className="rounded-[2.5rem] border-border/60 shadow-2xl overflow-hidden">
                            <CardHeader className="bg-muted/10 border-b border-border/40 p-8">
                                <div className="flex items-center gap-4">
                                    <div className="h-14 w-14 bg-primary text-white rounded-2xl flex items-center justify-center shadow-lg shadow-primary/20">
                                        <Building className="h-7 w-7" />
                                    </div>
                                    <div>
                                        <CardTitle className="text-xl uppercase tracking-tighter font-black text-foreground">Established Branding</CardTitle>
                                        <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest mt-1">Institutional Identity Profile</p>
                                    </div>
                                </div>
                            </CardHeader>
                            <CardContent className="p-8 space-y-8">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                    <div className="space-y-3">
                                        <label className="text-[10px] font-black uppercase text-muted-foreground tracking-[0.2em] px-1 flex items-center gap-2">
                                            Establishment Designation
                                        </label>
                                        <div className="relative group">
                                            <Building className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground/40 group-focus-within:text-primary transition-colors" />
