                                                className="w-full h-14 pl-12 pr-4 rounded-2xl bg-muted/30 border border-border focus:ring-4 focus:ring-primary/5 focus:border-primary text-sm font-black uppercase tracking-tight transition-all"
                                                placeholder="KITCHEN NAME..."
