                        filteredOrders.map(order => (
                            <OrderCard 
                                key={order.id} 
                                order={order} 
                                onStatusChange={updateOrderStatus}
                                onDelete={deleteOrder}
                                onEdit={(o) => setEditingOrder(o)}
                                onShowInvoice={setInvoiceOrder}
                                onShowTicket={setTicketOrder}
                                recipes={recipes}
                            />
                        ))
                    ) : (
                        <motion.div
                            key="empty"
                            variants={ANIMATION_VARIANTS.item}
                            className="flex flex-col items-center justify-center py-32 text-center bg-muted/5 border-2 border-dashed border-border/40 rounded-[3rem]"
                        >
                            <div className="h-24 w-24 bg-muted/20 rounded-full flex items-center justify-center mb-6">
                                <Terminal className="h-12 w-12 text-muted-foreground/30" />
                            </div>
                            <h3 className="text-xl font-black text-muted-foreground uppercase tracking-[0.2em]">Data Stream Silent</h3>
                            <p className="text-xs text-muted-foreground/60 font-bold uppercase mt-2 tracking-widest">No active orders matching current sector parameters.</p>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* Global Modals */}
            <AnimatePresence>
                {showOrderForm && (
                    <OrderFormModal 
                        recipes={recipes} 
                        onClose={() => setShowOrderForm(false)}
                        onSave={handleCreateOrder}
                    />
                )}
                {editingOrder && (
                    <OrderFormModal 
                        recipes={recipes} 
                        initialData={editingOrder}
                        onClose={() => setEditingOrder(null)}
                        onSave={handleUpdateOrder}
                    />
                )}
                {invoiceOrder && (
                    <InvoiceModal 
                        order={invoiceOrder}
                        onClose={() => setInvoiceOrder(null)}
                    />
                )}
                 {ticketOrder && (
                    <KitchenTicketModal 
                        order={ticketOrder}
                        onClose={() => setTicketOrder(null)}
                    />
                )}
            </AnimatePresence>
        </motion.div>
    );
};

