export const StatusBadge: React.FC<{ status: OrderStatus }> = ({ status }) => {
    const config: Record<OrderStatus, { color: string; icon: any; label: string }> = {
        pending_approval: { color: 'bg-amber-50 text-amber-600 border-amber-200/60 dark:bg-amber-900/20 dark:text-amber-400 dark:border-amber-800/40', icon: ListOrdered, label: 'Waiting Approval' },
        approved: { color: 'bg-blue-50 text-blue-600 border-blue-200/60 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800/40', icon: CheckCircle2, label: 'Operational' },
        processing: { color: 'bg-orange-50 text-orange-600 border-orange-200/60 dark:bg-orange-900/20 dark:text-orange-400 dark:border-orange-800/40', icon: Utensils, label: 'Firing Phase' },
        completed: { color: 'bg-emerald-50 text-emerald-600 border-emerald-200/60 dark:bg-emerald-900/20 dark:text-emerald-400 dark:border-emerald-800/40', icon: PackageCheck, label: 'Dispatched' },
        cancelled: { color: 'bg-red-50 text-red-600 border-red-200/60 dark:bg-red-900/20 dark:text-red-400 dark:border-red-800/40', icon: X, label: 'Protocol Halted' },
    };
    const { color, icon: Icon, label } = config[status];
    return (
        <span className={cn("flex items-center gap-2 px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] border shadow-sm", color)}>
            <Icon className="h-3.5 w-3.5" /> {label}
        </span>
    );
};

export const PriorityBadge: React.FC<{ priority: OrderPriority }> = ({ priority }) => {
    const config = {
        low: { color: 'bg-slate-50 text-slate-500 border-slate-200/50 dark:bg-slate-900/40 dark:text-slate-500 dark:border-slate-800', icon: ArrowRight, label: 'Standard' },
        normal: { color: 'bg-blue-50/50 text-blue-600 border-blue-100/50 dark:bg-blue-900/20 dark:text-blue-400 dark:border-blue-800/30', icon: Zap, label: 'Priority' },
        high: { color: 'bg-red-50 text-red-600 border-red-200/60 animate-pulse dark:bg-red-900/20 dark:text-red-400 dark:border-red-800/50', icon: ShieldAlert, label: 'Critical' },
    };

    const safePriority = (priority && config[priority]) ? priority : 'normal';
    const { color, icon: Icon, label } = config[safePriority];

    return (
        <span className={cn("flex items-center gap-1.5 px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest border", color)}>
            <Icon className="h-3 w-3" /> {label}
        </span>
    );
};

import React, { useState, useMemo, useCallback } from 'react';
import { useData } from '../context/DataContext';
import { 
    Search, DollarSign, Utensils, Plus, 
    LayoutDashboard, Clock, CheckCircle2, Terminal,
    Activity, ShoppingBag
} from 'lucide-react';
