                        <ShoppingBag className="h-5 w-5 text-primary" />
                    </div>
                    <div>
                        <h1 className="text-xl font-black tracking-tight text-foreground uppercase leading-none">Orders Terminal</h1>
                        <p className="text-[9px] font-black text-muted-foreground uppercase tracking-widest mt-1.5 flex items-center gap-2">
                            <Activity className="h-2.5 w-2.5 text-emerald-500 animate-pulse" /> Operational Flux: Active
                        </p>
                    </div>
                </div>

                <button 
                    onClick={() => setShowOrderForm(true)}
                    className="h-10 px-4 bg-primary text-white rounded-lg font-black text-[10px] uppercase tracking-widest flex items-center gap-2 shadow-lg shadow-primary/20 hover:brightness-110 active:scale-95 transition-all"
                >
                    <Plus className="h-4 w-4" /> New Manifest
                </button>
            </motion.div>

            {/* Compact Metrics Strip */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="grid grid-cols-3 gap-2">
                {[
                    { label: 'Queued', val: metrics.pending, icon: Clock, color: 'text-amber-500' },
                    { label: 'Firing', val: metrics.active, icon: Utensils, color: 'text-blue-500' },
                    { label: 'Revenue', val: formatCurrency(metrics.revenue).split('.')[0], icon: DollarSign, color: 'text-emerald-500' }
