export const StatusBadge: React.FC<{ status: OrderStatus }> = ({ status }) => {
    const config: Record<OrderStatus, { color: string; icon: any; label: string }> = {
        pending_approval: { color: 'bg-amber-50 text-amber-600 border-amber-200/40 dark:bg-amber-900/20 dark:text-amber-400', icon: ListOrdered, label: 'Queued' },
        approved: { color: 'bg-blue-50 text-blue-600 border-blue-200/40 dark:bg-blue-900/20 dark:text-blue-400', icon: CheckCircle2, label: 'Active' },
        processing: { color: 'bg-orange-50 text-orange-600 border-orange-200/40 dark:bg-orange-900/20 dark:text-orange-400', icon: Utensils, label: 'Firing' },
        completed: { color: 'bg-emerald-50 text-emerald-600 border-emerald-200/40 dark:bg-emerald-900/20 dark:text-emerald-400', icon: PackageCheck, label: 'Done' },
        cancelled: { color: 'bg-red-50 text-red-600 border-red-200/40 dark:bg-red-900/20 dark:text-red-400', icon: X, label: 'Halted' },
    };
    const { color, icon: Icon, label } = config[status];
    return (
        <span className={cn("flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-widest border", color)}>
            <Icon className="h-2.5 w-2.5" /> {label}
        </span>
    );
};

export const PriorityBadge: React.FC<{ priority: OrderPriority }> = ({ priority }) => {
    const config = {
        low: { color: 'bg-slate-50 text-slate-500 border-slate-200/40', icon: AlertCircle, label: 'Standard' },
        normal: { color: 'bg-blue-50/50 text-blue-600 border-blue-100/40', icon: Zap, label: 'Priority' },
        high: { color: 'bg-red-50 text-red-600 border-red-200/40 animate-pulse', icon: ShieldAlert, label: 'Critical' },
    };

    const safePriority = (priority && config[priority]) ? priority : 'normal';
    const { color, icon: Icon, label } = config[safePriority];

    return (
        <span className={cn("flex items-center gap-1 px-1.5 py-0.5 rounded-md text-[7px] font-black uppercase tracking-widest border", color)}>
            <Icon className="h-2 w-2" /> {label}
        </span>
    );
};

