                                                                "h-12 rounded-lg border-2 transition-all flex flex-col items-center justify-center gap-1",
                                                                theme === t.name 
                                                                    ? "border-primary bg-primary/5 shadow-sm" 
                                                                    : "border-transparent bg-muted/40 hover:bg-muted/80"
