                                                        >
                                                            <div className={cn('h-3.5 w-3.5 rounded-full ring-offset-1', t.color, theme === t.name ? 'ring-1 ring-primary' : '')} />
                                                            <span className="text-[7px] font-black uppercase tracking-widest opacity-60">{t.label}</span>
                                                        </button>
