                {activeTab === 'data' && (
                    <motion.div 
                        key="data" initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -10 }}
                        className="space-y-4"
                    >
