                            <CardContent className="p-5 space-y-3">
                                <div className="flex items-center justify-between p-4 border border-border/60 rounded-xl bg-card hover:border-primary/40 transition-all gap-4 group">
                                    <div className="flex items-center gap-4">
                                        <div className="h-10 w-10 rounded-lg bg-blue-50 dark:bg-blue-900/20 text-blue-600 flex items-center justify-center shrink-0 border border-blue-100 dark:border-blue-900/30">
                                            <Download className="h-5 w-5" />
                                        </div>
                                        <div>
                                            <h4 className="text-[10px] font-black uppercase tracking-widest text-foreground leading-none mb-1">Encapsulated Export</h4>
                                            <p className="text-[8px] font-bold text-muted-foreground uppercase tracking-tight">Full manifest JSON backup</p>
                                        </div>
                                    </div>
                                    <button 
                                        onClick={handleExportData}
                                        disabled={exporting}
                                        className="h-9 px-4 rounded-lg bg-blue-600 text-white font-black text-[9px] uppercase tracking-widest shadow-md hover:brightness-110 active:scale-95 transition-all flex items-center gap-2 disabled:opacity-50"
                                    >
                                        {exporting ? <Loader2 className="h-3 w-3 animate-spin" /> : <Layers className="h-3 w-3" />}
                                        Run Export
                                    </button>
                                </div>

                                <div className="p-4 rounded-xl bg-muted/20 border border-border/60 flex items-start gap-4">
                                    <Shield className="h-4 w-4 text-primary shrink-0 mt-0.5" />
                                    <p className="text-[9px] text-muted-foreground font-black uppercase tracking-tight leading-relaxed">
                                        iKITCHEN operates a <span className="text-primary">Tier-1 Local Persistence</span> model. Data is stored in your secure browser sandbox.
                                    </p>
                                </div>
                            </CardContent>
                        </Card>

                        {/* Ultra Compact Danger Zone */}
                        <div className="bg-red-500/5 rounded-2xl border border-red-200/50 dark:border-red-900/20 p-4">
                             <div className="flex items-center justify-between gap-4">
                                <div className="flex items-center gap-3">
                                    <div className="h-10 w-10 rounded-lg bg-red-100 dark:bg-red-900/40 text-red-600 flex items-center justify-center border border-red-200 dark:border-red-900/50">
                                        <Trash2 className="h-5 w-5" />
                                    </div>
                                    <div>
                                        <h4 className="text-[10px] font-black uppercase tracking-widest text-foreground leading-none mb-1">Critical Purge</h4>
                                        <p className="text-[8px] font-bold text-red-600/60 uppercase tracking-tight">Destructive system reset</p>
                                    </div>
                                </div>
                                <button 
                                    onClick={handleSeed}
                                    disabled={seeding}
                                    className={cn(
                                        "h-9 px-5 rounded-lg font-black text-[9px] uppercase tracking-widest shadow-md transition-all flex items-center gap-2",
                                        seeded 
                                            ? "bg-emerald-600 text-white shadow-emerald-600/20" 
                                            : "bg-red-600 text-white shadow-red-600/20 hover:brightness-110 active:scale-95"
                                    )}
                                >
                                    {seeding ? <Loader2 className="h-3 w-3 animate-spin"/> : seeded ? <Check className="h-3 w-3" /> : <RefreshCw className="h-3 w-3" />}
                                    {seeded ? "Purged" : "Run Purge"}
                                </button>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
          </div>
      </div>
    </div>
  );
};

export default SettingsPage;

import React, { useState, useMemo, useRef, useCallback } from 'react';
import { useData } from '../context/DataContext';
import { Search, PlusCircle, Layers, CheckSquare, X, LayoutGrid, List as ListIcon, Group, Trash2, Boxes, Activity, Warehouse } from 'lucide-react';
import { formatCurrency, cn } from '../lib/utils';
import { AnimatePresence, motion } from 'framer-motion';
import { Ingredient } from '../types';
import { BatchUpdateModal } from '../components/pantry/BatchUpdateModal';
import { AddIngredientModal } from '../components/pantry/AddIngredientModal';
import { EditIngredientModal } from '../components/pantry/EditIngredientModal';
import { PantryItemCard } from '../components/pantry/PantryItemCard';

const CATEGORIES = ["Protein", "Vegetable", "Fruit", "Grains", "Dairy", "Spices", "Oils & Fats", "Baking", "Condiments", "Beverage", "Other"];

const PantryPage: React.FC = () => {
    const { ingredients, addIngredient, updateIngredient, deleteIngredient } = useData();
    const [searchQuery, setSearchQuery] = useState("");
    const [filterCategory, setFilterCategory] = useState("All");

    const [viewMode, setViewMode] = useState<'grid' | 'list'>('list');
    const [groupByCategory, setGroupByCategory] = useState(false);
    const [sortBy, setSortBy] = useState<'name' | 'stock' | 'cost'>('stock');
    const [showExpiringOnly, setShowExpiringOnly] = useState(false);

    const [showAddModal, setShowAddModal] = useState(false);
    const [editingIngredient, setEditingIngredient] = useState<Ingredient | null>(null);

    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [showBatchModal, setShowBatchModal] = useState(false);
    const [isSelectionMode, setIsSelectionMode] = useState(false);

    const totalValue = ingredients.reduce((sum, item) => sum + (item.costPerPackage * item.packagesInStock), 0);
    const lowStockCount = ingredients.filter(i => i.packagesInStock <= 2).length;
    const expiringSoonCount = ingredients.filter(i => {
         if (!i.last_verified) return false;
         const expiry = new Date(i.last_verified);
         expiry.setDate(expiry.getDate() + (i.shelf_life_days || 365));
         const diff = Math.ceil((expiry.getTime() - new Date().getTime()) / (1000 * 3600 * 24));
         return diff <= 7;
    }).length;

    const filteredIngredients = useMemo(() => {
        let items = ingredients.filter(item => {
            const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
            const matchesCategory = filterCategory === "All" || item.category === filterCategory;

            let isExpiring = false;
            if (item.last_verified) {
                 const expiry = new Date(item.last_verified);
                 expiry.setDate(expiry.getDate() + (item.shelf_life_days || 365));
                 const diff = Math.ceil((expiry.getTime() - new Date().getTime()) / (1000 * 3600 * 24));
                 isExpiring = diff <= 7;
            }

            const matchesExpiry = !showExpiringOnly || isExpiring;
            return matchesSearch && matchesCategory && matchesExpiry;
        });

        return items.sort((a, b) => {
            if (sortBy === 'name') return a.name.localeCompare(b.name);
            if (sortBy === 'stock') {
                if (a.packagesInStock <= 2 && b.packagesInStock > 2) return -1;
                if (a.packagesInStock > 2 && b.packagesInStock <= 2) return 1;
                return a.packagesInStock - b.packagesInStock;
            }
            if (sortBy === 'cost') return b.costPerUnit - a.costPerUnit;
            return 0;
        });
    }, [ingredients, searchQuery, filterCategory, sortBy, showExpiringOnly]);

    const groupedIngredients: Record<string, Ingredient[]> = useMemo(() => {
        if (!groupByCategory) return { 'Active Assets': filteredIngredients };
        return filteredIngredients.reduce((groups, item) => {
            const cat = item.category || 'Other';
            if (!groups[cat]) groups[cat] = [];
            groups[cat].push(item);
            return groups;
        }, {} as Record<string, Ingredient[]>);
    }, [filteredIngredients, groupByCategory]);

    const handleAddIngredient = useCallback((newIngredient: any) => {
        addIngredient(newIngredient);
        setShowAddModal(false);
    }, [addIngredient]);

    const handleUpdateIngredient = useCallback((updatedIngredient: Ingredient) => {
        updateIngredient(updatedIngredient);
        setEditingIngredient(null);
    }, [updateIngredient]);

    const handleBatchDelete = useCallback(() => {
        if (window.confirm(`Purge ${selectedIds.size} selected SKUs?`)) {
            selectedIds.forEach(id => deleteIngredient(id));
            setSelectedIds(new Set());
            setIsSelectionMode(false);
        }
    }, [selectedIds, deleteIngredient]);

    const toggleSelection = useCallback((id: string) => {
        setSelectedIds(prev => {
            const newSet = new Set(prev);
            if (newSet.has(id)) newSet.delete(id);
            else newSet.add(id);
            return newSet;
        });
    }, []);

    const handleBatchSave = useCallback((operation: 'add' | 'subtract' | 'set', value: number) => {
        selectedIds.forEach(id => {
            const item = ingredients.find(i => i.id === id);
            if (item) {
                let newStock = item.packagesInStock;
                if (operation === 'set') newStock = value;
                else if (operation === 'add') newStock += value;
                else if (operation === 'subtract') newStock = Math.max(0, newStock - value);

                const updated = {
                    ...item,
                    packagesInStock: newStock,
                    quantityInStock: newStock * item.packageSize,
                    last_verified: new Date()
                };
                updateIngredient(updated);
            }
        });
        setSelectedIds(new Set());
        setShowBatchModal(false);
        setIsSelectionMode(false);
    }, [selectedIds, ingredients, updateIngredient]);

    return (
        <div className="space-y-3 max-w-6xl mx-auto pb-24 md:pb-20 relative font-sans px-4 md:px-0">
            {/* High-Density Header */}
            <div className="flex items-center justify-between border-b border-border/40 pb-3">
                <div className="flex items-center gap-3">
                    <div className="h-9 w-9 bg-primary/10 rounded-xl flex items-center justify-center border border-primary/20">
                        <Warehouse className="h-4 w-4 text-primary" />
                    </div>
                    <div>
                        <h1 className="text-lg font-black tracking-tight text-foreground uppercase leading-none">Inventory Vault</h1>
                        <p className="text-[8px] font-black text-muted-foreground uppercase tracking-widest mt-1 flex items-center gap-2">
                            <Activity className="h-2 w-2 text-emerald-500 animate-pulse" /> Local Stock Synced
                        </p>
                    </div>
                </div>

                <button 
                    onClick={() => setShowAddModal(true)}
                    className="h-8 px-4 bg-primary text-white rounded-lg font-black text-[9px] uppercase tracking-widest flex items-center gap-2 shadow-lg shadow-primary/10 hover:brightness-110 active:scale-95 transition-all"
                >
                    <PlusCircle className="h-3.5 w-3.5" /> New Asset
                </button>
            </div>

            {/* Tight Stats Strip */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                <div className="bg-card border border-border/60 p-2.5 rounded-lg flex items-center justify-between">
                    <div className="min-w-0">
                        <p className="text-[7px] font-black text-muted-foreground uppercase tracking-widest leading-none mb-1">Gross Equity</p>
                        <p className="text-sm font-black text-foreground leading-none tabular-nums">{formatCurrency(totalValue).split('.')[0]}</p>
                    </div>
                    <Activity className="h-3 w-3 text-primary/30" />
                </div>
                <div className="bg-card border border-border/60 p-2.5 rounded-lg flex items-center justify-between">
                    <div className="min-w-0">
                        <p className="text-[7px] font-black text-muted-foreground uppercase tracking-widest leading-none mb-1">Total SKUs</p>
                        <p className="text-sm font-black text-foreground leading-none tabular-nums">{ingredients.length}</p>
                    </div>
                    <Boxes className="h-3 w-3 text-blue-500/30" />
                </div>
                <div className={cn("border p-2.5 rounded-lg flex items-center justify-between transition-all", lowStockCount > 0 ? "bg-red-50/50 border-red-200 dark:bg-red-950/20 dark:border-red-900" : "bg-card border-border/60")}>
                    <div className="min-w-0">
                        <p className={cn("text-[7px] font-black uppercase tracking-widest leading-none mb-1", lowStockCount > 0 ? "text-red-600" : "text-muted-foreground")}>Critical</p>
                        <p className={cn("text-sm font-black leading-none tabular-nums", lowStockCount > 0 ? "text-red-700" : "text-foreground")}>{lowStockCount}</p>
                    </div>
                    <ACTIVITY_ICON className={cn("h-3 w-3", lowStockCount > 0 ? "text-red-500/40" : "text-muted-foreground/30")} />
                </div>
                <div 
                    onClick={() => setShowExpiringOnly(!showExpiringOnly)}
                    className={cn("border p-2.5 rounded-lg flex items-center justify-between transition-all cursor-pointer", expiringSoonCount > 0 ? "bg-amber-50/50 border-amber-200 dark:bg-amber-950/20 dark:border-amber-900" : "bg-card border-border/60", showExpiringOnly && "ring-1 ring-primary")}
                >
                    <div className="min-w-0">
                        <p className={cn("text-[7px] font-black uppercase tracking-widest leading-none mb-1", expiringSoonCount > 0 ? "text-amber-600" : "text-muted-foreground")}>Vulnerable</p>
                        <p className={cn("text-sm font-black leading-none tabular-nums", expiringSoonCount > 0 ? "text-amber-700" : "text-foreground")}>{expiringSoonCount}</p>
                    </div>
                    <ACTIVITY_ICON className={cn("h-3 w-3", expiringSoonCount > 0 ? "text-amber-500/40" : "text-muted-foreground/30")} />
                </div>
            </div>

            {/* Tactical Control Bar */}
            <div className="sticky top-14 md:top-16 z-30 bg-background/90 backdrop-blur-xl py-2">
                <div className="bg-card border border-border/60 p-1 rounded-lg flex flex-col lg:flex-row gap-1.5 shadow-sm">
                    <div className="relative flex-grow">
                        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3 w-3 text-muted-foreground/50" />
                        <input 
                            placeholder="QUERY VAULT..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-8 pr-3 h-8 rounded-md bg-muted/30 border-transparent focus:bg-background focus:ring-1 focus:ring-primary/20 text-[10px] font-black uppercase tracking-widest transition-all"
                        />
                    </div>

                    <div className="flex gap-1 overflow-x-auto scrollbar-hide items-center px-1">
                        <div className="flex bg-muted/40 p-0.5 rounded-md">
                            <button onClick={() => setViewMode('grid')} className={cn("p-1.5 rounded transition-all", viewMode==='grid' ? "bg-white shadow-sm text-primary" : "text-muted-foreground")}>
                                <LayoutGrid className="h-3 w-3" />
                            </button>
                            <button onClick={() => setViewMode('list')} className={cn("p-1.5 rounded transition-all", viewMode==='list' ? "bg-white shadow-sm text-primary" : "text-muted-foreground")}>
                                <ListIcon className="h-3 w-3" />
                            </button>
                        </div>

                        <select 
                            value={filterCategory}
                            onChange={(e) => setFilterCategory(e.target.value)}
                            className="h-8 px-2 rounded-md bg-muted/30 border-transparent focus:ring-1 focus:ring-primary/20 text-[8px] font-black uppercase tracking-widest appearance-none min-w-[100px] text-center cursor-pointer"
                        >
                            <option value="All">Categories</option>
                            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>

                        <button 
                            onClick={() => setGroupByCategory(!groupByCategory)}
                            className={cn("h-8 px-3 rounded-md text-[8px] font-black uppercase tracking-widest flex items-center gap-2 transition-all border", groupByCategory ? "bg-primary/5 text-primary border-primary/20" : "bg-muted/30 text-muted-foreground border-transparent")}
                        >
                            <Group className="h-3 w-3" /> <span className="hidden sm:inline">Group</span>
                        </button>

                         <button 
                            onClick={() => setIsSelectionMode(!isSelectionMode)}
                            className={cn("h-8 px-3 rounded-md text-[8px] font-black uppercase tracking-widest flex items-center gap-2 transition-all border", isSelectionMode ? "bg-primary text-white border-primary shadow-sm" : "bg-muted/30 text-muted-foreground border-transparent")}
                        >
                            <CheckSquare className="h-3 w-3" /> <span className="hidden sm:inline">Mark</span>
                        </button>
                    </div>
                </div>
            </div>

            {/* Asset Manifest Feed */}
            <div className="min-h-[400px]">
                {filteredIngredients.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-20 bg-muted/5 border border-dashed border-border/40 rounded-2xl">
                        <Boxes className="h-10 w-10 text-muted-foreground/20 mb-4" />
                        <p className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.3em]">Manifest Empty</p>
                    </div>
                ) : (
                    <div className="space-y-6">
                         {Object.entries(groupedIngredients).map(([groupName, groupItems]) => (
                            <div key={groupName} className="space-y-2">
                                <div className="flex items-center gap-2 px-1">
                                    <h3 className="font-black text-[9px] uppercase tracking-[0.3em] text-muted-foreground/40">{groupName}</h3>
                                    <div className="h-px flex-1 bg-border/20"></div>
                                    <span className="text-[8px] font-black text-primary/60 uppercase">{groupItems.length} SKU</span>
                                </div>

                                <div className={cn(
                                    "grid gap-1.5 md:gap-2", 
                                    viewMode === 'grid' ? "grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5" : "grid-cols-1"
                                )}>
                                    <AnimatePresence mode="popLayout">
                                        {groupItems.map(item => (
                                            <motion.div key={item.id} layout initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                                                <PantryItemCard 
                                                    item={item} 
                                                    onEdit={setEditingIngredient}
                                                    isSelected={selectedIds.has(item.id)}
                                                    isSelectionMode={isSelectionMode}
                                                    onToggleSelect={toggleSelection}
                                                    onUpdate={updateIngredient}
                                                    viewMode={viewMode}
                                                />
                                            </motion.div>
                                        ))}
                                    </AnimatePresence>
                                </div>
                            </div>
                         ))}
                    </div>
                )}
            </div>

            {/* Operations Bar */}
            <AnimatePresence>
                {selectedIds.size > 0 && (
                    <motion.div 
                        initial={{ y: 50, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 50, opacity: 0 }}
                        className="fixed bottom-20 md:bottom-8 left-1/2 -translate-x-1/2 z-50 bg-zinc-900 text-white px-5 py-2.5 rounded-xl shadow-2xl flex items-center gap-4 border border-white/10"
                    >
                         <div className="bg-primary text-black font-black h-5 w-5 rounded flex items-center justify-center text-[9px]">
                            {selectedIds.size}
                         </div>

                        <div className="h-4 w-px bg-white/10"></div>

                        <div className="flex items-center gap-3">
                            <button onClick={() => setShowBatchModal(true)} className="text-[9px] font-black uppercase tracking-widest hover:text-primary transition-all flex items-center gap-1.5">
                                <Layers className="h-3 w-3" /> Re-Batch
                            </button>
                            <button onClick={handleBatchDelete} className="text-[9px] font-black uppercase tracking-widest hover:text-red-400 transition-all flex items-center gap-1.5">
                                <Trash2 className="h-3 w-3" /> Purge
                            </button>
                        </div>

                        <button onClick={() => { setSelectedIds(new Set()); setIsSelectionMode(false); }} className="p-1 hover:bg-white/10 rounded transition-all">
                            <X className="h-3 w-3" />
                        </button>
                    </motion.div>
                )}
            </AnimatePresence>

            <AnimatePresence>
                {showAddModal && <AddIngredientModal onClose={() => setShowAddModal(false)} onSave={handleAddIngredient} />}
                {editingIngredient && <EditIngredientModal ingredient={editingIngredient} onClose={() => setEditingIngredient(null)} onSave={handleUpdateIngredient} />}
                {showBatchModal && <BatchUpdateModal count={selectedIds.size} onClose={() => setShowBatchModal(false)} onSave={handleBatchSave} />}
            </AnimatePresence>
        </div>
    );
};

const ACTIVITY_ICON = ({ className }: { className?: string }) => <Activity className={className} />;

export default PantryPage;

import React from 'react';
import { Ingredient } from '../../types';
import { formatCurrency, cn } from '../../lib/utils';
import { CheckSquare, Edit, Clock } from 'lucide-react';
import { QuickStockControl } from './QuickStockControl';

const getDaysRemaining = (item: Ingredient) => {
    if (!item.last_verified) return 999;
    const lastVerified = new Date(item.last_verified);
    const expiryDate = new Date(lastVerified);
    expiryDate.setDate(expiryDate.getDate() + (item.shelf_life_days || 365));
    const now = new Date();
    const diffTime = expiryDate.getTime() - now.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const getCategoryIcon = (category: string) => {
    switch (category) {
        case 'Dairy': return '🥛';
        case 'Vegetable': return '🥬';
        case 'Protein': return '🥩';
        case 'Spices': return '🌶️';
        case 'Grains': return '🌾';
        case 'Oils & Fats': return '🫒';
        case 'Condiments': return '🧂';
        case 'Fruit': return '🍎';
        case 'Baking': return '🥖';
        case 'Beverage': return '🥤';
        default: return '📦';
    }
};

export const PantryItemCard: React.FC<{
    item: Ingredient;
    onEdit: (item: Ingredient) => void;
    isSelected: boolean;
    isSelectionMode: boolean;
    onToggleSelect: (id: string) => void;
    onUpdate: (item: Ingredient) => void;
    viewMode?: 'grid' | 'list';
}> = React.memo(({ item, onEdit, isSelected, isSelectionMode, onToggleSelect, onUpdate, viewMode = 'grid' }) => {
    const daysRemaining = getDaysRemaining(item);
    const isExpired = daysRemaining < 0;
    const isExpiringSoon = daysRemaining <= 7 && !isExpired;
    const isLowStock = item.packagesInStock <= 2;

    if (viewMode === 'list') {
        return (
            <div 
                onClick={() => isSelectionMode ? onToggleSelect(item.id) : onEdit(item)}
                className={cn(
                    "group relative flex items-center gap-3 p-1.5 bg-card border rounded-lg hover:border-primary/40 transition-all select-none",
                    isSelected ? "border-primary bg-primary/5" : "border-border/60 shadow-sm",
                    isLowStock && "border-l-4 border-l-red-500/60"
                )}
            >
                <div className="h-8 w-8 rounded-md bg-muted/40 flex items-center justify-center text-sm shadow-inner shrink-0 border border-border/40">
                    {getCategoryIcon(item.category)}
                </div>

                <div className="flex-1 min-w-0 flex items-center justify-between gap-4">
                    <div className="min-w-0 flex-1">
                        <h4 className="font-black text-[11px] text-foreground truncate uppercase tracking-tight leading-none mb-1">{item.name}</h4>
                        <div className="flex items-center gap-2">
                            <span className="text-[7px] font-black text-muted-foreground uppercase tracking-widest">{item.category}</span>
                            <span className="text-[7px] font-bold text-primary font-mono">{formatCurrency(item.costPerUnit)}/U</span>
                        </div>
                    </div>

                    <div className="hidden sm:block shrink-0">
                        <div className={cn(
                            "flex items-center gap-1 text-[8px] font-black uppercase tracking-tighter px-2 py-0.5 rounded border bg-background",
                            isExpired ? "text-red-600 border-red-200" : isExpiringSoon ? "text-amber-600 border-amber-200" : "text-emerald-600 border-emerald-200"
                        )}>
                            <Clock className="h-2 w-2" />
                            {daysRemaining < 0 ? 'PURGE' : `${daysRemaining}D`}
                        </div>
                    </div>

                    <div className="flex items-center gap-2" onClick={e => e.stopPropagation()}>
                        <QuickStockControl item={item} onUpdate={onUpdate} className="h-7 min-w-[80px]" />
                        {isSelectionMode && (
                             <div className={cn(
                                 "h-7 w-7 rounded-md flex items-center justify-center transition-colors border",
                                 isSelected ? "bg-primary border-primary text-white" : "bg-transparent border-muted-foreground/30"
                             )}>
                                {isSelected && <CheckSquare className="h-3.5 w-3.5" />}
                             </div>
                        )}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div 
            onClick={() => isSelectionMode ? onToggleSelect(item.id) : onEdit(item)}
            className={cn(
                "group relative bg-card rounded-xl transition-all duration-200 border select-none overflow-hidden h-full flex flex-col shadow-sm",
                isSelected ? "border-primary bg-primary/5" : "border-border/60 hover:border-primary/20",
                isLowStock && "border-l-4 border-l-red-500/60"
            )}
        >
            <div className="p-2.5 flex flex-col h-full gap-2.5">
                <div className="flex items-start gap-2">
                    <div className="h-8 w-8 rounded-lg bg-muted/40 flex items-center justify-center text-sm shrink-0 border border-border/40">
                        {getCategoryIcon(item.category)}
                    </div>

                    <div className="min-w-0 flex-1">
                        <h4 className="font-black text-[10px] text-foreground leading-tight uppercase tracking-tight truncate mb-1" title={item.name}>{item.name}</h4>
                        <div className={cn(
                            "inline-flex items-center gap-0.5 text-[7px] font-black uppercase tracking-tighter px-1.5 py-0.5 rounded-[3px] border bg-background",
                            isExpired ? "text-red-600 border-red-200" : isExpiringSoon ? "text-amber-600 border-amber-200" : "text-emerald-600 border-emerald-200"
                        )}>
                            <Clock className="h-2 w-2" /> {daysRemaining < 0 ? 'EXPIRED' : `${daysRemaining}D REM.`}
                        </div>
                    </div>
                </div>

                <div className="flex flex-col gap-2 mt-auto">
                    <div className="flex justify-between items-center border-t border-border/40 pt-2 px-0.5">
                        <div className="flex flex-col">
                            <span className="text-[7px] font-black text-muted-foreground uppercase tracking-widest leading-none mb-1">Price</span>
                            <span className="text-[9px] font-black text-foreground font-mono">{formatCurrency(item.costPerUnit)}</span>
                        </div>
                        <div className="text-right">
                            <span className="text-[7px] font-black text-muted-foreground uppercase tracking-widest leading-none mb-1">Cat</span>
                            <p className="text-[8px] font-black uppercase text-foreground">{item.category.slice(0,3)}</p>
                        </div>
                    </div>

                    <div className="flex items-center gap-1" onClick={e => e.stopPropagation()}>
                        <QuickStockControl item={item} onUpdate={onUpdate} className="flex-1 h-7" />
                        {!isSelectionMode && (
                             <button 
                                onClick={(e) => { e.stopPropagation(); onEdit(item); }}
                                className="h-7 w-7 rounded-md bg-muted/30 text-muted-foreground flex items-center justify-center hover:bg-primary/10 hover:text-primary transition-all border border-border/40"
                            >
                                <Edit className="h-3 w-3" />
                            </button>
                        )}
                        {isSelectionMode && (
                            <div className={cn(
                                "h-7 w-7 rounded-md flex items-center justify-center transition-colors border shadow-inner",
                                isSelected ? "bg-primary border-primary text-white" : "bg-muted/10 border-muted-foreground/20"
                            )}>
                               {isSelected && <CheckSquare className="h-3 w-3" />}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
});

