const CompactRecipeCard: React.FC<{ 
    recipe: Recipe; 
    viewMode: 'grid' | 'list';
    onToggleFavorite: (recipe: Recipe) => void;
    pantryIngredients: Ingredient[];
}> = React.memo(({ recipe, viewMode, onToggleFavorite, pantryIngredients }) => {
    const navigate = useNavigate();

    const { pricePerPerson, difficultyColor } = useMemo(() => {
        let rawTotal = 0;
        recipe.ingredientSections?.forEach(sec => {
            sec.ingredients?.forEach(ing => {
                const pantryItem = pantryIngredients.find(pi => pi.id === ing.ingredientId);
                const unitCost = ing.manualCostPerUnit !== undefined ? ing.manualCostPerUnit : (pantryItem?.costPerUnit || 0);
                rawTotal += (ing.quantity * unitCost);
            });
        });
        const overhead = rawTotal * (recipe.overheadPercentage / 100);
        const profit = rawTotal * (recipe.profitMargin / 100);
        const totalMenuPrice = rawTotal + overhead + profit;
        const servings = recipe.servings || 1;

        const diffColors: Record<string, string> = {
            'Easy': 'text-emerald-500',
            'Medium': 'text-amber-500',
            'Hard': 'text-red-500'
        };

        return {
            pricePerPerson: totalMenuPrice / servings,
            difficultyColor: diffColors[recipe.difficulty] || 'text-muted-foreground'
        };
    }, [recipe, pantryIngredients]);

    const handleFavoriteClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        onToggleFavorite(recipe);
    };

    if (viewMode === 'list') {
        return (
            <motion.div 
                layout
                onClick={() => navigate(`/recipes/${recipe.id}`)}
                className="group flex flex-row items-center gap-3 p-1.5 bg-card border border-border/60 rounded-xl hover:border-primary/40 cursor-pointer transition-all active:scale-[0.99] shadow-sm"
            >
                <div className="relative w-10 h-10 flex-shrink-0 rounded-lg overflow-hidden bg-muted border border-border/40">
                    <img src={recipe.imageUrl} alt={recipe.name} className="w-full h-full object-cover" />
                </div>

                <div className="flex-grow min-w-0">
                    <div className="flex items-center gap-2">
                        <h3 className="font-black text-foreground text-[11px] truncate uppercase tracking-tight leading-none">{recipe.name}</h3>
                        {recipe.isFavorite && <Star className="h-2.5 w-2.5 fill-yellow-400 text-yellow-400 shrink-0" />}
                    </div>
                    <div className="flex items-center gap-2 mt-1 text-[8px] text-muted-foreground uppercase font-black tracking-widest">
                        <span>{recipe.category}</span>
                        <span className="opacity-30">&bull;</span>
                        <span className="text-primary/70">{recipe.cuisine}</span>
                    </div>
                </div>

                <div className="flex items-center gap-4 shrink-0 px-2">
                    <div className="hidden sm:flex items-center gap-1.5 text-[8px] font-black text-muted-foreground uppercase">
                        <Clock className="h-2.5 w-2.5" /> {recipe.prepTime + recipe.cookTime}m
                    </div>
                    <div className="text-right border-l border-border/40 pl-4">
                        <div className="text-[10px] font-black text-primary font-mono leading-none">{formatCurrency(pricePerPerson)}</div>
                        <div className="text-[7px] text-muted-foreground font-black uppercase tracking-tighter mt-0.5">PER PERSON</div>
                    </div>
                </div>
            </motion.div>
        );
    }

    return (
        <motion.div 
            layout
            onClick={() => navigate(`/recipes/${recipe.id}`)}
            className="group bg-card rounded-xl overflow-hidden cursor-pointer flex flex-col hover:border-primary/30 transition-all border border-border/60 shadow-sm"
        >
            <div className="relative h-24 overflow-hidden border-b border-border/40">
                <img src={recipe.imageUrl} alt={recipe.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500 grayscale-[0.2] group-hover:grayscale-0" />
                <div className="absolute top-1.5 right-1.5">
                     <button onClick={handleFavoriteClick} className="h-6 w-6 bg-black/40 backdrop-blur-md rounded-md text-white hover:bg-black/60 flex items-center justify-center transition-all">
                         <Star className={cn("h-3 w-3", recipe.isFavorite && "fill-yellow-400 text-yellow-400")} />
                    </button>
                </div>
                <div className="absolute bottom-1.5 left-1.5 flex gap-1">
                    <span className="text-[7px] font-black bg-black/60 backdrop-blur-md text-white px-1.5 py-0.5 rounded uppercase tracking-widest border border-white/10">
                        {recipe.cuisine}
                    </span>
                </div>
            </div>

            <div className="p-2.5 flex flex-col flex-grow">
                <h3 className="font-black text-[10px] uppercase tracking-tight line-clamp-1 group-hover:text-primary transition-colors leading-tight">{recipe.name}</h3>

                <div className="mt-2 space-y-1.5">
                    <div className="flex items-center justify-between text-[7px] font-black text-muted-foreground uppercase tracking-widest">
                        <div className="flex items-center gap-1">
                            <Clock className="h-2 w-2" /> {recipe.prepTime + recipe.cookTime}m
                        </div>
                        <div className={cn("flex items-center gap-1", difficultyColor)}>
                            <Activity className="h-2 w-2" /> {recipe.difficulty}
                        </div>
                    </div>

                    <div className="pt-2 border-t border-border/40 flex items-center justify-between">
                        <div className="flex flex-col">
                            <span className="text-[9px] font-black text-foreground font-mono leading-none">{formatCurrency(pricePerPerson)}</span>
                            <span className="text-[6px] font-black text-muted-foreground uppercase tracking-tighter">Cost / Srv</span>
                        </div>
                        <div className="h-6 w-6 rounded-lg bg-primary/5 text-primary flex items-center justify-center border border-primary/10 group-hover:bg-primary group-hover:text-white transition-all">
                            <Plus className="h-3 w-3" />
                        </div>
                    </div>
                </div>
            </div>
        </motion.div>
    );
});

export default function RecipesPage() {
    const { recipes, updateRecipe, ingredients } = useData();
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedCategory, setSelectedCategory] = useState("All");
    const [viewMode, setViewMode] = useState<"list" | "grid">("grid");

    const filteredRecipes = useMemo(() => {
        return recipes.filter(r => {
            const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
            const matchesCategory = selectedCategory === "All" || r.category === selectedCategory;
            return matchesSearch && matchesCategory;
        }).sort((a, b) => {
            if (a.isFavorite && !b.isFavorite) return -1;
            if (!a.isFavorite && b.isFavorite) return 1;
            return 0;
        });
    }, [recipes, searchQuery, selectedCategory]);

    const toggleFavorite = useCallback((recipe: Recipe) => {
        updateRecipe({ ...recipe, isFavorite: !recipe.isFavorite });
    }, [updateRecipe]);

    return (
        <motion.div 
            initial="hidden" animate="visible" variants={ANIMATION_VARIANTS.container}
            className="space-y-3 max-w-7xl mx-auto pb-24 font-sans px-4 md:px-0"
        >
            {/* High-Density Header */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="flex items-center justify-between gap-4 border-b border-border/40 pb-3">
                <div className="flex items-center gap-3">
                    <div className="h-9 w-9 bg-primary/10 rounded-xl flex items-center justify-center border border-primary/20">
                        <BookOpen className="h-4 w-4 text-primary" />
                    </div>
                    <div>
                        <h1 className="text-lg font-black tracking-tight text-foreground uppercase leading-none">Recipe Hub</h1>
                        <p className="text-[8px] font-black text-muted-foreground uppercase tracking-widest mt-1.5 flex items-center gap-2">
                            <Activity className="h-2.5 w-2.5 text-emerald-500 animate-pulse" /> Database status: {recipes.length} Units Active
                        </p>
                    </div>
                </div>

                <Link to="/recipes/new" className="h-8 px-4 bg-primary text-white rounded-lg font-black text-[9px] uppercase tracking-widest flex items-center gap-2 shadow-lg shadow-primary/10 hover:brightness-110 active:scale-95 transition-all">
                    <Plus className="h-3.5 w-3.5" /> New Recipe
                </Link>
            </motion.div>

            {/* Tactical Search & Filter Strip */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="sticky top-14 md:top-16 z-30 bg-background/90 backdrop-blur-xl py-2">
                <div className="bg-card border border-border/60 p-1 rounded-lg flex flex-col lg:flex-row gap-1.5 shadow-sm">
                    <div className="relative flex-grow">
                        <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3 w-3 text-muted-foreground/50" />
                        <input 
                            placeholder="QUERY ARCHIVE..." 
                            value={searchQuery} 
                            onChange={(e) => setSearchQuery(e.target.value)} 
                            className="w-full h-8 pl-8 pr-3 rounded-md bg-muted/30 border-transparent focus:bg-background focus:ring-1 focus:ring-primary/20 text-[10px] font-black uppercase tracking-widest transition-all"
                        />
                    </div>

                    <div className="flex gap-1 overflow-x-auto scrollbar-hide items-center px-1">
                        {categories.map(c => (
                            <button 
                                key={c.v} 
                                onClick={() => setSelectedCategory(c.v)}
                                className={cn(
                                    "whitespace-nowrap h-8 px-3 rounded-md text-[8px] font-black uppercase tracking-widest transition-all border",
                                    selectedCategory === c.v ? "bg-primary text-white border-primary shadow-sm" : "bg-muted/30 border-transparent text-muted-foreground hover:bg-muted"
                                )}
                            >
                                {c.l}
                            </button>
                        ))}
                        <div className="w-px h-4 bg-border/40 mx-1"></div>
                        <div className="flex bg-muted/40 p-0.5 rounded-md shrink-0">
                            <button onClick={() => setViewMode("grid")} className={cn("p-1.5 rounded transition-all", viewMode==='grid'?'bg-white shadow-sm text-primary':'text-muted-foreground')}><Grid3X3 className="h-3.5 w-3.5" /></button>
                            <button onClick={() => setViewMode("list")} className={cn("p-1.5 rounded transition-all", viewMode==='list'?'bg-white shadow-sm text-primary':'text-muted-foreground')}><List className="h-3.5 w-3.5" /></button>
                        </div>
                    </div>
                </div>
            </motion.div>

            {/* Content Feed */}
            <div className={cn("grid gap-2", viewMode === 'grid' ? 'grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6' : 'grid-cols-1')}>
                <AnimatePresence mode="popLayout">
                    {filteredRecipes.length > 0 ? (
                        filteredRecipes.map((recipe) => (
                            <motion.div key={recipe.id} layout initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                                <CompactRecipeCard 
                                    recipe={recipe} 
                                    viewMode={viewMode} 
                                    onToggleFavorite={toggleFavorite} 
                                    pantryIngredients={ingredients} 
                                />
                            </motion.div>
                        ))
                    ) : (
                        <motion.div 
                            layout
                            className="col-span-full flex flex-col items-center justify-center py-24 bg-muted/5 border border-dashed border-border/40 rounded-3xl"
