const DashboardPage: React.FC = () => {
    const { recipes, ingredients, orders, updateIngredient } = useData();
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const timer = setTimeout(() => setLoading(false), 400);
        return () => clearTimeout(timer);
    }, []);

    const totalRevenue = useMemo(() => orders.filter(o => o.status === 'completed').reduce((sum, o) => sum + o.totalAmount, 0), [orders]);

    const { criticalStock, warningStock } = useMemo(() => {
        const critical = ingredients.filter(i => i.packagesInStock === 0);
        const warning = ingredients.filter(i => i.packagesInStock > 0 && i.packagesInStock <= 2);
        return { criticalStock: critical, warningStock: warning };
    }, [ingredients]);

    const activePrepItems = useMemo(() => {
        const counts: Record<string, { count: number, id: string }> = {};
        orders.filter(o => o.status === 'approved' || o.status === 'processing').forEach(order => {
            order.items.forEach(item => {
                if (!counts[item.recipeName]) {
                    counts[item.recipeName] = { count: 0, id: item.recipeId };
                }
                counts[item.recipeName].count += item.quantity;
            });
        });
        return Object.entries(counts)
            .map(([name, data]) => ({ name, ...data }))
            .sort((a, b) => b.count - a.count);
    }, [orders]);

    const topRecipes = useMemo(() => recipes.slice(0, 3), [recipes]);

    const handleQuickRestock = (item: any) => {
        const restockQty = 5;
        const updated = {
            ...item,
            packagesInStock: item.packagesInStock + restockQty,
            quantityInStock: (item.packagesInStock + restockQty) * item.packageSize,
            last_verified: new Date()
        };
        updateIngredient(updated);
    };

    if (loading) return (
        <div className="flex flex-col h-96 items-center justify-center gap-4">
            <Cpu className="animate-spin text-primary w-8 h-8" />
            <p className="text-[9px] font-black text-muted-foreground uppercase tracking-[0.3em]">Booting Core Terminal...</p>
        </div>
    );

    const dailyTarget = 5000;
    const progressPercent = Math.min(100, (totalRevenue / dailyTarget) * 100);

    return (
        <motion.div initial="hidden" animate="visible" variants={ANIMATION_VARIANTS.container} className="space-y-4 pb-24 max-w-6xl mx-auto px-4 md:px-0 font-sans">
            {/* Ultra-Condensed Status Header */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 border-b border-border/40 pb-4">
                <div className="flex items-center gap-3">
                    <div className="h-10 w-10 bg-primary/10 rounded-xl flex items-center justify-center border border-primary/20">
                        <Rocket className="h-5 w-5 text-primary" />
                    </div>
                    <div>
                        <h1 className="text-xl font-black tracking-tight text-foreground uppercase leading-none">Operations Console</h1>
                        <p className="text-[9px] font-black text-muted-foreground uppercase tracking-widest mt-1.5 flex items-center gap-2">
                            <Activity className="h-2.5 w-2.5 text-emerald-500 animate-pulse" /> Live Flux: Synchronized
                        </p>
                    </div>
                </div>

                <div className="bg-card border border-border/60 rounded-xl p-2.5 flex items-center gap-4 min-w-[280px] shadow-sm">
                    <div className="flex-1">
                        <div className="flex justify-between items-center mb-1.5 px-0.5">
                            <span className="text-[8px] font-black uppercase text-muted-foreground tracking-[0.2em] flex items-center gap-1.5">
                                <Target className="h-2.5 w-2.5 text-primary" /> Revenue Target
                            </span>
                            <span className="text-[8px] font-black text-primary uppercase tabular-nums">{Math.round(progressPercent)}%</span>
                        </div>
                        <div className="h-1.5 w-full bg-muted/40 rounded-full overflow-hidden border border-border/20">
                            <motion.div initial={{ width: 0 }} animate={{ width: `${progressPercent}%` }} className="h-full bg-primary shadow-[0_0_8px_rgba(var(--primary),0.4)]" />
                        </div>
                    </div>
                    <div className="text-right border-l border-border/40 pl-4">
                        <p className="text-sm font-black leading-none tabular-nums text-foreground">{formatCurrency(totalRevenue).split('.')[0]}</p>
                        <p className="text-[7px] font-black text-muted-foreground uppercase mt-1 tracking-tighter">Gross Realtime</p>
                    </div>
                </div>
            </motion.div>

            {/* Tactical Metric Strip */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="grid grid-cols-2 md:grid-cols-4 gap-2">
                <MetricStripItem icon={ChefHat} label="Culinary Library" value={recipes.length} color="text-blue-500" />
                <MetricStripItem icon={Warehouse} label="Pantry Assets" value={ingredients.length} color="text-emerald-500" />
                <MetricStripItem icon={ClipboardList} label="Active Missions" value={orders.filter(o=>o.status !== 'completed').length} color="text-orange-500" />
                <MetricStripItem icon={DollarSign} label="Daily Yield" value={formatCurrency(totalRevenue).split('.')[0]} color="text-purple-500" trend="12%" />
            </motion.div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-3">
                {/* Left: Service Queue */}
                <div className="lg:col-span-7 space-y-3">
                    <Card className="rounded-xl border-border/60 overflow-hidden shadow-sm h-full">
                        <CardHeader className="p-3 border-b border-border/40 bg-muted/20 flex flex-row items-center justify-between">
                            <CardTitle className="text-[10px] uppercase tracking-widest text-muted-foreground flex items-center gap-2 font-black">
                                <Activity className="h-3 w-3 text-primary" /> Active Service Queue
                            </CardTitle>
                            <Link to="/orders" className="text-[8px] font-black text-primary uppercase tracking-[0.2em] hover:brightness-110">Full Terminal <ChevronRight className="inline h-2 w-2" /></Link>
                        </CardHeader>
                        <CardContent className="p-0">
                            <div className="divide-y divide-border/30">
                                {activePrepItems.length > 0 ? (
                                    activePrepItems.map(item => (
                                        <div key={item.id} className="flex items-center justify-between py-2 px-4 hover:bg-muted/10 transition-colors group">
                                            <div className="flex items-center gap-4">
                                                <div className="h-9 w-9 rounded-lg bg-primary/5 text-primary flex items-center justify-center font-black text-sm border border-primary/20 shrink-0">
                                                    {item.count}
                                                </div>
                                                <div className="min-w-0">
                                                    <p className="text-[11px] font-black uppercase text-foreground truncate">{item.name}</p>
                                                    <p className="text-[8px] text-muted-foreground font-black uppercase tracking-tighter mt-0.5">Portions to fire</p>
                                                </div>
                                            </div>
                                            <Link 
                                                to={`/recipes/${item.id}/cook?servings=${item.count}`}
                                                className="h-8 px-4 rounded-lg bg-primary text-white hover:brightness-110 transition-all flex items-center gap-2 text-[9px] font-black uppercase tracking-widest shadow-md shadow-primary/20 active:scale-95"
