                                                <Timer className="h-3.5 w-3.5" /> Start
                                            </Link>
                                        </div>
                                    ))
                                ) : (
                                    <div className="py-16 text-center">
                                        <div className="h-10 w-10 bg-muted/20 rounded-full flex items-center justify-center mx-auto mb-3">
                                            <ClipboardList className="h-5 w-5 text-muted-foreground/30" />
                                        </div>
                                        <p className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.3em]">Queue Idle</p>
                                    </div>
                                )}
                            </div>
                        </CardContent>
                    </Card>
                </div>

                {/* Right: Critical Stats & Quick Links */}
                <div className="lg:col-span-5 space-y-3">
                    <Card className="rounded-xl border-border/60 overflow-hidden shadow-sm">
                        <CardHeader className="p-3 border-b border-border/40 bg-muted/20 flex flex-row items-center justify-between">
                            <CardTitle className="text-[10px] uppercase tracking-widest text-muted-foreground font-black flex items-center gap-2">
