                                </div>
                            ) : (
                                <div className="space-y-2">
                                    {[...criticalStock.slice(0, 2), ...warningStock.slice(0, 3)].map(item => {
                                        const isCritical = item.packagesInStock === 0;
                                        return (
                                            <div key={item.id} className="flex items-center justify-between p-2 rounded-lg bg-muted/20 border border-border/40 group hover:border-primary/20 transition-all">
                                                <div className="min-w-0 flex-1">
                                                    <div className="flex items-center gap-2 mb-1">
                                                        <div className={cn("h-1.5 w-1.5 rounded-full", isCritical ? "bg-red-500 animate-pulse" : "bg-orange-500")} />
                                                        <p className="text-[10px] font-black text-foreground truncate uppercase">{item.name}</p>
                                                    </div>
                                                    <p className={cn("text-[7px] font-black uppercase tracking-widest", isCritical ? "text-red-500" : "text-muted-foreground")}>
                                                        {isCritical ? "DEPLETED" : `${item.packagesInStock} ${item.packageUnit.slice(0,3)} REMAINING`}
                                                    </p>
                                                </div>
                                                <button 
                                                    onClick={() => handleQuickRestock(item)}
                                                    className={cn(
                                                        "h-7 w-7 rounded-md flex items-center justify-center transition-all active:scale-90 border shrink-0 shadow-sm",
                                                        isCritical ? "bg-red-500 text-white border-red-400" : "bg-white dark:bg-zinc-800 text-muted-foreground hover:text-primary border-border"
                                                    )}
                                                >
                                                    <Zap className="h-3.5 w-3.5 fill-current" />
                                                </button>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </CardContent>
                    </Card>

                    {/* Navigation Terminal Grid */}
                    <div className="grid grid-cols-2 gap-2">
                        {[
                            { to: '/recipes/new', icon: Plus, label: 'Add Entry', color: 'text-blue-500' },
                            { to: '/orders', icon: ShoppingCart, label: 'Terminal', color: 'text-amber-500' },
                            { to: '/pantry', icon: Warehouse, label: 'Vault', color: 'text-emerald-500' },
                            { to: '/analytics', icon: FileSearch, label: 'Audit', color: 'text-purple-500' }
                        ].map(link => (
                            <Link 
                                key={link.label}
                                to={link.to} 
                                className="group flex flex-col items-center justify-center p-4 rounded-xl border border-border/60 bg-card hover:border-primary/40 hover:bg-primary/5 transition-all shadow-sm"
                            >
                                <div className={cn("h-8 w-8 rounded-lg bg-muted/40 flex items-center justify-center mb-2 group-hover:scale-110 transition-transform border border-border/40", link.color)}>
                                    <link.icon className="h-4 w-4" />
                                </div>
                                <span className="text-[9px] font-black uppercase tracking-widest text-foreground">{link.label}</span>
                            </Link>
                        ))}
                    </div>

                    {/* Compact Leaderboard */}
                    <Card className="rounded-xl border-border/60 overflow-hidden shadow-sm">
                        <CardHeader className="p-3 border-b border-border/40 bg-muted/20">
                            <CardTitle className="text-[10px] uppercase tracking-widest text-muted-foreground font-black flex items-center gap-2">
                                <TrendingUp className="h-3 w-3 text-primary" /> Key Assets
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="p-1.5 space-y-1">
                            {topRecipes.map(recipe => (
                                <Link key={recipe.id} to={`/recipes/${recipe.id}`} className="flex items-center gap-3 p-2 rounded-lg hover:bg-muted/40 transition-all group border border-transparent hover:border-border/40">
                                    <div className="relative h-9 w-9 shrink-0 rounded-lg overflow-hidden bg-muted border border-border/30">
                                        <img src={recipe.imageUrl} className="h-full w-full object-cover grayscale-[0.5] group-hover:grayscale-0 transition-all duration-500" alt={recipe.name} />
                                    </div>
                                    <div className="min-w-0 flex-1">
                                        <p className="text-[10px] font-black truncate uppercase text-foreground leading-tight">{recipe.name}</p>
                                        <p className="text-[7px] font-black text-muted-foreground uppercase tracking-widest mt-1 opacity-60">{recipe.category} &bull; {recipe.cuisine}</p>
                                    </div>
                                    <ChevronRight className="h-3 w-3 text-muted-foreground/30 group-hover:text-primary transition-colors shrink-0" />
                                </Link>
                            ))}
                        </CardContent>
                    </Card>
                </div>
            </div>
        </motion.div>
    );
};

