import React, { useState, useEffect, useMemo } from 'react';
import { useData } from '../context/DataContext';
import { Card, CardHeader, CardTitle, CardContent } from '../components/ui/Card';
import { 
  UtensilsCrossed, Warehouse, ClipboardList, DollarSign, Plus, ChevronRight, 
  Activity, Package, LayoutGrid, FileSearch, 
  ChefHat, TrendingUp, Timer, ShoppingCart, AlertCircle, Zap, Target,
  Cpu, Rocket
} from 'lucide-react';
import { formatCurrency, cn, ANIMATION_VARIANTS } from '../lib/utils';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';

const MetricStripItem: React.FC<{ icon: any, label: string, value: string | number, color: string, trend?: string }> = React.memo(({ icon: Icon, label, value, color, trend }) => (
    <div className="bg-card border border-border/60 p-2.5 rounded-xl flex items-center justify-between group hover:border-primary/40 hover:bg-primary/[0.02] transition-all shadow-sm">
        <div className="flex items-center gap-2.5 min-w-0">
            <div className={cn("h-8 w-8 rounded-lg flex items-center justify-center bg-muted/40 border border-border/40 shrink-0 transition-colors group-hover:border-primary/30", color)}>
                <Icon className="h-4 w-4" />
            </div>
            <div className="min-w-0">
                <p className="text-[7px] font-black text-muted-foreground uppercase tracking-[0.2em] leading-none mb-1 group-hover:text-primary/70 transition-colors">{label}</p>
                <p className="text-sm font-black text-foreground tabular-nums leading-none truncate tracking-tight">{value}</p>
            </div>
        </div>
        {trend && <span className="text-[8px] font-black text-emerald-500 bg-emerald-500/10 px-1.5 py-0.5 rounded-md border border-emerald-500/20 ml-2">+{trend}</span>}
    </div>
));

const DashboardPage: React.FC = () => {
    const { recipes, ingredients, orders, updateIngredient } = useData();
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const timer = setTimeout(() => setLoading(false), 400);
        return () => clearTimeout(timer);
    }, []);

    const totalRevenue = useMemo(() => orders.filter(o => o.status === 'completed').reduce((sum, o) => sum + o.totalAmount, 0), [orders]);

    const { criticalStock, warningStock } = useMemo(() => {
        const critical = ingredients.filter(i => i.packagesInStock === 0);
        const warning = ingredients.filter(i => i.packagesInStock > 0 && i.packagesInStock <= 2);
        return { criticalStock: critical, warningStock: warning };
    }, [ingredients]);

    const activePrepItems = useMemo(() => {
        const counts: Record<string, { count: number, id: string }> = {};
        orders.filter(o => o.status === 'approved' || o.status === 'processing').forEach(order => {
            order.items.forEach(item => {
                if (!counts[item.recipeName]) {
                    counts[item.recipeName] = { count: 0, id: item.recipeId };
                }
                counts[item.recipeName].count += item.quantity;
            });
        });
        return Object.entries(counts)
            .map(([name, data]) => ({ name, ...data }))
            .sort((a, b) => b.count - a.count);
    }, [orders]);

    const topRecipes = useMemo(() => recipes.slice(0, 3), [recipes]);

    const handleQuickRestock = (item: any) => {
        const restockQty = 5;
        const updated = {
            ...item,
            packagesInStock: item.packagesInStock + restockQty,
            quantityInStock: (item.packagesInStock + restockQty) * item.packageSize,
            last_verified: new Date()
        };
        updateIngredient(updated);
    };

    if (loading) return (
        <div className="flex flex-col h-96 items-center justify-center gap-4">
            <div className="relative">
                <Cpu className="animate-spin text-primary w-10 h-10" />
                <div className="absolute inset-0 bg-primary/20 blur-xl animate-pulse rounded-full" />
            </div>
            <p className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.4em] animate-pulse">Initializing Control Console...</p>
        </div>
    );

    const dailyTarget = 5000;
    const progressPercent = Math.min(100, (totalRevenue / dailyTarget) * 100);

    return (
        <motion.div initial="hidden" animate="visible" variants={ANIMATION_VARIANTS.container} className="space-y-4 pb-24 max-w-6xl mx-auto px-4 md:px-0 font-sans">
            {/* Control Header */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 border-b border-border/40 pb-5">
                <div className="flex items-center gap-4">
                    <div className="h-11 w-11 bg-primary text-white rounded-xl flex items-center justify-center shadow-[0_0_20px_rgba(29,185,84,0.3)]">
                        <Rocket className="h-6 w-6" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-black tracking-tighter text-foreground uppercase leading-none">Operations Console</h1>
