import { Recipe, Ingredient } from "../types";
import { formatCurrency, cn, ANIMATION_VARIANTS } from "../lib/utils";
import { motion, AnimatePresence } from "framer-motion";

const categories = [
    { v: "All", l: "All" },
    { v: "Main Course", l: "Mains" },
    { v: "Appetizer", l: "Starters" },
    { v: "Dessert", l: "Sweets" },
    { v: "Beverage", l: "Drinks" }
];

const CompactRecipeCard: React.FC<{ 
    recipe: Recipe; 
    viewMode: 'grid' | 'list';
    onToggleFavorite: (recipe: Recipe) => void;
    pantryIngredients: Ingredient[];
}> = React.memo(({ recipe, viewMode, onToggleFavorite, pantryIngredients }) => {
    const navigate = useNavigate();

    const { pricePerPerson, difficultyColor } = useMemo(() => {
        let rawTotal = 0;
        recipe.ingredientSections?.forEach(sec => {
            sec.ingredients?.forEach(ing => {
                const pantryItem = pantryIngredients.find(pi => pi.id === ing.ingredientId);
                const unitCost = ing.manualCostPerUnit !== undefined ? ing.manualCostPerUnit : (pantryItem?.costPerUnit || 0);
                rawTotal += (ing.quantity * unitCost);
            });
        });
        const overhead = rawTotal * (recipe.overheadPercentage / 100);
        const profit = rawTotal * (recipe.profitMargin / 100);
        const totalMenuPrice = rawTotal + overhead + profit;
        const servings = recipe.servings || 1;

        const diffColors: Record<string, string> = {
            'Easy': 'text-emerald-500',
            'Medium': 'text-amber-500',
            'Hard': 'text-red-500'
        };

        return {
            pricePerPerson: totalMenuPrice / servings,
            difficultyColor: diffColors[recipe.difficulty] || 'text-muted-foreground'
        };
    }, [recipe, pantryIngredients]);

    const handleFavoriteClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        onToggleFavorite(recipe);
    };

    if (viewMode === 'list') {
        return (
            <motion.div 
                layout
                onClick={() => navigate(`/recipes/${recipe.id}`)}
                className="group flex flex-row items-center gap-4 p-2 bg-card border border-border/60 rounded-xl hover:border-primary/40 hover:bg-primary/[0.01] cursor-pointer transition-all active:scale-[0.99] shadow-sm relative overflow-hidden"
            >
                {recipe.isFavorite && <div className="absolute top-0 left-0 w-1 h-full bg-primary shadow-[0_0_8px_rgba(29,185,84,0.5)]" />}
                <div className="relative w-12 h-12 flex-shrink-0 rounded-lg overflow-hidden bg-muted border border-border/40 shadow-inner">
                    <img src={recipe.imageUrl} alt={recipe.name} className="w-full h-full object-cover transition-transform group-hover:scale-110" />
                </div>

                <div className="flex-grow min-w-0">
                    <div className="flex items-center gap-2">
                        <h3 className="font-black text-foreground text-xs truncate uppercase tracking-tight leading-none group-hover:text-primary transition-colors">{recipe.name}</h3>
                        {recipe.isFavorite && <Star className="h-3 w-3 fill-yellow-400 text-yellow-400 shrink-0" />}
                    </div>
                    <div className="flex items-center gap-2 mt-1.5 text-[8px] text-muted-foreground uppercase font-black tracking-[0.2em]">
                        <span className="bg-muted px-1.5 py-0.5 rounded-md border border-border/40">{recipe.category}</span>
                        <span className="text-primary/70">{recipe.cuisine}</span>
                    </div>
                </div>

                <div className="flex items-center gap-5 shrink-0 px-2">
                    <div className="hidden sm:flex items-center gap-1.5 text-[9px] font-black text-muted-foreground uppercase tracking-widest">
                        <Clock className="h-3 w-3" /> {recipe.prepTime + recipe.cookTime}M
                    </div>
                    <div className="text-right border-l border-border/40 pl-5">
                        <div className="text-xs font-black text-primary font-mono leading-none tracking-tight">{formatCurrency(pricePerPerson)}</div>
                        <div className="text-[7px] text-muted-foreground font-black uppercase tracking-widest mt-1 opacity-60">PRICE/SERV</div>
                    </div>
                </div>
            </motion.div>
        );
    }

    return (
        <motion.div 
            layout
            onClick={() => navigate(`/recipes/${recipe.id}`)}
            className="group bg-card rounded-2xl overflow-hidden cursor-pointer flex flex-col hover:border-primary/40 hover:shadow-xl hover:shadow-primary/5 transition-all border border-border/60 shadow-sm relative"
        >
            <div className="relative h-28 overflow-hidden border-b border-border/40">
                <img src={recipe.imageUrl} alt={recipe.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700 grayscale-[0.3] group-hover:grayscale-0" />
                <div className="absolute top-2 right-2">
                     <button onClick={handleFavoriteClick} className="h-7 w-7 bg-black/50 backdrop-blur-md rounded-lg text-white hover:bg-primary transition-all border border-white/10 shadow-lg">
                         <Star className={cn("h-3.5 w-3.5 transition-all", recipe.isFavorite && "fill-yellow-400 text-yellow-400 scale-110")} />
                    </button>
                </div>
                <div className="absolute bottom-2 left-2 flex gap-1">
                    <span className="text-[8px] font-black bg-black/60 backdrop-blur-md text-white px-2 py-1 rounded-md uppercase tracking-[0.2em] border border-white/10 shadow-lg">
                        {recipe.cuisine}
                    </span>
                </div>
            </div>

            <div className="p-3 flex flex-col flex-grow bg-gradient-to-b from-transparent to-primary/[0.02]">
                <h3 className="font-black text-[11px] uppercase tracking-tight line-clamp-1 group-hover:text-primary transition-colors leading-tight mb-3">{recipe.name}</h3>

                <div className="mt-auto space-y-3">
                    <div className="flex items-center justify-between text-[8px] font-black text-muted-foreground uppercase tracking-[0.2em]">
                        <div className="flex items-center gap-1.5 bg-muted/30 px-1.5 py-0.5 rounded border border-border/40">
                            <Clock className="h-2.5 w-2.5" /> {recipe.prepTime + recipe.cookTime}M
                        </div>
                        <div className={cn("flex items-center gap-1.5 px-1.5 py-0.5 rounded border border-current opacity-80", difficultyColor)}>
                            <Activity className="h-2.5 w-2.5" /> {recipe.difficulty}
                        </div>
                    </div>

                    <div className="pt-2.5 border-t border-border/40 flex items-center justify-between">
                        <div className="flex flex-col">
                            <span className="text-xs font-black text-foreground font-mono leading-none tracking-tight">{formatCurrency(pricePerPerson)}</span>
                            <span className="text-[7px] font-black text-muted-foreground uppercase tracking-[0.1em] mt-1">Cost unit</span>
                        </div>
                        <div className="h-8 w-8 rounded-xl bg-primary/10 text-primary flex items-center justify-center border border-primary/20 group-hover:bg-primary group-hover:text-white transition-all shadow-sm group-hover:shadow-primary/20">
                            <Plus className="h-4 w-4" />
                        </div>
                    </div>
                </div>
            </div>
        </motion.div>
    );
});

export default function RecipesPage() {
    const { recipes, updateRecipe, ingredients } = useData();
    const [searchQuery, setSearchQuery] = useState("");
    const [selectedCategory, setSelectedCategory] = useState("All");
    const [viewMode, setViewMode] = useState<"list" | "grid">("grid");

    const filteredRecipes = useMemo(() => {
        return recipes.filter(r => {
            const matchesSearch = r.name.toLowerCase().includes(searchQuery.toLowerCase());
            const matchesCategory = selectedCategory === "All" || r.category === selectedCategory;
            return matchesSearch && matchesCategory;
        }).sort((a, b) => {
            if (a.isFavorite && !b.isFavorite) return -1;
            if (!a.isFavorite && b.isFavorite) return 1;
            return 0;
        });
    }, [recipes, searchQuery, selectedCategory]);

    const toggleFavorite = useCallback((recipe: Recipe) => {
        updateRecipe({ ...recipe, isFavorite: !recipe.isFavorite });
