const DashboardPage: React.FC = () => {
    const { recipes, ingredients, orders, updateIngredient } = useData();
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const timer = setTimeout(() => setLoading(false), 500);
        return () => clearTimeout(timer);
    }, []);

    const totalRevenue = useMemo(() => orders.filter(o => o.status === 'completed').reduce((sum, o) => sum + o.totalAmount, 0), [orders]);

    const { criticalStock, warningStock } = useMemo(() => {
        const critical = ingredients.filter(i => i.packagesInStock === 0);
        const warning = ingredients.filter(i => i.packagesInStock > 0 && i.packagesInStock <= 2);
        return { criticalStock: critical, warningStock: warning };
    }, [ingredients]);

    const activePrepItems = useMemo(() => {
        const counts: Record<string, { count: number, id: string }> = {};
        orders.filter(o => o.status === 'approved' || o.status === 'processing').forEach(order => {
            order.items.forEach(item => {
                if (!counts[item.recipeName]) {
                    counts[item.recipeName] = { count: 0, id: item.recipeId };
                }
                counts[item.recipeName].count += item.quantity;
            });
        });
        return Object.entries(counts)
            .map(([name, data]) => ({ name, ...data }))
            .sort((a, b) => b.count - a.count);
    }, [orders]);

    if (loading) return (
        <div className="flex flex-col h-[60vh] items-center justify-center gap-6">
            <div className="relative">
                <div className="h-16 w-16 border-2 border-app-primary/20 border-t-app-primary rounded-full animate-spin" />
                <div className="absolute inset-0 flex items-center justify-center">
                    <div className="h-2 w-2 bg-app-primary rounded-full animate-pulse" />
                </div>
            </div>
            <p className="text-[11px] font-black text-app-muted uppercase tracking-[0.5em] animate-pulse">Synchronizing Core Array</p>
        </div>
    );

    const progressPercent = Math.min(100, (totalRevenue / 10000) * 100);

    return (
        <motion.div initial="hidden" animate="visible" variants={ANIMATION_VARIANTS.container} className="space-y-6 pb-24 max-w-7xl mx-auto px-4 md:px-0">
            {/* Header / Mission Status */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 border-b border-app-border pb-6">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <Crosshair className="h-6 w-6 text-app-primary" />
                        <h1 className="text-3xl font-black italic tracking-tighter uppercase text-foreground">Operational Dashboard</h1>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <div className="h-2 w-2 rounded-full bg-app-success animate-pulse" />
                            <span className="text-[10px] font-black uppercase text-app-muted tracking-widest">Grid Status: SECURE</span>
                        </div>
                        <div className="h-4 w-px bg-app-border" />
                        <div className="flex items-center gap-2 text-[10px] font-black uppercase text-app-primary tracking-widest">
                            <Activity className="h-3 w-3" /> Realtime Data Sync Active
                        </div>
                    </div>
                </div>

                <div className="bg-app-card border border-app-border p-4 rounded-sm min-w-[320px] relative overflow-hidden">
                    <div className="flex justify-between items-center mb-2">
                        <span className="text-[10px] font-black uppercase tracking-widest text-app-muted">Mission Quota Progress</span>
                        <span className="text-xs font-black italic text-app-primary">{Math.round(progressPercent)}%</span>
                    </div>
                    <div className="h-2 w-full bg-app-bg border border-app-border rounded-none overflow-hidden">
                        <motion.div 
                            initial={{ width: 0 }} 
                            animate={{ width: `${progressPercent}%` }} 
                            className="h-full bg-gradient-to-r from-app-primary to-app-success shadow-[0_0_10px_rgba(59,125,221,0.5)]" 
                        />
                    </div>
                    <div className="flex justify-between mt-2">
                        <span className="text-[9px] font-bold text-app-muted uppercase">Base: {formatCurrency(totalRevenue)}</span>
                        <span className="text-[9px] font-bold text-app-muted uppercase">Target: $10,000</span>
                    </div>
                </div>
            </motion.div>

            {/* Tactical Grid Metrics */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <TacticalMetric icon={ChefHat} label="Culinary Modules" value={recipes.length} color="text-app-primary" />
                <TacticalMetric icon={Warehouse} label="Asset Vault" value={ingredients.length} color="text-app-success" />
                <TacticalMetric icon={ClipboardList} label="Active Directives" value={orders.filter(o=>o.status !== 'completed').length} color="text-app-warning" />
                <TacticalMetric icon={DollarSign} label="Yield Realized" value={formatCurrency(totalRevenue).split('.')[0]} color="text-white" trend="18.4%" />
            </motion.div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                {/* Deployment Queue */}
                <motion.div variants={ANIMATION_VARIANTS.item} className="lg:col-span-8">
                    <div className="bg-app-card border border-app-border rounded-sm h-full flex flex-col border-t-2 border-t-app-primary">
                        <div className="p-5 border-b border-app-border flex justify-between items-center bg-white/[0.02]">
                            <h2 className="text-[12px] font-black uppercase tracking-[0.4em] text-foreground flex items-center gap-3">
                                <Zap className="h-4 w-4 text-app-primary" /> Task Execution Queue
                            </h2>
                            <Link to="/orders" className="text-[10px] font-black uppercase text-app-primary hover:underline flex items-center gap-1">Full Array <ChevronRight className="h-3 w-3"/></Link>
                        </div>
                        <div className="flex-1 overflow-y-auto">
                            {activePrepItems.length > 0 ? (
                                activePrepItems.map(item => (
                                    <div key={item.id} className="flex items-center justify-between p-5 border-b border-app-border hover:bg-white/[0.03] transition-colors group">
                                        <div className="flex items-center gap-6">
                                            <div className="h-12 w-12 bg-app-bg border border-app-border text-app-primary flex items-center justify-center font-black text-xl italic rounded-sm shadow-inner group-hover:border-app-primary/50 transition-all">
                                                {item.count}
                                            </div>
                                            <div className="min-w-0">
                                                <p className="text-sm font-black uppercase tracking-tight text-foreground truncate mb-1">{item.name}</p>
                                                <div className="flex items-center gap-2">
                                                    <span className="h-1.5 w-1.5 rounded-full bg-app-warning animate-pulse" />
                                                    <span className="text-[9px] font-bold text-app-muted uppercase tracking-widest">Awaiting Plating Sequence</span>
                                                </div>
                                            </div>
                                        </div>
                                        <Link 
                                            to={`/recipes/${item.id}/cook?servings=${item.count}`}
                                            className="bg-app-primary text-white h-10 px-6 rounded-sm text-[10px] font-black uppercase tracking-[0.2em] shadow-lg hover:brightness-110 active:scale-95 transition-all flex items-center gap-2"
                                        >
                                            <Rocket className="h-3.5 w-3.5" /> Initialize
                                        </Link>
                                    </div>
                                ))
                            ) : (
                                <div className="py-32 text-center">
                                    <Box className="h-12 w-12 text-app-muted/10 mx-auto mb-4" />
                                    <p className="text-[11px] font-black text-app-muted uppercase tracking-[0.5em]">No Pending Tasks</p>
                                </div>
                            )}
                        </div>
                    </div>
                </motion.div>

                {/* Logistics Radar */}
                <motion.div variants={ANIMATION_VARIANTS.item} className="lg:col-span-4 space-y-6">
                    <div className="bg-app-card border border-app-border rounded-sm border-t-2 border-t-app-warning overflow-hidden">
                        <div className="p-4 border-b border-app-border bg-white/[0.02] flex justify-between items-center">
                            <h2 className="text-[10px] font-black uppercase tracking-[0.3em] text-app-muted flex items-center gap-2">
                                <Shield className="h-3.5 w-3.5 text-app-warning" /> Asset Integrity
                            </h2>
                            <Link to="/pantry" className="text-[9px] font-bold text-app-muted uppercase tracking-widest hover:text-foreground">Vault</Link>
                        </div>
                        <div className="p-4 space-y-3">
                            {[...criticalStock.slice(0, 2), ...warningStock.slice(0, 3)].map(item => {
                                const isCritical = item.packagesInStock === 0;
                                return (
                                    <div key={item.id} className="flex items-center justify-between p-3 bg-app-bg border border-app-border rounded-sm group hover:border-app-primary/20 transition-all">
                                        <div className="min-w-0 flex-1">
                                            <div className="flex items-center gap-2 mb-1.5">
                                                <div className={cn("h-2 w-2 rounded-full", isCritical ? "bg-app-warning animate-pulse shadow-[0_0_8px_#fcb92c]" : "bg-app-primary")} />
                                                <p className="text-[11px] font-black uppercase tracking-tight text-foreground truncate">{item.name}</p>
                                            </div>
                                            <p className={cn("text-[9px] font-bold uppercase tracking-widest", isCritical ? "text-app-warning" : "text-app-muted")}>
                                                {isCritical ? "ZERO ASSETS REMAINING" : `${item.packagesInStock} ${item.packageUnit.toUpperCase()} IN STORAGE`}
                                            </p>
                                        </div>
                                        <button className="h-8 w-8 bg-app-card border border-app-border text-app-muted hover:text-app-primary hover:border-app-primary/30 rounded-sm flex items-center justify-center transition-all active:scale-90">
                                            <Plus className="h-4 w-4" />
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    </div>

                    {/* Fast-Access Terminal */}
                    <div className="grid grid-cols-2 gap-4">
                        {[
                            { to: '/recipes/new', icon: Plus, label: 'New Module', color: 'text-app-primary' },
                            { to: '/orders', icon: ShoppingCart, label: 'Terminal', color: 'text-app-warning' },
                            { to: '/pantry', icon: Warehouse, label: 'The Vault', color: 'text-app-success' },
                            { to: '/analytics', icon: FileSearch, label: 'Audits', color: 'text-app-muted' }
                        ].map(link => (
                            <Link 
                                key={link.label}
                                to={link.to} 
                                className="bg-app-card border border-app-border p-6 rounded-sm flex flex-col items-center justify-center gap-4 hover:border-app-primary/40 hover:bg-white/[0.02] transition-all shadow-sm group"
