import React, { useState, useMemo, useCallback } from 'react';
import { useData } from '../context/DataContext';
import { Search, PlusCircle, Layers, CheckSquare, X, LayoutGrid, List as ListIcon, Group, Trash2, Boxes, Activity, Warehouse, ShieldAlert, Crosshair, Package } from 'lucide-react';
import { formatCurrency, cn } from '../lib/utils';
import { AnimatePresence, motion } from 'framer-motion';
import { Ingredient } from '../types';
import { BatchUpdateModal } from '../components/pantry/BatchUpdateModal';
import { AddIngredientModal } from '../components/pantry/AddIngredientModal';
import { EditIngredientModal } from '../components/pantry/EditIngredientModal';
import { PantryItemCard } from '../components/pantry/PantryItemCard';

const CATEGORIES = ["Protein", "Vegetable", "Fruit", "Grains", "Dairy", "Spices", "Oils & Fats", "Baking", "Condiments", "Beverage", "Other"];

const PantryPage: React.FC = () => {
    const { ingredients, addIngredient, updateIngredient, deleteIngredient } = useData();
    const [searchQuery, setSearchQuery] = useState("");
    const [filterCategory, setFilterCategory] = useState("All");

    const [viewMode, setViewMode] = useState<'grid' | 'list'>('list');
    const [groupByCategory, setGroupByCategory] = useState(false);
    const [sortBy, setSortBy] = useState<'name' | 'stock' | 'cost'>('stock');

    const [showAddModal, setShowAddModal] = useState(false);
    const [editingIngredient, setEditingIngredient] = useState<Ingredient | null>(null);

    const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
    const [showBatchModal, setShowBatchModal] = useState(false);
    const [isSelectionMode, setIsSelectionMode] = useState(false);

    const totalValue = ingredients.reduce((sum, item) => sum + (item.costPerPackage * item.packagesInStock), 0);
    const lowStockCount = ingredients.filter(i => i.packagesInStock <= 2).length;

    const filteredIngredients = useMemo(() => {
        let items = ingredients.filter(item => {
            const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase());
            const matchesCategory = filterCategory === "All" || item.category === filterCategory;
            return matchesSearch && matchesCategory;
        });

        return items.sort((a, b) => {
            if (sortBy === 'name') return a.name.localeCompare(b.name);
            if (sortBy === 'stock') return a.packagesInStock - b.packagesInStock;
            if (sortBy === 'cost') return b.costPerUnit - a.costPerUnit;
            return 0;
        });
    }, [ingredients, searchQuery, filterCategory, sortBy]);

    const groupedIngredients: Record<string, Ingredient[]> = useMemo(() => {
        if (!groupByCategory) return { 'Main Inventory': filteredIngredients };
        return filteredIngredients.reduce((groups, item) => {
            const cat = item.category || 'Other';
            if (!groups[cat]) groups[cat] = [];
            groups[cat].push(item);
            return groups;
        }, {} as Record<string, Ingredient[]>);
    }, [filteredIngredients, groupByCategory]);

    return (
        <div className="space-y-6 max-w-7xl mx-auto pb-24 px-4 md:px-0 font-sans">
            {/* Header Area */}
            <div className="flex flex-col lg:flex-row lg:items-end justify-between gap-6 border-b border-app-border pb-6">
                <div className="space-y-2">
                    <div className="flex items-center gap-3">
                        <Warehouse className="h-6 w-6 text-app-primary" />
                        <h1 className="text-3xl font-black italic tracking-tighter uppercase text-foreground">Asset Vault</h1>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <span className="h-2 w-2 rounded-full bg-app-success animate-pulse" />
                            <span className="text-[10px] font-black uppercase text-app-muted tracking-[0.2em]">Master Ledger Synced</span>
                        </div>
                    </div>
                </div>

                <div className="flex gap-4">
                    <div className="bg-app-card border border-app-border px-6 py-3 rounded-sm flex flex-col">
                        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-app-muted mb-1">Vault Value</span>
                        <span className="text-xl font-black italic tabular-nums text-foreground">{formatCurrency(totalValue).split('.')[0]}</span>
                    </div>
                    <div className="bg-app-card border border-app-border px-6 py-3 rounded-sm flex flex-col">
                        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-app-warning mb-1">Critical SKUs</span>
                        <span className="text-xl font-black italic tabular-nums text-app-warning">{lowStockCount}</span>
                    </div>
                    <button 
                        onClick={() => setShowAddModal(true)}
                        className="bg-app-primary text-white px-8 h-full rounded-sm text-[11px] font-black uppercase tracking-[0.2em] shadow-lg hover:brightness-110 transition-all flex items-center gap-3"
                    >
                        <PlusCircle className="h-4 w-4" /> New Entry
                    </button>
                </div>
            </div>

            {/* Control Strip */}
            <div className="sticky top-14 md:top-16 z-30 bg-app-bg/95 backdrop-blur-md py-4">
                <div className="bg-app-card border border-app-border p-2 rounded-sm flex flex-col lg:flex-row gap-3 shadow-md">
                    <div className="relative flex-grow">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-app-muted" />
                        <input 
                            placeholder="QUERY ARCHIVE BY SKU OR NAME..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-12 pr-4 h-12 rounded-sm bg-app-bg border border-app-border focus:ring-1 focus:ring-app-primary text-xs font-bold uppercase tracking-widest placeholder:text-app-muted/30"
                        />
                    </div>

                    <div className="flex items-center gap-2 px-1">
                        <select 
                            value={filterCategory}
                            onChange={(e) => setFilterCategory(e.target.value)}
                            className="h-12 px-4 rounded-sm bg-app-bg border border-app-border text-[10px] font-black uppercase tracking-widest focus:ring-1 focus:ring-app-primary appearance-none cursor-pointer min-w-[160px] text-center"
                        >
                            <option value="All">All Sectors</option>
                            {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>

                        <div className="h-12 w-px bg-app-border mx-1 hidden lg:block" />

                        <div className="flex bg-app-bg p-1 rounded-sm border border-app-border">
                            <button onClick={() => setViewMode('grid')} className={cn("p-2.5 rounded-sm transition-all", viewMode==='grid' ? "bg-app-primary text-white" : "text-app-muted hover:bg-white/5")}>
                                <LayoutGrid className="h-4 w-4" />
                            </button>
                            <button onClick={() => setViewMode('list')} className={cn("p-2.5 rounded-sm transition-all", viewMode==='list' ? "bg-app-primary text-white" : "text-app-muted hover:bg-white/5")}>
                                <ListIcon className="h-4 w-4" />
                            </button>
                        </div>

                         <button 
                            onClick={() => setIsSelectionMode(!isSelectionMode)}
                            className={cn("h-12 px-5 rounded-sm text-[10px] font-black uppercase tracking-widest flex items-center gap-2 border transition-all", isSelectionMode ? "bg-app-primary text-white border-app-primary" : "bg-app-bg text-app-muted border-app-border hover:bg-white/5")}
                        >
                            <CheckSquare className="h-4 w-4" /> Marks
                        </button>
                    </div>
                </div>
            </div>

            {/* Asset Grid */}
            <div className="min-h-[500px]">
                {Object.entries(groupedIngredients).map(([groupName, groupItems]) => (
                    <div key={groupName} className="mb-10">
                        <div className="flex items-center gap-4 mb-4 px-2">
                            <h3 className="font-black text-[12px] italic uppercase tracking-[0.5em] text-app-muted">{groupName}</h3>
                            <div className="h-px flex-1 bg-app-border" />
                            <span className="text-[10px] font-black text-app-primary uppercase tabular-nums">DATA_POINTS: {groupItems.length}</span>
                        </div>

                        <div className={cn(
                            "grid gap-4", 
                            viewMode === 'grid' ? "grid-cols-2 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6" : "grid-cols-1"
                        )}>
                            {groupItems.map(item => (
                                <PantryItemCard 
                                    key={item.id}
                                    item={item} 
                                    onEdit={setEditingIngredient}
                                    isSelected={selectedIds.has(item.id)}
                                    isSelectionMode={isSelectionMode}
                                    onToggleSelect={(id) => {
                                        setSelectedIds(prev => {
                                            const next = new Set(prev);
                                            if (next.has(id)) next.delete(id);
                                            else next.add(id);
                                            return next;
                                        });
                                    }}
                                    onUpdate={updateIngredient}
                                    viewMode={viewMode}
                                />
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            {/* Float Command Bar */}
            <AnimatePresence>
                {selectedIds.size > 0 && (
                    <motion.div 
                        initial={{ y: 100, opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: 100, opacity: 0 }}
                        className="fixed bottom-10 left-1/2 -translate-x-1/2 z-50 bg-app-bg border border-app-primary/50 text-white px-8 py-4 rounded-sm shadow-2xl flex items-center gap-8"
                    >
                        <div className="flex flex-col">
                            <span className="text-[8px] font-black uppercase text-app-primary tracking-widest">Active Selections</span>
                            <span className="text-lg font-black italic">{selectedIds.size} SKUs</span>
                        </div>
                        <div className="h-8 w-px bg-app-border" />
                        <div className="flex gap-2">
                             <button onClick={() => setShowBatchModal(true)} className="h-10 px-6 rounded-sm bg-app-card border border-app-border text-[10px] font-black uppercase tracking-widest hover:border-app-primary transition-all flex items-center gap-2">
                                <Layers className="h-3.5 w-3.5" /> Re-Batch
                            </button>
                            <button className="h-10 px-6 rounded-sm bg-red-900/30 border border-red-900/50 text-red-400 text-[10px] font-black uppercase tracking-widest hover:bg-red-900/50 transition-all flex items-center gap-2">
                                <Trash2 className="h-3.5 w-3.5" /> Purge
                            </button>
                        </div>
                        <button onClick={() => setSelectedIds(new Set())} className="p-2 hover:bg-white/5 transition-colors">
                            <X className="h-4 w-4 text-app-muted" />
                        </button>
                    </motion.div>
                )}
            </AnimatePresence>

            {showAddModal && <AddIngredientModal onClose={() => setShowAddModal(false)} onSave={(ni) => { addIngredient(ni); setShowAddModal(false); }} />}
            {editingIngredient && <EditIngredientModal ingredient={editingIngredient} onClose={() => setEditingIngredient(null)} onSave={(ui) => { updateIngredient(ui); setEditingIngredient(null); }} />}
            {showBatchModal && <BatchUpdateModal count={selectedIds.size} onClose={() => setShowBatchModal(false)} onSave={(op, val) => { /* implementation */ setShowBatchModal(false); }} />}
        </div>
    );
};

