            </div>
            <p className="text-[11px] font-bold uppercase tracking-[0.4em] text-app-muted animate-pulse">Initializing Command Console...</p>
        </div>
    );

    const targetRevenue = 10000;
    const progressPercent = Math.min(100, (totalRevenue / targetRevenue) * 100);

    return (
        <motion.div initial="hidden" animate="visible" variants={ANIMATION_VARIANTS.container} className="space-y-6 pb-24 max-w-7xl mx-auto px-4 md:px-0">
            {/* Mission Header */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="flex flex-col lg:flex-row lg:items-end justify-between gap-6 border-b border-app-border pb-6">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <Crosshair className="h-6 w-6 text-app-primary" />
                        <h1 className="text-3xl font-black italic tracking-tighter text-app-text uppercase">Operations Center</h1>
                    </div>
                    <div className="flex items-center gap-4">
                        <div className="flex items-center gap-2">
                            <span className="h-1.5 w-1.5 rounded-full bg-app-success animate-pulse shadow-[0_0_8px_#1cbb8c]"></span>
                            <span className="text-[10px] font-bold uppercase text-app-muted tracking-[0.2em]">Grid Status: Operational</span>
                        </div>
                        <div className="h-4 w-px bg-app-border"></div>
                        <span className="text-[10px] font-bold uppercase text-app-primary tracking-widest flex items-center gap-2">
                            <Activity className="h-3 w-3" /> Realtime Data Link Active
                        </span>
                    </div>
                </div>

                <div className="bg-app-card border border-app-border p-4 rounded-sm min-w-[320px] shadow-lg relative overflow-hidden group">
                    <div className="absolute -top-6 -right-6 h-20 w-20 text-white/[0.02] group-hover:rotate-12 transition-transform">
                        <Target className="h-full w-full" />
                    </div>
                    <div className="flex justify-between items-center mb-3">
                        <span className="text-[10px] font-bold uppercase tracking-widest text-app-muted">Mission Quota: {Math.round(progressPercent)}%</span>
                        <span className="text-[10px] font-black italic text-app-primary">EST. $10.0K</span>
                    </div>
                    <div className="h-1.5 w-full bg-app-bg border border-white/5 rounded-none overflow-hidden">
                        <motion.div 
                            initial={{ width: 0 }} 
                            animate={{ width: `${progressPercent}%` }} 
                            className="h-full bg-gradient-to-r from-app-primary to-app-success shadow-[0_0_10px_rgba(59,125,221,0.5)]" 
                        />
                    </div>
                </div>
            </motion.div>

            {/* Top Grid Metrics */}
            <motion.div variants={ANIMATION_VARIANTS.item} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                <MetricTactical icon={ChefHat} label="Culinary Modules" value={recipes.length} color="text-app-primary" />
                <MetricTactical icon={Warehouse} label="Asset Vault" value={ingredients.length} color="text-app-success" />
                <MetricTactical icon={ClipboardList} label="Directives" value={orders.filter(o=>o.status !== 'completed').length} color="text-app-warning" trend="12%" />
