            {/* Main Command Grid (12-Column Pattern) */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                {/* Content Area (8 Columns) */}
                <motion.div variants={ANIMATION_VARIANTS.item} className="lg:col-span-8 space-y-6">
