                                                        <span className="text-[10px] font-bold uppercase tracking-widest text-app-muted">Awaiting Station Assignment</span>
                                                    </div>
                                                </div>
                                            </div>
                                            <Link 
                                                to={`/recipes/${item.id}/cook?servings=${item.count}`}
                                                className="bg-app-primary text-white h-10 px-6 rounded-sm text-[10px] font-black uppercase tracking-[0.2em] shadow-lg hover:brightness-110 active:scale-95 transition-all flex items-center gap-2"
                                            >
                                                <Rocket className="h-3.5 w-3.5" /> Initialize
                                            </Link>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <div className="py-32 flex flex-col items-center justify-center opacity-30">
                                    <Box className="h-12 w-12 mb-4" />
                                    <p className="text-[10px] font-bold uppercase tracking-[0.4em]">Grid Static: No Active Orders</p>
                                </div>
                            )}
                        </CardContent>
                    </Card>
                </motion.div>

                {/* Sidebar/Stats (4 Columns) */}
                <motion.div variants={ANIMATION_VARIANTS.item} className="lg:col-span-4 space-y-6">
                    {/* Integrity Section */}
                    <Card className="border-t-2 border-t-app-warning">
                        <CardHeader className="bg-white/[0.02]">
                            <div className="flex items-center gap-3">
                                <Shield className="h-4 w-4 text-app-warning" />
                                <CardTitle>Vault Integrity</CardTitle>
                            </div>
                        </CardHeader>
                        <CardContent className="p-4 space-y-3">
                            {[...criticalStock.slice(0, 2), ...warningStock.slice(0, 3)].map(item => {
                                const isCritical = item.packagesInStock === 0;
                                return (
                                    <div key={item.id} className="p-3 bg-app-bg border border-app-border rounded-sm group hover:border-app-primary transition-all">
                                        <div className="flex items-center justify-between mb-2">
                                            <div className="flex items-center gap-2">
