                                            <div 
                                                className={cn("h-full transition-all duration-1000", isCritical ? "bg-app-warning" : "bg-app-primary")}
                                                style={{ width: `${Math.min(100, (item.packagesInStock / 10) * 100)}%` }}
                                            ></div>
                                        </div>
                                    </div>
                                );
                            })}
                        </CardContent>
                    </Card>

                    {/* Quick Access Grid */}
                    <div className="grid grid-cols-2 gap-4">
                        {[
                            { to: '/recipes/new', icon: Plus, label: 'Add Asset', color: 'text-app-primary' },
