                            { to: '/settings', icon: Cpu, label: 'Config', color: 'text-app-warning' }
                        ].map(link => (
                            <Link 
                                key={link.label}
                                to={link.to} 
                                className="bg-app-card border border-app-border p-6 rounded-sm flex flex-col items-center justify-center gap-3 hover:border-app-primary hover:bg-white/[0.02] transition-all group"
                            >
                                <div className={cn("h-10 w-10 rounded-sm bg-app-bg border border-app-border flex items-center justify-center group-hover:scale-110 group-hover:border-app-primary transition-all", link.color)}>
