                            <span className="text-[8px] font-black uppercase text-app-primary tracking-widest leading-none mb-1">Marked Units</span>
                            <span className="text-xl font-black italic tabular-nums leading-none">{selectedIds.size}</span>
                         </div>

                        <div className="h-8 w-px bg-white/10 mx-2"></div>

                        <div className="flex-1 flex items-center gap-4">
                            <button onClick={() => setShowBatchModal(true)} className="flex-1 h-11 bg-app-bg border border-app-border text-[9px] font-black uppercase tracking-[0.2em] rounded-sm hover:text-app-primary transition-all flex items-center justify-center gap-2">
                                <Layers className="h-4 w-4" /> Adjust Qty
                            </button>
                            <button onClick={handleBatchDelete} className="flex-1 h-11 bg-red-900/20 border border-red-500/30 text-red-500 text-[9px] font-black uppercase tracking-[0.2em] rounded-sm hover:bg-red-500 hover:text-white transition-all flex items-center justify-center gap-2">
