                </div>
            </div>

            <div className="h-px bg-white/5"></div>

            {/* Inventory Group */}
            <div className="space-y-4">
                <div className="flex items-center gap-3">
                    <DollarSign className="h-4 w-4 text-app-primary" />
                    <h3 className="text-[10px] font-black uppercase text-app-muted tracking-[0.4em]">Inventory Calibration</h3>
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-app-muted tracking-widest block ml-1">Operational Stock</label>
                        <input type="number" name="packagesInStock" value={formData.packagesInStock} onChange={handleChange} className="w-full h-12 px-4 rounded-sm bg-app-bg border border-app-border focus:border-app-primary text-sm font-black italic tabular-nums" required />
                    </div>
                     <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-app-muted tracking-widest block ml-1">Mkt_Pack_Cost</label>
                        <div className="relative">
                            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-xs font-black text-app-muted">$</span>
                            <input type="number" name="costPerPackage" value={formData.costPerPackage} onChange={handleChange} className="w-full h-12 pl-8 pr-4 rounded-sm bg-app-bg border border-app-border focus:border-app-primary text-sm font-black italic tabular-nums" required />
