import React, { useState, useEffect, useMemo, useCallback } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Grid3X3, List, Plus, SlidersHorizontal, X, ChefHat, Star, Clock, Flame, Download, Upload, Loader2, Search, FileSpreadsheet, Utensils, Activity, BookOpen, Layers, Crosshair, Shield } from "lucide-react";
import { useData } from "../context/DataContext";
import { Recipe, Ingredient } from "../types";
import { formatCurrency, cn, ANIMATION_VARIANTS } from "../lib/utils";
import { motion, AnimatePresence } from "framer-motion";

const categories = [
    { v: "All", l: "All Sectors" },
    { v: "Main Course", l: "Mains" },
    { v: "Appetizer", l: "Start" },
    { v: "Dessert", l: "Sweet" },
    { v: "Beverage", l: "Drink" }
];

const CompactRecipeCard: React.FC<{ 
    recipe: Recipe; 
    viewMode: 'grid' | 'list';
    onToggleFavorite: (recipe: Recipe) => void;
    pantryIngredients: Ingredient[];
}> = React.memo(({ recipe, viewMode, onToggleFavorite, pantryIngredients }) => {
    const navigate = useNavigate();

    const { pricePerPerson, difficultyColor } = useMemo(() => {
        let rawTotal = 0;
        recipe.ingredientSections?.forEach(sec => {
            sec.ingredients?.forEach(ing => {
                const pantryItem = pantryIngredients.find(pi => pi.id === ing.ingredientId);
                const unitCost = ing.manualCostPerUnit !== undefined ? ing.manualCostPerUnit : (pantryItem?.costPerUnit || 0);
                rawTotal += (ing.quantity * unitCost);
            });
        });
        const overhead = rawTotal * (recipe.overheadPercentage / 100);
        const profit = rawTotal * (recipe.profitMargin / 100);
        const totalMenuPrice = rawTotal + overhead + profit;
        const servings = recipe.servings || 1;

        const diffColors: Record<string, string> = {
            'Easy': 'text-app-success',
            'Medium': 'text-app-warning',
            'Hard': 'text-red-500'
        };

        return {
            pricePerPerson: totalMenuPrice / servings,
            difficultyColor: diffColors[recipe.difficulty] || 'text-app-muted'
        };
    }, [recipe, pantryIngredients]);

    const handleFavoriteClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        onToggleFavorite(recipe);
    };

    if (viewMode === 'list') {
        return (
            <motion.div 
                layout
                onClick={() => navigate(`/recipes/${recipe.id}`)}
                className="group flex flex-row items-center gap-4 p-3 bg-app-card border border-app-border rounded-sm hover:border-app-primary/40 hover:bg-white/[0.02] cursor-pointer transition-all active:scale-[0.99] shadow-sm relative overflow-hidden"
            >
                {recipe.isFavorite && <div className="absolute top-0 left-0 w-1 h-full bg-app-primary shadow-[0_0_8px_#3b7ddd]" />}
                <div className="relative w-16 h-12 flex-shrink-0 rounded-sm overflow-hidden bg-app-bg border border-white/5">
                    <img src={recipe.imageUrl} alt={recipe.name} className="w-full h-full object-cover opacity-60 group-hover:opacity-100 transition-all" />
                </div>

                <div className="flex-grow min-w-0">
                    <div className="flex items-center gap-3">
                        <h3 className="font-black text-app-text text-sm truncate uppercase tracking-tight group-hover:text-app-primary transition-colors">{recipe.name}</h3>
                        {recipe.isFavorite && <Star className="h-3 w-3 fill-app-warning text-app-warning shrink-0" />}
                    </div>
                    <div className="flex items-center gap-3 mt-1 text-[8px] font-bold text-app-muted uppercase tracking-[0.2em]">
                        <span className="bg-app-bg px-1.5 py-0.5 rounded-sm border border-white/5">{recipe.category}</span>
                        <span>{recipe.cuisine}</span>
                    </div>
