import React, { useState, useEffect, useMemo, useCallback } from "react";
import { Link, useNavigate } from "react-router-dom";
import { Grid3X3, List, Plus, Star, Clock, Activity, Search, Layers, Crosshair, Shield, Zap, Target } from "lucide-react";
import { useData } from "../context/DataContext";
import { Recipe, Ingredient } from "../types";
import { formatCurrency, cn, ANIMATION_VARIANTS } from "../lib/utils";
import { motion, AnimatePresence } from "framer-motion";

const categories = [
    { v: "All", l: "ALL SECTORS" },
    { v: "Main Course", l: "MAINS" },
    { v: "Appetizer", l: "STARTS" },
    { v: "Dessert", l: "SWEETS" },
    { v: "Beverage", l: "DRINKS" }
];

const CompactRecipeCard: React.FC<{ 
    recipe: Recipe; 
    viewMode: 'grid' | 'list';
    onToggleFavorite: (recipe: Recipe) => void;
    pantryIngredients: Ingredient[];
}> = React.memo(({ recipe, viewMode, onToggleFavorite, pantryIngredients }) => {
    const navigate = useNavigate();

    const { pricePerPerson, difficultyColor } = useMemo(() => {
        let rawTotal = 0;
        recipe.ingredientSections?.forEach(sec => {
            sec.ingredients?.forEach(ing => {
                const pantryItem = pantryIngredients.find(pi => pi.id === ing.ingredientId);
                const unitCost = ing.manualCostPerUnit !== undefined ? ing.manualCostPerUnit : (pantryItem?.costPerUnit || 0);
                rawTotal += (ing.quantity * unitCost);
            });
        });
        const overhead = rawTotal * (recipe.overheadPercentage / 100);
        const profit = rawTotal * (recipe.profitMargin / 100);
        const totalMenuPrice = rawTotal + overhead + profit;
        const servings = recipe.servings || 1;

        const diffColors: Record<string, string> = {
            'Easy': 'text-app-success',
            'Medium': 'text-app-warning',
            'Hard': 'text-app-danger'
        };

        return {
            pricePerPerson: totalMenuPrice / servings,
            difficultyColor: diffColors[recipe.difficulty] || 'text-app-muted'
        };
    }, [recipe, pantryIngredients]);

    const handleFavoriteClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        onToggleFavorite(recipe);
    };

    if (viewMode === 'list') {
        return (
            <motion.div 
                layout
                onClick={() => navigate(`/recipes/${recipe.id}`)}
                className="group flex flex-row items-center gap-4 p-3 bg-app-card/60 backdrop-blur-md border border-app-border rounded-md hover:border-app-primary/40 hover:bg-white/[0.02] cursor-pointer transition-all active:scale-[0.99] shadow-sm relative overflow-hidden"
            >
                {recipe.isFavorite && <div className="absolute top-0 left-0 w-1 h-full bg-app-primary shadow-[0_0_12px_#10b981]" />}
                <div className="relative w-20 h-14 flex-shrink-0 rounded-sm overflow-hidden bg-app-bg border border-white/5">
